return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'kn_IN','project-id-version'=>'Events Manager','pot-creation-date'=>'2026-11-16T04:45:03+00:00','po-revision-date'=>'2026-11-15 04:52:17+0000','x-generator'=>'Pixelite GlotPress Sync','messages'=>[' Maximum size permitted by WordPress is %s.'=>' WordPress ಅನುಮತಿಸುವ ಗರಿಷ್ಠ ಗಾತ್ರ %s.',' is required.'=>' ಅಗತ್ಯವಿದೆ.','"%1$s" could not be created: %2$s'=>'"%1$s" ಅನ್ನು ರಚಿಸಲಾಗಲಿಲ್ಲ: %2$s','"%1$s" is not a field. Fields: %2$s.'=>'"%1$s" ಒಂದು ಕ್ಷೇತ್ರವಲ್ಲ. ಕ್ಷೇತ್ರಗಳು: %2$s.','"%s" is neither a media ID nor a web address that can be reached.'=>'"%s" ಮೀಡಿಯಾ ID ಅಲ್ಲ ಅಥವಾ ತಲುಪಬಹುದಾದ ವೆಬ್ ವಿಳಾಸವೂ ಅಲ್ಲ.','"All events" link text'=>'"ಎಲ್ಲಾ ಈವೆಂಟ್‌ಗಳು" ಲಿಂಕ್ ಪಠ್ಯ','#s will be replaced by the date format below'=>'#s ಅನ್ನು ಕೆಳಗಿನ ದಿನಾಂಕದ ನಮೂನೆಯಿಂದ ಬದಲಾಯಿಸಲಾಗುತ್ತದೆ','%1$s could not be updated yet, and Events Manager will keep retrying in the background: %2$s'=>'%1$s ಅನ್ನು ಇನ್ನೂ ಅಪ್‌ಡೇಟ್ ಮಾಡಲಾಗಲಿಲ್ಲ, Events Manager ಹಿನ್ನೆಲೆಯಲ್ಲಿ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸುತ್ತಲೇ ಇರುತ್ತದೆ: %2$s','%1$s of %2$s'=>'%2$s ರಲ್ಲಿ %1$s','%1$s recommends %2$s version %3$s or greater installed. Earlier versions may cause unexpected issues.'=>'%1$s ಗೆ %2$s ಆವೃತ್ತಿ %3$s ಅಥವಾ ಹೆಚ್ಚಿನದನ್ನು ಸ್ಥಾಪಿಸಲು ಶಿಫಾರಸು ಮಾಡಲಾಗಿದೆ. ಹಿಂದಿನ ಆವೃತ್ತಿಗಳು ಅನಿರೀಕ್ಷಿತ ಸಮಸ್ಯೆಗಳನ್ನು ಉಂಟುಮಾಡಬಹುದು.','%1$s requires %2$s version %3$s or greater installed.'=>'%1$s ಗೆ %2$s ಆವೃತ್ತಿ %3$s ಅಥವಾ ಹೆಚ್ಚಿನದನ್ನು ಸ್ಥಾಪಿಸುವುದು ಅಗತ್ಯ.','%1$s was updated, but the result could not be stored: %2$s'=>'%1$s ಅಪ್‌ಡೇಟ್ ಆಗಿದೆ, ಆದರೆ ಫಲಿತಾಂಶವನ್ನು ಸಂಗ್ರಹಿಸಲಾಗಲಿಲ್ಲ: %2$s','%1$s will be set up automatically on %2$s.'=>'%1$s ಅನ್ನು %2$s ರಂದು ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಹೊಂದಿಸಲಾಗುತ್ತದೆ.','%1$s: %2$d rows imported, %3$d skipped.'=>'%1$s: %2$d ಸಾಲುಗಳನ್ನು ಆಮದು ಮಾಡಲಾಗಿದೆ, %3$d ಬಿಟ್ಟುಬಿಡಲಾಗಿದೆ.','%d Attendees'=>'%d ಹಾಜರಾತಿದಾರರು','%d Pattern'=>'%d ಮಾದರಿ' . "\0" . '%d ಮಾದರಿಗಳು','%d Spaces'=>'%d ಸ್ಥಾನಗಳು','%d Tickets'=>'%d ಟಿಕೆಟ್‌ಗಳು','%d date'=>'%d ದಿನಾಂಕ' . "\0" . '%d ದಿನಾಂಕಗಳು','%d events have been %s as they no longer match the recurrence pattern.'=>'%d ಈವೆಂಟ್‌ಗಳು ಇನ್ನು ಪುನರಾವರ್ತನೆ ಮಾದರಿಗೆ ಹೊಂದದ ಕಾರಣ %s.','%d more rows are not listed.'=>'ಇನ್ನೂ %d ಸಾಲುಗಳನ್ನು ಪಟ್ಟಿ ಮಾಡಲಾಗಿಲ್ಲ.','%d potentially orphaned events have been found.'=>'%d ಸಂಭಾವ್ಯ ಅನಾಥ ಈವೆಂಟ್‌ಗಳು ಕಂಡುಬಂದಿವೆ.','%d space'=>'%d ಸ್ಥಾನ' . "\0" . '%d ಸ್ಥಾನಗಳು','%d ticket belongs to a recurring event or series pass; each date of the migrated recurring event gets its own copy of the ticket, and each series pass order becomes one booking per date.'=>'%d ಟಿಕೆಟ್ ಪುನರಾವರ್ತಿತ ಈವೆಂಟ್ ಅಥವಾ ಸರಣಿ ಪಾಸ್‌ಗೆ ಸೇರಿದೆ; ವರ್ಗಾಯಿಸಿದ ಪುನರಾವರ್ತಿತ ಈವೆಂಟ್‌ನ ಪ್ರತಿ ದಿನಾಂಕಕ್ಕೂ ಟಿಕೆಟ್‌ನ ತನ್ನದೇ ಪ್ರತಿ ಸಿಗುತ್ತದೆ, ಮತ್ತು ಪ್ರತಿ ಸರಣಿ ಪಾಸ್ ಆರ್ಡರ್ ಪ್ರತಿ ದಿನಾಂಕಕ್ಕೆ ಒಂದು ಬುಕಿಂಗ್ ಆಗುತ್ತದೆ.' . "\0" . '%d ಟಿಕೆಟ್‌ಗಳು ಪುನರಾವರ್ತಿತ ಈವೆಂಟ್‌ಗಳು ಅಥವಾ ಸರಣಿ ಪಾಸ್‌ಗಳಿಗೆ ಸೇರಿವೆ; ವರ್ಗಾಯಿಸಿದ ಪುನರಾವರ್ತಿತ ಈವೆಂಟ್‌ನ ಪ್ರತಿ ದಿನಾಂಕಕ್ಕೂ ಟಿಕೆಟ್‌ನ ತನ್ನದೇ ಪ್ರತಿ ಸಿಗುತ್ತದೆ, ಮತ್ತು ಪ್ರತಿ ಸರಣಿ ಪಾಸ್ ಆರ್ಡರ್ ಪ್ರತಿ ದಿನಾಂಕಕ್ಕೆ ಒಂದು ಬುಕಿಂಗ್ ಆಗುತ್ತದೆ.','%d will be replaced by a number.'=>'%d ಅನ್ನು ಒಂದು ಸಂಖ್ಯೆಯಿಂದ ಬದಲಾಯಿಸಲಾಗುತ್ತದೆ.','%s'=>'%s','%s (the link is provided after booking)'=>'%s (ಲಿಂಕ್ ಅನ್ನು ಬುಕಿಂಗ್ ನಂತರ ಒದಗಿಸಲಾಗುತ್ತದೆ)','%s (the link is provided once your booking is confirmed)'=>'%s (ನಿಮ್ಮ ಬುಕಿಂಗ್ ದೃಢೀಕರಿಸಿದ ನಂತರ ಲಿಂಕ್ ಒದಗಿಸಲಾಗುತ್ತದೆ)','%s (your booking does not include virtual access)'=>'%s (ನಿಮ್ಮ ಬುಕಿಂಗ್ ವರ್ಚುವಲ್ ಪ್ರವೇಶವನ್ನು ಒಳಗೊಂಡಿಲ್ಲ)','%s Advanced Options'=>'ಹೆಚ್ಚುವರಿ ಆಯ್ಕೆಗಳನ್ನು %s','%s App ID'=>'%s ಆಪ್ ID','%s App Secret'=>'%s ಆಪ್ ಸೀಕ್ರೆಟ್','%s Attributes'=>'%s ಗುಣಲಕ್ಷಣಗಳು','%s Between'=>'%s ನಡುವೆ','%s Capabilities'=>'%s ಅರ್ಹತೆಗಳು','%s Error. Try again?'=>'%s ದೋಷ. ಮತ್ತೆ ಪ್ರಯತ್ನಿಸುವಿರಾ?','%s Excerpts'=>'%s ಆಯ್ದ ಭಾಗಗಳು','%s ID'=>'%s ID','%s List Formats'=>'%s ಪಟ್ಟಿ ನಮೂನೆಗಳು','%s List/Archives'=>'%s ಪಟ್ಟಿ/ದಾಖಲೆಗಳು','%s Options'=>'%s ಆಯ್ಕೆಗಳು','%s Page'=>'%s ಪುಟ','%s Pages'=>'%s ಪುಟಗಳು','%s Preview Mode'=>'%s ಮುನ್ನೋಟ ಮೋಡ್','%s Recurrences'=>'%s ಪುನರಾವರ್ತನೆಗಳು','%s Rows'=>'%s ಸಾಲುಗಳು','%s Settings'=>'%s ಸೆಟ್ಟಿಂಗ್‌ಗಳು','%s Span Between'=>'%s ನಡುವಿನ ವ್ಯಾಪ್ತಿ','%s Status'=>'%s ಸ್ಥಿತಿ','%s Submitted'=>'%s ಸಲ್ಲಿಸಲಾಗಿದೆ','%s URL'=>'%s URL','%s added the event %s'=>'%s ಅವರು %s ಈವೆಂಟ್ ಅನ್ನು ಸೇರಿಸಿದ್ದಾರೆ','%s added the event %s to %s.'=>'%s ಅವರು %s ಈವೆಂಟ್ ಅನ್ನು %s ಗೆ ಸೇರಿಸಿದ್ದಾರೆ.','%s allows you to modify some or all of the formats used by Events Manager to generate your content. You can choose to override default formats and customize them to your needs. You do not lose your previously defined custom formats should you enable/disable %s or choose to not override a certain set of formats, they\'ll appear again once you enable %s again for that content.'=>'%s ನಿಮ್ಮ ವಿಷಯವನ್ನು ರಚಿಸಲು Events Manager ಬಳಸುವ ಕೆಲವು ಅಥವಾ ಎಲ್ಲಾ ಸ್ವರೂಪಗಳನ್ನು ಮಾರ್ಪಡಿಸಲು ಅನುಮತಿಸುತ್ತದೆ. ನೀವು ಡೀಫಾಲ್ಟ್ ಸ್ವರೂಪಗಳನ್ನು ಅತಿಕ್ರಮಿಸಿ ನಿಮ್ಮ ಅಗತ್ಯಕ್ಕೆ ತಕ್ಕಂತೆ ಅಗತ್ಯಾನುಗುಣಗೊಳಿಸಬಹುದು. ನೀವು %s ಅನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿದರೂ/ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಿದರೂ ಅಥವಾ ಕೆಲವು ಸ್ವರೂಪಗಳನ್ನು ಅತಿಕ್ರಮಿಸದಿರಲು ಆರಿಸಿದರೂ ನೀವು ಈ ಹಿಂದೆ ವ್ಯಾಖ್ಯಾನಿಸಿದ ಅಗತ್ಯಾನುಗುಣ ಸ್ವರೂಪಗಳು ಕಳೆದುಹೋಗುವುದಿಲ್ಲ; ಆ ವಿಷಯಕ್ಕಾಗಿ %s ಅನ್ನು ಮತ್ತೆ ಸಕ್ರಿಯಗೊಳಿಸಿದಾಗ ಅವು ಮತ್ತೆ ಕಾಣಿಸುತ್ತವೆ.','%s are a <a href="%s" target="_blank">WordPress custom taxonomy</a>.'=>'%s ಒಂದು <a href="%s" target="_blank">WordPress ಕಸ್ಟಮ್ ಟ್ಯಾಕ್ಸಾನಮಿ</a> ಆಗಿದೆ.','%s are also accepted, for example %s equals 1 month and 12 hours before the event starts.'=>'%s ಗಳನ್ನೂ ಸ್ವೀಕರಿಸಲಾಗುತ್ತದೆ, ಉದಾಹರಣೆಗೆ %s ಎಂದರೆ ಈವೆಂಟ್ ಪ್ರಾರಂಭವಾಗುವ 1 ತಿಂಗಳು ಮತ್ತು 12 ಗಂಟೆಗಳ ಮೊದಲು.','%s belonging to other sub-sites will have an extra slug prepended to it so that your main site can differentiate between its own %s and those belonging to other sites in your network.'=>'ಇತರ ಉಪ-ಸೈಟ್‌ಗಳಿಗೆ ಸೇರಿದ %s ಗೆ ಹೆಚ್ಚುವರಿ ಸ್ಲಗ್ ಅನ್ನು ಮುಂದೆ ಸೇರಿಸಲಾಗುತ್ತದೆ, ಇದರಿಂದ ನಿಮ್ಮ ಮುಖ್ಯ ಸೈಟ್ ತನ್ನದೇ %s ಮತ್ತು ನಿಮ್ಮ ನೆಟ್‌ವರ್ಕ್‌ನ ಇತರ ಸೈಟ್‌ಗಳಿಗೆ ಸೇರಿದವುಗಳ ನಡುವೆ ವ್ಯತ್ಯಾಸ ಗುರುತಿಸಬಹುದು.','%s can be displayed just like normal WordPress custom taxonomies in an archive-style format, however Events Manager by default allows you to completely change the standard look of these archives and use our own <a href="%s">custom formatting</a> methods.'=>'%s ಅನ್ನು ಸಾಮಾನ್ಯ WordPress ಕಸ್ಟಮ್ ಟ್ಯಾಕ್ಸಾನಮಿಗಳಂತೆ ಆರ್ಕೈವ್ ಶೈಲಿಯಲ್ಲಿ ತೋರಿಸಬಹುದು, ಆದರೆ Events Manager ಡೀಫಾಲ್ಟ್ ಆಗಿ ಈ ಆರ್ಕೈವ್‌ಗಳ ಸಾಮಾನ್ಯ ನೋಟವನ್ನು ಸಂಪೂರ್ಣವಾಗಿ ಬದಲಾಯಿಸಲು ಮತ್ತು ನಮ್ಮದೇ ಆದ <a href="%s">ಕಸ್ಟಮ್ ಫಾರ್ಮ್ಯಾಟಿಂಗ್</a> ವಿಧಾನಗಳನ್ನು ಬಳಸಲು ಅವಕಾಶ ನೀಡುತ್ತದೆ.','%s cannot be used for a hybrid event, because it gives every booking virtual access.'=>'%s ಅನ್ನು ಹೈಬ್ರಿಡ್ ಈವೆಂಟ್‌ಗೆ ಬಳಸಲಾಗುವುದಿಲ್ಲ, ಏಕೆಂದರೆ ಅದು ಪ್ರತಿ ಬುಕಿಂಗ್‌ಗೂ ವರ್ಚುವಲ್ ಪ್ರವೇಶವನ್ನು ನೀಡುತ್ತದೆ.','%s could not be deleted'=>'%s ಅನ್ನು ಅಳಿಸಲಾಗಲಿಲ್ಲ','%s could not be deleted.'=>'%s ಅನ್ನು ಅಳಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ.','%s created.'=>'%s ರಚಿಸಲಾಗಿದೆ.','%s custom post types can have archives, just like normal WordPress posts. If enabled, should you visit your base slug url %s and you will see an post-formatted archive of previous %s'=>'%s ಕಸ್ಟಮ್ ಪೋಸ್ಟ್ ಪ್ರಕಾರಗಳು ಸಾಮಾನ್ಯ WordPress ಪೋಸ್ಟ್‌ಗಳಂತೆಯೇ ಆರ್ಕೈವ್‌ಗಳನ್ನು ಹೊಂದಬಹುದು. ಸಕ್ರಿಯಗೊಳಿಸಿದರೆ, ನಿಮ್ಮ ಮೂಲ ಸ್ಲಗ್ URL %s ಗೆ ಭೇಟಿ ನೀಡಿದಾಗ ನೀವು ಹಿಂದಿನ %s ನ ಪೋಸ್ಟ್-ಸ್ವರೂಪದ ಆರ್ಕೈವ್ ಅನ್ನು ನೋಡುತ್ತೀರಿ','%s deleted'=>'%s ಅಳಿಸಲಾಗಿದೆ','%s excerpt'=>'%s ಆಯ್ದ ಭಾಗ','%s excerpt fallback'=>'%s ಆಯ್ದ ಭಾಗದ ಪರ್ಯಾಯ','%s includes every add-on sold here.'=>'%s ಇಲ್ಲಿ ಮಾರಾಟವಾಗುವ ಎಲ್ಲಾ ಆಡ್-ಆನ್‌ಗಳನ್ನು ಒಳಗೊಂಡಿದೆ.','%s is attending %s of the group %s.'=>'%s ಅವರು %s ಗುಂಪಿನ %s ಗೆ ಹಾಜರಾಗುತ್ತಿದ್ದಾರೆ.','%s is attending %s.'=>'%s ಅವರು %s ಗೆ ಹಾಜರಾಗುತ್ತಿದ್ದಾರೆ.','%s is replaced by username, %s is replaced by the user password and %s is replaced by a link to create a password.'=>'%s ಅನ್ನು ಬಳಕೆದಾರರ ಹೆಸರಿನಿಂದ, %s ಅನ್ನು ಬಳಕೆದಾರರ ಗುಪ್ತಪದದಿಂದ ಮತ್ತು %s ಅನ್ನು ಗುಪ್ತಪದ ರಚಿಸುವ ಲಿಂಕ್‌ನಿಂದ ಬದಲಾಯಿಸಲಾಗುತ್ತದೆ.','%s is required.'=>'%s ಅಗತ್ಯವಿದೆ.','%s item'=>'%s ಐಟಂ' . "\0" . '%s ಐಟಂಗಳು','%s list footer format'=>'%s ಪಟ್ಟಿಯ ಅಡಿಟಿಪ್ಪಣಿ ನಮೂನೆ','%s list header format'=>'%s ಪಟ್ಟಿಯ ಶೀರ್ಷಿಕೆ ನಮೂನೆ','%s list item format'=>'%s ಪಟ್ಟಿ ಐಟಂ ನಮೂನೆ','%s must be set to yes for this to work.'=>'ಇದು ಕಾರ್ಯನಿರ್ವಹಿಸಲು %s ಅನ್ನು ಹೌದು ಎಂದು ಹೊಂದಿಸಬೇಕು.','%s overrides all formatting choices, which will be be taken from the settings defined on this page. If you want to override only certain formatting, choose the %s instead.'=>'%s ಎಲ್ಲಾ ಫಾರ್ಮ್ಯಾಟಿಂಗ್ ಆಯ್ಕೆಗಳನ್ನು ಅತಿಕ್ರಮಿಸುತ್ತದೆ, ಅವನ್ನು ಈ ಪುಟದಲ್ಲಿ ವ್ಯಾಖ್ಯಾನಿಸಿದ ಸೆಟ್ಟಿಂಗ್‌ಗಳಿಂದ ತೆಗೆದುಕೊಳ್ಳಲಾಗುತ್ತದೆ. ಕೆಲವು ಫಾರ್ಮ್ಯಾಟಿಂಗ್ ಅನ್ನು ಮಾತ್ರ ಅತಿಕ್ರಮಿಸಬೇಕೆಂದಿದ್ದರೆ, ಬದಲಿಗೆ %s ಆರಿಸಿ.','%s page'=>'%s ಪುಟ','%s parameters will be permitted in shortcode.'=>'ಶಾರ್ಟ್‌ಕೋಡ್‌ನಲ್ಲಿ %s ಪ್ಯಾರಾಮೀಟರ್‌ಗಳಿಗೆ ಅನುಮತಿ ನೀಡಲಾಗುತ್ತದೆ.','%s row'=>'%s ಸಾಲು' . "\0" . '%s ಸಾಲುಗಳು','%s successfully deleted'=>'%s ಯಶಸ್ವಿಯಾಗಿ ಅಳಿಸಲಾಗಿದೆ','%s successfully deleted.'=>'%s ಯಶಸ್ವಿಯಾಗಿ ಅಳಿಸಲಾಗಿದೆ.','%s successfully duplicated.'=>'%s ಯಶಸ್ವಿಯಾಗಿ ನಕಲು ಮಾಡಲಾಗಿದೆ.','%s users cancelled bookings.'=>'%s ಬಳಕೆದಾರರು ಬುಕಿಂಗ್‌ಗಳನ್ನು ರದ್ದುಗೊಳಿಸಿದ್ದಾರೆ.','%s will be replaced by a link to your site privacy policy page.'=>'%s ಅನ್ನು ನಿಮ್ಮ ಸೈಟ್‌ನ ಗೌಪ್ಯತಾ ನೀತಿ ಪುಟದ ಲಿಂಕ್‌ನಿಂದ ಬದಲಾಯಿಸಲಾಗುತ್ತದೆ.','%s will not be attending %s anymore.'=>'%s ಅವರು ಇನ್ನು ಮುಂದೆ %s ಗೆ ಹಾಜರಾಗುವುದಿಲ್ಲ.','%s will not be attending %s of group %s anymore.'=>'%s ಅವರು ಇನ್ನು ಮುಂದೆ %s ಗುಂಪಿನ %s ಗೆ ಹಾಜರಾಗುವುದಿಲ್ಲ.','(New)'=>'(ಹೊಸ)','(always available)'=>'(ಯಾವಾಗಲೂ ಲಭ್ಯವಿದೆ)','(not applicable with event ownership on presently, coming soon!)'=>'(ಈಗ ಈವೆಂಟ್ ಮಾಲೀಕತ್ವ ಆನ್ ಇರುವಾಗ ಅನ್ವಯಿಸುವುದಿಲ್ಲ, ಶೀಘ್ರದಲ್ಲೇ ಬರಲಿದೆ!)','1,2,3 or 2 (0 = all)'=>'1,2,3 ಅಥವಾ 2 (0 = ಎಲ್ಲಾ)','1. Match columns'=>'1. ಕಾಲಮ್‌ಗಳನ್ನು ಹೊಂದಿಸಿ','2 for every second day, week, month or year. Leave empty for every one.'=>'ಪ್ರತಿ ಎರಡನೇ ದಿನ, ವಾರ, ತಿಂಗಳು ಅಥವಾ ವರ್ಷಕ್ಕೆ 2. ಪ್ರತಿಯೊಂದಕ್ಕೂ ಖಾಲಿ ಬಿಡಿ.','2. Options'=>'2. ಆಯ್ಕೆಗಳು','3. Preview'=>'3. ಪೂರ್ವವೀಕ್ಷಣೆ','<a href="%s">See some more information</a> on how %s work when overriding with formats.'=>'ಸ್ವರೂಪಗಳೊಂದಿಗೆ ಮೀರಿಸುವಾಗ %s ಹೇಗೆ ಕೆಲಸ ಮಾಡುತ್ತವೆ ಎಂಬುದರ <a href="%s">ಹೆಚ್ಚಿನ ಮಾಹಿತಿಯನ್ನು ನೋಡಿ</a>.','<a href="%s">Visit our blog</a> for the latest news about recent updates.'=>'ಇತ್ತೀಚಿನ ಅಪ್‌ಡೇಟ್‌ಗಳ ಕುರಿತ ಸುದ್ದಿಗಾಗಿ <a href="%s">ನಮ್ಮ ಬ್ಲಾಗ್‌ಗೆ ಭೇಟಿ ನೀಡಿ</a>.','<li>No events in this location</li>'=>'<li>ಈ ಸ್ಥಳದಲ್ಲಿ ಯಾವುದೇ ಈವೆಂಟ್‌ಗಳಿಲ್ಲ</li>','<p>Events Manager is ready to go! It is highly recommended you read the <a href=\'%s\'>Getting Started</a> guide on our site, as well as checking out the <a href=\'%s\'>Settings Page</a></p>'=>'<p>Events Manager ಬಳಸಲು ಸಿದ್ಧವಾಗಿದೆ! ನಮ್ಮ ಜಾಲತಾಣದಲ್ಲಿರುವ <a href=\'%s\'>ಪ್ರಾರಂಭಿಸುವ ಮಾರ್ಗದರ್ಶಿ</a>ಯನ್ನು ಓದಲು ಹಾಗೂ <a href=\'%s\'>ಸೆಟ್ಟಿಂಗ್ ಗಳ ಪುಟ</a>ವನ್ನು ನೋಡಲು ಬಲವಾಗಿ ಶಿಫಾರಸು ಮಾಡಲಾಗಿದೆ</p>','<strong>ERROR</strong>: Couldn&#8217;t register you... please contact the <a href="mailto:%s">webmaster</a> !'=>'<strong>ದೋಷ</strong>: ನಿಮ್ಮನ್ನು ನೋಂದಾಯಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ... ದಯವಿಟ್ಟು <a href="mailto:%s">ವೆಬ್‌ಮಾಸ್ಟರ್</a> ಅವರನ್ನು ಸಂಪರ್ಕಿಸಿ!','<strong>ERROR</strong>: Please enter a username.'=>'<strong>ದೋಷ</strong>: ದಯವಿಟ್ಟು ಬಳಕೆದಾರರ ಹೆಸರನ್ನು ನಮೂದಿಸಿ.','<strong>ERROR</strong>: Please type your e-mail address.'=>'<strong>ದೋಷ</strong>: ದಯವಿಟ್ಟು ನಿಮ್ಮ ಇಮೇಲ್ ವಿಳಾಸವನ್ನು ಟೈಪ್ ಮಾಡಿ.','<strong>ERROR</strong>: The email address isn&#8217;t correct.'=>'<strong>ದೋಷ</strong>: ಇಮೇಲ್ ವಿಳಾಸ ಸರಿಯಾಗಿಲ್ಲ.','<strong>ERROR</strong>: This email is already registered, please choose another one.'=>'<strong>ದೋಷ</strong>: ಈ ಇಮೇಲ್ ಈಗಾಗಲೇ ನೋಂದಣಿಯಾಗಿದೆ, ದಯವಿಟ್ಟು ಬೇರೆಯದನ್ನು ಆರಿಸಿ.','<strong>ERROR</strong>: This username is already registered, please choose another one.'=>'<strong>ದೋಷ</strong>: ಈ ಬಳಕೆದಾರರ ಹೆಸರು ಈಗಾಗಲೇ ನೋಂದಣಿಯಾಗಿದೆ, ದಯವಿಟ್ಟು ಬೇರೆಯದನ್ನು ಆರಿಸಿ.','<strong>ERROR</strong>: This username is invalid because it uses illegal characters. Please enter a valid username.'=>'<strong>ದೋಷ</strong>: ಈ ಬಳಕೆದಾರರ ಹೆಸರು ಕಾನೂನುಬಾಹಿರ ಅಕ್ಷರಗಳನ್ನು ಬಳಸಿರುವುದರಿಂದ ಅಮಾನ್ಯವಾಗಿದೆ. ದಯವಿಟ್ಟು ಮಾನ್ಯ ಬಳಕೆದಾರರ ಹೆಸರನ್ನು ನಮೂದಿಸಿ.','<strong>Notes:</strong> Ticket availability not taken into account (i.e. you can overbook). Emails are not resent automatically.'=>'<strong>ಟಿಪ್ಪಣಿಗಳು:</strong> ಟಿಕೆಟ್ ಲಭ್ಯತೆಯನ್ನು ಪರಿಗಣಿಸಲಾಗುವುದಿಲ್ಲ (ಅಂದರೆ ನೀವು ಹೆಚ್ಚುವರಿ ಬುಕಿಂಗ್ ಮಾಡಬಹುದು). ಇಮೇಲ್‌ಗಳನ್ನು ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಮರುಕಳುಹಿಸಲಾಗುವುದಿಲ್ಲ.','<strong>Notes:</strong> Ticket availability not taken into account when approving new bookings (i.e. you can overbook).'=>'<strong>ಟಿಪ್ಪಣಿಗಳು:</strong> ಹೊಸ ಬುಕಿಂಗ್‌ಗಳನ್ನು ಅನುಮೋದಿಸುವಾಗ ಟಿಕೆಟ್ ಲಭ್ಯತೆಯನ್ನು ಪರಿಗಣಿಸಲಾಗುವುದಿಲ್ಲ (ಅಂದರೆ ನೀವು ಹೆಚ್ಚುವರಿ ಬುಕಿಂಗ್ ಮಾಡಬಹುದು).','<strong>Warning : </strong> By enabling this, registered users will not be able to see bookings they make as guests in their "My Bookings" page.'=>'<strong>ಎಚ್ಚರಿಕೆ : </strong> ಇದನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿದರೆ, ನೋಂದಾಯಿತ ಬಳಕೆದಾರರು ಅತಿಥಿಗಳಾಗಿ ಮಾಡುವ ಬುಕಿಂಗ್‌ಗಳನ್ನು ತಮ್ಮ "ನನ್ನ ಬುಕಿಂಗ್‌ಗಳು" ಪುಟದಲ್ಲಿ ನೋಡಲು ಸಾಧ್ಯವಾಗುವುದಿಲ್ಲ.','<strong>Warning : </strong> Various features afforded to users with an account will not be available, e.g. viewing bookings. Once you enable this and select a user, modifying these values will prevent older non-user bookings from displaying the correct information.'=>'<strong>ಎಚ್ಚರಿಕೆ : </strong> ಖಾತೆಯಿರುವ ಬಳಕೆದಾರರಿಗೆ ದೊರೆಯುವ ವಿವಿಧ ವೈಶಿಷ್ಟ್ಯಗಳು, ಉದಾ. ಬುಕಿಂಗ್‌ಗಳನ್ನು ವೀಕ್ಷಿಸುವುದು, ಲಭ್ಯವಿರುವುದಿಲ್ಲ. ಇದನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ ಬಳಕೆದಾರರನ್ನು ಆರಿಸಿದ ನಂತರ, ಈ ಮೌಲ್ಯಗಳನ್ನು ಮಾರ್ಪಡಿಸಿದರೆ ಹಳೆಯ ಬಳಕೆದಾರರಿಲ್ಲದ ಬುಕಿಂಗ್‌ಗಳು ಸರಿಯಾದ ಮಾಹಿತಿಯನ್ನು ತೋರಿಸುವುದನ್ನು ತಡೆಯುತ್ತದೆ.','A booking intent cannot have its status changed.'=>'ಬುಕಿಂಗ್ ಉದ್ದೇಶದ ಸ್ಥಿತಿಯನ್ನು ಬದಲಾಯಿಸಲಾಗುವುದಿಲ್ಲ.','A booking was cancelled'=>'ಒಂದು ಬುಕಿಂಗ್ ರದ್ದಾಗಿದೆ','A booking\'s payment gateway is set when the booking is made and cannot be changed.'=>'ಬುಕಿಂಗ್‌ನ ಪಾವತಿ ಗೇಟ್‌ವೇ ಅನ್ನು ಬುಕಿಂಗ್ ಮಾಡುವಾಗ ಹೊಂದಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ಅದನ್ನು ಬದಲಾಯಿಸಲಾಗುವುದಿಲ್ಲ.','A guest-accessible cancellation flow for the EU statutory <strong>right of withdrawal</strong>. Enable this only if you sell to consumers who have a right of withdrawal — <strong>fixed-date events are generally exempt</strong>. Events Manager provides the mechanism; you supply your own legal withdrawal policy text below.'=>'EU ಕಾನೂನುಬದ್ಧ <strong>ಹಿಂಪಡೆಯುವ ಹಕ್ಕಿ</strong>ಗಾಗಿ ಅತಿಥಿಗಳು ಬಳಸಬಹುದಾದ ರದ್ದತಿ ಪ್ರಕ್ರಿಯೆ. ಹಿಂಪಡೆಯುವ ಹಕ್ಕು ಹೊಂದಿರುವ ಗ್ರಾಹಕರಿಗೆ ನೀವು ಮಾರಾಟ ಮಾಡಿದರೆ ಮಾತ್ರ ಇದನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ — <strong>ನಿಗದಿತ ದಿನಾಂಕದ ಈವೆಂಟ್‌ಗಳಿಗೆ ಸಾಮಾನ್ಯವಾಗಿ ವಿನಾಯಿತಿ ಇರುತ್ತದೆ</strong>. Events Manager ಕಾರ್ಯವಿಧಾನವನ್ನು ಒದಗಿಸುತ್ತದೆ; ನಿಮ್ಮ ಸ್ವಂತ ಕಾನೂನುಬದ್ಧ ಹಿಂಪಡೆಯುವಿಕೆ ನೀತಿ ಪಠ್ಯವನ್ನು ಕೆಳಗೆ ನೀವು ಒದಗಿಸಬೇಕು.','A hybrid event needs a physical venue.'=>'ಹೈಬ್ರಿಡ್ ಈವೆಂಟ್‌ಗೆ ಭೌತಿಕ ಸ್ಥಳದ ಅಗತ್ಯವಿದೆ.','A list of further dates, such as 2027-03-11|2027-03-18, used alone or with a rule.'=>'2027-03-11|2027-03-18 ನಂತಹ ಹೆಚ್ಚುವರಿ ದಿನಾಂಕಗಳ ಪಟ್ಟಿ, ಏಕಾಂಗಿಯಾಗಿ ಅಥವಾ ನಿಯಮದೊಂದಿಗೆ ಬಳಸಲಾಗುತ್ತದೆ.','A location with this name is already on this site (location %d).'=>'ಈ ಹೆಸರಿನ ಸ್ಥಳ ಈಗಾಗಲೇ ಈ ಸೈಟ್‌ನಲ್ಲಿದೆ (ಸ್ಥಳ %d).','A location with this name is already on this site.'=>'ಈ ಹೆಸರಿನ ಸ್ಥಳ ಈಗಾಗಲೇ ಈ ಸೈಟ್‌ನಲ್ಲಿದೆ.','A new event has been published by #_CONTACTNAME.<br/>Name : #_EVENTNAME <br/>Date : #_EVENTDATES <br/>Time : #_EVENTTIMES <br/>Edit this event - #_EDITEVENTURL <br/> View this event - #_EVENTURL'=>'#_CONTACTNAME ಅವರು ಹೊಸ ಈವೆಂಟ್ ಅನ್ನು ಪ್ರಕಟಿಸಿದ್ದಾರೆ.<br/>ಹೆಸರು : #_EVENTNAME <br/>ದಿನಾಂಕ : #_EVENTDATES <br/>ಸಮಯ : #_EVENTTIMES <br/>ಈ ಈವೆಂಟ್ ಅನ್ನು ಸಂಪಾದಿಸಿ - #_EDITEVENTURL <br/> ಈ ಈವೆಂಟ್ ಅನ್ನು ವೀಕ್ಷಿಸಿ - #_EVENTURL','A new event has been submitted by #_CONTACTNAME.<br/>Name : #_EVENTNAME <br/>Date : #_EVENTDATES <br/>Time : #_EVENTTIMES <br/>Please visit #_EDITEVENTURL to review this event for approval.'=>'#_CONTACTNAME ಅವರು ಹೊಸ ಈವೆಂಟ್ ಅನ್ನು ಸಲ್ಲಿಸಿದ್ದಾರೆ.<br/>ಹೆಸರು : #_EVENTNAME <br/>ದಿನಾಂಕ : #_EVENTDATES <br/>ಸಮಯ : #_EVENTTIMES <br/>ಅನುಮೋದನೆಗಾಗಿ ಈ ಈವೆಂಟ್ ಅನ್ನು ಪರಿಶೀಲಿಸಲು ದಯವಿಟ್ಟು #_EDITEVENTURL ಗೆ ಭೇಟಿ ನೀಡಿ.','A new event was created'=>'ಹೊಸ ಈವೆಂಟ್ ರಚಿಸಲಾಗಿದೆ','A new user account has been created for you. Please check your email for access details.'=>'ನಿಮಗಾಗಿ ಹೊಸ ಬಳಕೆದಾರ ಖಾತೆಯನ್ನು ರಚಿಸಲಾಗಿದೆ. ಪ್ರವೇಶ ವಿವರಗಳಿಗಾಗಿ ದಯವಿಟ್ಟು ನಿಮ್ಮ ಇಮೇಲ್ ಪರಿಶೀಲಿಸಿ.','A previously published event has been modified by #_CONTACTNAME, and this event is now unpublished and pending your approval.<br/>Name : #_EVENTNAME <br/>Date : #_EVENTDATES <br/>Time : #_EVENTTIMES <br/>Please visit #_EDITEVENTURL to review this event for approval.'=>'ಈ ಹಿಂದೆ ಪ್ರಕಟಿಸಲಾದ ಈವೆಂಟ್ ಅನ್ನು #_CONTACTNAME ಅವರು ಮಾರ್ಪಡಿಸಿದ್ದಾರೆ, ಈ ಈವೆಂಟ್ ಈಗ ಅಪ್ರಕಟಿತವಾಗಿದ್ದು ನಿಮ್ಮ ಅನುಮೋದನೆಗಾಗಿ ಬಾಕಿಯಿದೆ.<br/>ಹೆಸರು : #_EVENTNAME <br/>ದಿನಾಂಕ : #_EVENTDATES <br/>ಸಮಯ : #_EVENTTIMES <br/>ಅನುಮೋದನೆಗಾಗಿ ಈ ಈವೆಂಟ್ ಅನ್ನು ಪರಿಶೀಲಿಸಲು ದಯವಿಟ್ಟು #_EDITEVENTURL ಗೆ ಭೇಟಿ ನೀಡಿ.','A repeating event needs a repeat-until date or a number of times.'=>'ಪುನರಾವರ್ತಿತ ಈವೆಂಟ್‌ಗೆ ಪುನರಾವರ್ತನೆಯ ಅಂತಿಮ ದಿನಾಂಕ ಅಥವಾ ಬಾರಿಗಳ ಸಂಖ್ಯೆ ಬೇಕು.','A test email will be sent to your account email - %s'=>'ನಿಮ್ಮ ಖಾತೆಯ ಇಮೇಲ್‌ಗೆ ಪರೀಕ್ಷಾ ಇಮೇಲ್ ಕಳುಹಿಸಲಾಗುತ್ತದೆ - %s','A token is required.'=>'ಟೋಕನ್ ಅಗತ್ಯವಿದೆ.','A user cancelled a booking'=>'ಒಬ್ಬ ಬಳಕೆದಾರರು ಬುಕಿಂಗ್ ಅನ್ನು ರದ್ದುಗೊಳಿಸಿದ್ದಾರೆ','A valid Expo push token is required.'=>'ಮಾನ್ಯ Expo ಪುಶ್ ಟೋಕನ್ ಅಗತ್ಯವಿದೆ.','A valid blog ID must be provided, you can only reset one blog at a time.'=>'ಮಾನ್ಯವಾದ ಬ್ಲಾಗ್ ಐಡಿ ನೀಡಬೇಕು, ನೀವು ಒಮ್ಮೆಗೆ ಒಂದು ಬ್ಲಾಗ್ ಅನ್ನು ಮಾತ್ರ ಮರುಹೊಂದಿಸಬಹುದು.','A valid email'=>'ಮಾನ್ಯ ಇಮೇಲ್','A virtual event can hold its link back until shortly before it starts. Until then, visitors and attendees see a short text in place of the link, and join links sent to attendees only start working at that time.'=>'ವರ್ಚುವಲ್ ಈವೆಂಟ್ ಪ್ರಾರಂಭವಾಗುವ ಸ್ವಲ್ಪ ಮುಂಚಿನವರೆಗೆ ತನ್ನ ಲಿಂಕ್ ಅನ್ನು ಹಿಡಿದಿಟ್ಟುಕೊಳ್ಳಬಹುದು. ಅಲ್ಲಿಯವರೆಗೆ, ಸಂದರ್ಶಕರು ಮತ್ತು ಹಾಜರಾತಿದಾರರಿಗೆ ಲಿಂಕ್‌ನ ಬದಲಿಗೆ ಸಣ್ಣ ಪಠ್ಯ ಕಾಣಿಸುತ್ತದೆ, ಮತ್ತು ಹಾಜರಾತಿದಾರರಿಗೆ ಕಳುಹಿಸಿದ ಸೇರುವ ಲಿಂಕ್‌ಗಳು ಆ ಸಮಯದಲ್ಲೇ ಕೆಲಸ ಮಾಡಲು ಪ್ರಾರಂಭಿಸುತ್ತವೆ.','AFTER the withdrawal period — please review carefully'=>'ಹಿಂಪಡೆಯುವ ಅವಧಿಯ ನಂತರ — ದಯವಿಟ್ಟು ಎಚ್ಚರಿಕೆಯಿಂದ ಪರಿಶೀಲಿಸಿ','AI / MCP Setup'=>'AI / MCP ಸೆಟಪ್','Abbreviated weekdays'=>'ಸಂಕ್ಷಿಪ್ತ ವಾರದ ದಿನಗಳು','Abbreviated weekdays?'=>'ಸಂಕ್ಷಿಪ್ತ ವಾರದ ದಿನಗಳು?','Abilities that create, update, delete, or otherwise modify Events Manager data.'=>'Events Manager ಡೇಟಾವನ್ನು ರಚಿಸುವ, ನವೀಕರಿಸುವ, ಅಳಿಸುವ ಅಥವಾ ಬೇರೆ ರೀತಿಯಲ್ಲಿ ಮಾರ್ಪಡಿಸುವ ಸಾಮರ್ಥ್ಯಗಳು.','Access'=>'ಪ್ರವೇಶ','Accordion'=>'ಅಕಾರ್ಡಿಯನ್','Account Connection'=>'ಖಾತೆ ಸಂಪರ್ಕ','Acknowledgment email'=>'ಸ್ವೀಕೃತಿ ಇಮೇಲ್','Acknowledgment email body'=>'ಸ್ವೀಕೃತಿ ಇಮೇಲ್ ಒಳಾಂಶ','Acknowledgment email subject'=>'ಸ್ವೀಕೃತಿ ಇಮೇಲ್ ವಿಷಯ','Actions'=>'ಕ್ರಿಯೆಗಳು','Activate license'=>'ಪರವಾನಗಿಯನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ','Activate plugin'=>'ಪ್ಲಗಿನ್ ಸಕ್ರಿಯಗೊಳಿಸಿ','Active'=>'ಸಕ್ರಿಯ','Add %s'=>'%s ಸೇರಿಸಿ','Add Dates '=>'ದಿನಾಂಕಗಳನ್ನು ಸೇರಿಸಿ ','Add Event'=>'ಈವೆಂಟ್ ಸೇರಿಸಿ','Add Location'=>'ಸ್ಥಳ ಸೇರಿಸಿ','Add New'=>'ಹೊಸದನ್ನು ಸೇರಿಸಿ','Add New %s'=>'ಹೊಸ %s ಸೇರಿಸಿ','Add New Archetype'=>'ಹೊಸ ಆರ್ಕಿಟೈಪ್ ಸೇರಿಸಿ','Add New Event'=>'ಹೊಸ ಈವೆಂಟ್ ಸೇರಿಸಿ','Add New Event Category'=>'ಹೊಸ ಈವೆಂಟ್ ವರ್ಗ ಸೇರಿಸಿ','Add New Event Tag'=>'ಹೊಸ ಈವೆಂಟ್ ಟ್ಯಾಗ್ ಸೇರಿಸಿ','Add New Location'=>'ಹೊಸ ಸ್ಥಳ ಸೇರಿಸಿ','Add New Repeating Event'=>'ಹೊಸ ಪುನರಾವರ್ತಿತ ಈವೆಂಟ್ ಸೇರಿಸಿ','Add Note'=>'ಟಿಪ್ಪಣಿ ಸೇರಿಸಿ','Add Repeating Event'=>'ಪುನರಾವರ್ತಿತ ಈವೆಂಟ್ ಸೇರಿಸಿ','Add Reply-To booker?'=>'ಬುಕ್ ಮಾಡಿದವರನ್ನು Reply-To ಆಗಿ ಸೇರಿಸಬೇಕೇ?','Add Reply-To event owner?'=>'ಈವೆಂಟ್ ಮಾಲೀಕರನ್ನು Reply-To ಆಗಿ ಸೇರಿಸಬೇಕೇ?','Add Time Slot'=>'ಸಮಯಾವಕಾಶ ಸೇರಿಸಿ','Add To Calendar'=>'ದಿನಸೂಚಿಗೆ ಸೇರಿಸಿ','Add a negative number or minus sign to the start of the date interval to allow cancellations after events have started.'=>'ಈವೆಂಟ್‌ಗಳು ಪ್ರಾರಂಭವಾದ ನಂತರವೂ ರದ್ದತಿಗೆ ಅನುಮತಿಸಲು, ದಿನಾಂಕ ಅಂತರದ ಆರಂಭದಲ್ಲಿ ಋಣ ಸಂಖ್ಯೆ ಅಥವಾ ಮೈನಸ್ ಚಿಹ್ನೆಯನ್ನು ಸೇರಿಸಿ.','Add a start or end date (or both) to impose time constraints on ticket availability. Leave either blank for no upper/lower limit.'=>'ಟಿಕೆಟ್ ಲಭ್ಯತೆಗೆ ಸಮಯದ ನಿರ್ಬಂಧ ವಿಧಿಸಲು ಪ್ರಾರಂಭ ಅಥವಾ ಅಂತ್ಯ ದಿನಾಂಕವನ್ನು (ಅಥವಾ ಎರಡನ್ನೂ) ಸೇರಿಸಿ. ಮೇಲಿನ/ಕೆಳಗಿನ ಮಿತಿ ಬೇಡವಾದರೆ ಯಾವುದನ್ನಾದರೂ ಖಾಲಿ ಬಿಡಿ.','Add a tax rate to your ticket prices (entering 10 will add 10% to the ticket price).'=>'ನಿಮ್ಮ ಟಿಕೆಟ್ ಬೆಲೆಗಳಿಗೆ ತೆರಿಗೆ ದರವನ್ನು ಸೇರಿಸಿ (10 ನಮೂದಿಸಿದರೆ ಟಿಕೆಟ್ ಬೆಲೆಗೆ 10% ಸೇರಿಸಲಾಗುತ್ತದೆ).','Add any of these columns to an events file. A row with none of them filled in is a single event.'=>'ಈ ಕಾಲಮ್‌ಗಳಲ್ಲಿ ಯಾವುದನ್ನಾದರೂ ಈವೆಂಟ್‌ಗಳ ಫೈಲ್‌ಗೆ ಸೇರಿಸಿ. ಇವುಗಳಲ್ಲಿ ಯಾವುದನ್ನೂ ತುಂಬದ ಸಾಲು ಒಂದೇ ಈವೆಂಟ್ ಆಗಿರುತ್ತದೆ.','Add br tags to HTML emails?'=>'HTML ಇಮೇಲ್‌ಗಳಿಗೆ br ಟ್ಯಾಗ್‌ಗಳನ್ನು ಸೇರಿಸುವುದೇ?','Add location'=>'ಸ್ಥಳ ಸೇರಿಸಿ','Add new ticket'=>'ಹೊಸ ಟಿಕೆಟ್ ಸೇರಿಸಿ','Add or remove %s'=>'%s ಸೇರಿಸಿ ಅಥವಾ ತೆಗೆಯಿರಿ','Add or remove events'=>'ಈವೆಂಟ್‌ಗಳನ್ನು ಸೇರಿಸಿ ಅಥವಾ ತೆಗೆಯಿರಿ','Add tax to ticket price?'=>'ಟಿಕೆಟ್ ಬೆಲೆಗೆ ತೆರಿಗೆ ಸೇರಿಸಬೇಕೇ?','Add to your table from the columns below.'=>'ಕೆಳಗಿನ ಅಂಕಣಗಳಿಂದ ನಿಮ್ಮ ಕೋಷ್ಟಕಕ್ಕೆ ಸೇರಿಸಿ.','Add-ons'=>'ಆಡ್-ಆನ್‌ಗಳು','Add-ons and prices are up to date.'=>'ಆಡ್-ಆನ್‌ಗಳು ಮತ್ತು ಬೆಲೆಗಳು ಇತ್ತೀಚಿನವುಗಳಾಗಿವೆ.','Add-ons are separate plugins that work with the free Events Manager plugin, so you do not need Events Manager Pro to use them.'=>'ಆಡ್-ಆನ್‌ಗಳು ಉಚಿತ Events Manager ಪ್ಲಗಿನ್‌ನೊಂದಿಗೆ ಕೆಲಸ ಮಾಡುವ ಪ್ರತ್ಯೇಕ ಪ್ಲಗಿನ್‌ಗಳು, ಆದ್ದರಿಂದ ಅವುಗಳನ್ನು ಬಳಸಲು ನಿಮಗೆ Events Manager Pro ಅಗತ್ಯವಿಲ್ಲ.','Additional CSS'=>'ಹೆಚ್ಚುವರಿ CSS','Address'=>'ವಿಳಾಸ','Address line 2'=>'ವಿಳಾಸ ಸಾಲು 2','Address only'=>'ವಿಳಾಸ ಮಾತ್ರ','Address:'=>'ವಿಳಾಸ:','Adds a checkbox below the location options that limits results to events attendees can join virtually, including hybrid events.'=>'ಸ್ಥಳದ ಆಯ್ಕೆಗಳ ಕೆಳಗೆ ಚೆಕ್‌ಬಾಕ್ಸ್ ಅನ್ನು ಸೇರಿಸುತ್ತದೆ, ಇದು ಹಾಜರಾತಿದಾರರು ವರ್ಚುವಲ್ ಆಗಿ ಸೇರಬಹುದಾದ ಈವೆಂಟ್‌ಗಳಿಗೆ (ಹೈಬ್ರಿಡ್ ಈವೆಂಟ್‌ಗಳು ಸೇರಿದಂತೆ) ಫಲಿತಾಂಶಗಳನ್ನು ಸೀಮಿತಗೊಳಿಸುತ್ತದೆ.','Adds a guest-accessible withdrawal flow and, optionally, a site-wide footer link.'=>'ಅತಿಥಿಗಳು ಬಳಸಬಹುದಾದ ಹಿಂಪಡೆಯುವ ಪ್ರಕ್ರಿಯೆಯನ್ನು ಮತ್ತು ಐಚ್ಛಿಕವಾಗಿ ತಾಣದಾದ್ಯಂತ ಅಡಿಟಿಪ್ಪಣಿ ಲಿಂಕ್ ಅನ್ನು ಸೇರಿಸುತ್ತದೆ.','Adds the time and the hidden text to the event editor, so each event can set its own. If not, every event uses the defaults below.'=>'ಈವೆಂಟ್ ಸಂಪಾದಕಕ್ಕೆ ಸಮಯ ಮತ್ತು ಮರೆಮಾಡಿದ ಪಠ್ಯವನ್ನು ಸೇರಿಸುತ್ತದೆ, ಇದರಿಂದ ಪ್ರತಿ ಈವೆಂಟ್ ತನ್ನದೇ ಆದದ್ದನ್ನು ಹೊಂದಿಸಬಹುದು. ಇಲ್ಲದಿದ್ದರೆ, ಪ್ರತಿ ಈವೆಂಟ್ ಕೆಳಗಿನ ಡೀಫಾಲ್ಟ್‌ಗಳನ್ನು ಬಳಸುತ್ತದೆ.','Admin Icon'=>'ನಿರ್ವಹಣಾ ಐಕಾನ್','Admin Tools'=>'ನಿರ್ವಹಣಾ ಉಪಕರಣಗಳು','Administrator Email'=>'ನಿರ್ವಾಹಕರ ಇಮೇಲ್','Advanced'=>'ಮುಂದುವರೆದದ್ದು','Advanced Mode'=>'ಸುಧಾರಿತ ಮೋಡ್','Advanced Search Fields'=>'ಸುಧಾರಿತ ಹುಡುಕಾಟ ಕ್ಷೇತ್ರಗಳು','Advanced search mode'=>'ಸುಧಾರಿತ ಹುಡುಕಾಟದ ಮೋಡ್','Advanced search style'=>'ಸುಧಾರಿತ ಹುಡುಕಾಟದ ಶೈಲಿ','Advanced settings'=>'ಹೆಚ್ಚುವರಿ ಸೆಟ್ಟಿಂಗ್‌ಗಳು','After'=>'ನಂತರ','All'=>'ಎಲ್ಲಾ','All %s'=>'ಎಲ್ಲಾ %s','All Ascending'=>'ಎಲ್ಲಾ ಆರೋಹಣ','All Blogs'=>'ಎಲ್ಲಾ ಬ್ಲಾಗ್‌ಗಳು','All Categories'=>'ಎಲ್ಲಾ ವರ್ಗಗಳು','All Cities/Towns'=>'ಎಲ್ಲಾ ನಗರಗಳು/ಪಟ್ಟಣಗಳು','All Countries'=>'ಎಲ್ಲಾ ದೇಶಗಳು','All Day'=>'ಇಡೀ ದಿನ','All Day Message'=>'ಇಡೀ ದಿನದ ಸಂದೇಶ','All Descending'=>'ಎಲ್ಲಾ ಅವರೋಹಣ','All Event Categories'=>'ಎಲ್ಲಾ ಈವೆಂಟ್ ವರ್ಗಗಳು','All Event Tags'=>'ಎಲ್ಲಾ ಈವೆಂಟ್ ಟ್ಯಾಗ್‌ಗಳು','All Event Types'=>'ಎಲ್ಲಾ ಈವೆಂಟ್ ಬಗೆಗಳು','All Events'=>'ಎಲ್ಲಾ ಈವೆಂಟ್‌ಗಳು','All Regions'=>'ಎಲ್ಲಾ ಪ್ರದೇಶಗಳು','All States'=>'ಎಲ್ಲಾ ರಾಜ್ಯಗಳು','All Tags'=>'ಎಲ್ಲಾ ಟ್ಯಾಗ್ ಗಳು','All Time'=>'ಎಲ್ಲಾ ಸಮಯ','All Timeslots'=>'ಎಲ್ಲಾ ಟೈಮ್‌ಸ್ಲಾಟ್‌ಗಳು','All confirmed and pending bookings will be emailed a general event cancellation notification.'=>'ದೃಢೀಕರಿಸಿದ ಮತ್ತು ಬಾಕಿಯಿರುವ ಎಲ್ಲಾ ಬುಕಿಂಗ್‌ಗಳಿಗೆ ಸಾಮಾನ್ಯ ಈವೆಂಟ್ ರದ್ದತಿ ಅಧಿಸೂಚನೆಯನ್ನು ಇಮೇಲ್ ಮಾಡಲಾಗುತ್ತದೆ.','All countries text'=>'ಎಲ್ಲಾ ರಾಷ್ಟ್ರಗಳ ಪಠ್ಯ','All day'=>'ದಿನವಿಡೀ','All day (yes or no)'=>'ದಿನವಿಡೀ (yes ಅಥವಾ no)','All events'=>'ಎಲ್ಲಾ ಈವೆಂಟ್‌ಗಳು','All events link text?'=>'ಎಲ್ಲಾ ಈವೆಂಟ್‌ಗಳ ಲಿಂಕ್ ಪಠ್ಯ?','All events will be moved to trash.'=>'ಎಲ್ಲಾ ಈವೆಂಟ್‌ಗಳನ್ನು ಕಸದಬುಟ್ಟಿಗೆ ಸರಿಸಲಾಗುತ್ತದೆ.','All options below relate to data that may have been submitted by or collected from the user requesting their personal data, which would also include events and locations where they are the author.'=>'ಕೆಳಗಿನ ಎಲ್ಲಾ ಆಯ್ಕೆಗಳು ತಮ್ಮ ವೈಯಕ್ತಿಕ ಡೇಟಾವನ್ನು ವಿನಂತಿಸುವ ಬಳಕೆದಾರರು ಸಲ್ಲಿಸಿರಬಹುದಾದ ಅಥವಾ ಅವರಿಂದ ಸಂಗ್ರಹಿಸಿರಬಹುದಾದ ಡೇಟಾಗೆ ಸಂಬಂಧಿಸಿವೆ, ಇದರಲ್ಲಿ ಅವರು ಲೇಖಕರಾಗಿರುವ ಈವೆಂಟ್‌ಗಳು ಮತ್ತು ಸ್ಥಳಗಳೂ ಸೇರಿರುತ್ತವೆ.','All our sold add-ons'=>'ನಾವು ಮಾರಾಟ ಮಾಡುವ ಎಲ್ಲಾ ಆಡ್-ಆನ್‌ಗಳು','All regions text'=>'ಎಲ್ಲಾ ಪ್ರದೇಶಗಳ ಪಠ್ಯ','All settings, events and bookings for every site on this network will be permanently deleted. This cannot be undone.'=>'ಈ ನೆಟ್‌ವರ್ಕ್‌ನ ಪ್ರತಿ ಸೈಟ್‌ನ ಎಲ್ಲಾ ಸೆಟ್ಟಿಂಗ್‌ಗಳು, ಈವೆಂಟ್‌ಗಳು ಮತ್ತು ಬುಕಿಂಗ್‌ಗಳು ಶಾಶ್ವತವಾಗಿ ಅಳಿಸಲ್ಪಡುತ್ತವೆ. ಇದನ್ನು ರದ್ದುಗೊಳಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ.','All states text'=>'ಎಲ್ಲಾ ರಾಜ್ಯಗಳ ಪಠ್ಯ','All towns/cities text'=>'ಎಲ್ಲಾ ಪಟ್ಟಣಗಳು/ನಗರಗಳ ಪಠ್ಯ','All translations of this event will be detached from the recurring event.'=>'ಈ ಈವೆಂಟ್‌ನ ಎಲ್ಲಾ ಭಾಷಾಂತರಗಳನ್ನು ಪುನರಾವರ್ತಿತ ಈವೆಂಟ್‌ನಿಂದ ಬೇರ್ಪಡಿಸಲಾಗುತ್ತದೆ.','All your settings and events will be permanently deleted. This cannot be undone.'=>'ನಿಮ್ಮ ಎಲ್ಲಾ ಸೆಟ್ಟಿಂಗ್‌ಗಳು ಮತ್ತು ಈವೆಂಟ್‌ಗಳು ಶಾಶ್ವತವಾಗಿ ಅಳಿಸಲ್ಪಡುತ್ತವೆ. ಇದನ್ನು ರದ್ದುಗೊಳಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ.','All your settings, including email templates and template formats for Events Manager will be deleted.'=>'ಇಮೇಲ್ ಟೆಂಪ್ಲೇಟ್‌ಗಳು ಮತ್ತು Events Manager ನ ಟೆಂಪ್ಲೇಟ್ ಸ್ವರೂಪಗಳು ಸೇರಿದಂತೆ ನಿಮ್ಮ ಎಲ್ಲಾ ಸೆಟ್ಟಿಂಗ್‌ಗಳು ಅಳಿಸಲ್ಪಡುತ್ತವೆ.','Allow %s to appear in the built-in search results.'=>'ಅಂತರ್ನಿರ್ಮಿತ ಹುಡುಕಾಟ ಫಲಿತಾಂಶಗಳಲ್ಲಿ %s ಕಾಣಿಸಿಕೊಳ್ಳಲು ಅನುಮತಿಸಿ.','Allow Maybe?'=>'ಬಹುಶಃ ಎನ್ನಲು ಅನುಮತಿಸಬೇಕೇ?','Allow Multiple Uploads'=>'ಬಹು ಅಪ್‌ಲೋಡ್‌ಗಳನ್ನು ಅನುಮತಿಸಿ','Allow RSVP Actions'=>'RSVP ಕ್ರಿಯೆಗಳಿಗೆ ಅನುಮತಿಸಿ','Allow WordPress post-style archives.'=>'WordPress ಪೋಸ್ಟ್-ಶೈಲಿಯ ಆರ್ಕೈವ್‌ಗಳನ್ನು ಅನುಮತಿಸಿ.','Allow anonymous event submissions?'=>'ಅನಾಮಿಕ ಈವೆಂಟ್ ಸಲ್ಲಿಕೆಗಳನ್ನು ಅನುಮತಿಸುವುದೇ?','Allow bookings with registered emails?'=>'ನೋಂದಾಯಿತ ಇಮೇಲ್‌ಗಳೊಂದಿಗೆ ಬುಕಿಂಗ್‌ಗಳಿಗೆ ಅನುಮತಿಸಬೇಕೇ?','Allow double bookings?'=>'ದ್ವಿಗುಣ ಬುಕಿಂಗ್‌ಗಳಿಗೆ ಅನುಮತಿಸಬೇಕೇ?','Allow format shortcode parameters?'=>'ಫಾರ್ಮ್ಯಾಟ್ ಶಾರ್ಟ್‌ಕೋಡ್ ಪ್ಯಾರಾಮೀಟರ್‌ಗಳಿಗೆ ಅನುಮತಿಸಬೇಕೇ?','Allow guest bookings?'=>'ಅತಿಥಿ ಬುಕಿಂಗ್‌ಗಳಿಗೆ ಅನುಮತಿಸಬೇಕೇ?','Allow overbooking when approving?'=>'ಅನುಮೋದಿಸುವಾಗ ಅಧಿಕ ಬುಕಿಂಗ್‌ಗೆ ಅನುಮತಿಸಬೇಕೇ?','Allow subsites to create their own'=>'ಸಬ್‌ಸೈಟ್‌ಗಳು ತಮ್ಮದೇ ಆದದ್ದನ್ನು ರಚಿಸಲು ಅನುಮತಿಸಿ','Allow users to respond with a \'Maybe\' status rather than Attending or Not Attending'=>'ಹಾಜರಾಗುತ್ತೇನೆ ಅಥವಾ ಹಾಜರಾಗುವುದಿಲ್ಲ ಎನ್ನುವ ಬದಲು \'ಬಹುಶಃ\' ಸ್ಥಿತಿಯೊಂದಿಗೆ ಪ್ರತಿಕ್ರಿಯಿಸಲು ಬಳಕೆದಾರರಿಗೆ ಅನುಮತಿಸಿ','Allowed Extensions'=>'ಅನುಮತಿಸಿದ ವಿಸ್ತರಣೆಗಳು','Already Booked'=>'ಈಗಾಗಲೇ ಬುಕ್ ಆಗಿದೆ','Already attending'=>'ಈಗಾಗಲೇ ಹಾಜರಾಗುತ್ತಿದ್ದೀರಿ','Already booked'=>'ಈಗಾಗಲೇ ಬುಕ್ ಮಾಡಲಾಗಿದೆ','Already have a license? Download the plugin from %s, upload it under Plugins > Add New Plugin, then activate your license from its settings.'=>'ಈಗಾಗಲೇ ಪರವಾನಗಿ ಇದೆಯೇ? %s ನಿಂದ ಪ್ಲಗಿನ್ ಡೌನ್‌ಲೋಡ್ ಮಾಡಿ, ಪ್ಲಗಿನ್‌ಗಳು > ಹೊಸ ಪ್ಲಗಿನ್ ಸೇರಿಸಿ ಅಡಿಯಲ್ಲಿ ಅಪ್‌ಲೋಡ್ ಮಾಡಿ, ನಂತರ ಅದರ ಸೆಟ್ಟಿಂಗ್‌ಗಳಿಂದ ನಿಮ್ಮ ಪರವಾನಗಿಯನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ.','Already migrated: %s'=>'ಈಗಾಗಲೇ ವರ್ಗಾಯಿಸಲಾಗಿದೆ: %s','Also, the following will occur:'=>'ಅಲ್ಲದೆ, ಈ ಕೆಳಗಿನವು ಸಂಭವಿಸುತ್ತವೆ:','Always check the latest stable version?'=>'ಯಾವಾಗಲೂ ಇತ್ತೀಚಿನ ಸ್ಥಿರ ಆವೃತ್ತಿಯನ್ನು ಪರಿಶೀಲಿಸಬೇಕೇ?','Always show and ask for consent'=>'ಯಾವಾಗಲೂ ತೋರಿಸಿ ಮತ್ತು ಒಪ್ಪಿಗೆ ಕೇಳಿ','An email will be sent to an administrator of your choice when an event is published by users who are not administrators.'=>'ನಿರ್ವಾಹಕರಲ್ಲದ ಬಳಕೆದಾರರು ಈವೆಂಟ್ ಪ್ರಕಟಿಸಿದಾಗ ನೀವು ಆರಿಸಿದ ನಿರ್ವಾಹಕರಿಗೆ ಇಮೇಲ್ ಕಳುಹಿಸಲಾಗುತ್ತದೆ.','An email will be sent to the event contact if someone cancels their booking.'=>'ಯಾರಾದರೂ ತಮ್ಮ ಬುಕಿಂಗ್ ಅನ್ನು ರದ್ದುಗೊಳಿಸಿದರೆ ಈವೆಂಟ್ ಸಂಪರ್ಕದವರಿಗೆ ಇಮೇಲ್ ಕಳುಹಿಸಲಾಗುತ್ತದೆ.','An email will be sent to the event owner when their event is approved. Users requiring event approval do not have the <code>publish_events</code> capability.'=>'ಈವೆಂಟ್ ಮಾಲೀಕರ ಈವೆಂಟ್ ಅನುಮೋದಿಸಲ್ಪಟ್ಟಾಗ ಅವರಿಗೆ ಇಮೇಲ್ ಕಳುಹಿಸಲಾಗುತ್ತದೆ. ಈವೆಂಟ್ ಅನುಮೋದನೆ ಅಗತ್ಯವಿರುವ ಬಳಕೆದಾರರಿಗೆ <code>publish_events</code> ಸಾಮರ್ಥ್ಯ ಇರುವುದಿಲ್ಲ.','An email will be sent to your administrator emails when an event is submitted and pending approval.'=>'ಈವೆಂಟ್ ಸಲ್ಲಿಸಲ್ಪಟ್ಟು ಅನುಮೋದನೆಗಾಗಿ ಬಾಕಿಯಿದ್ದಾಗ ನಿಮ್ಮ ನಿರ್ವಾಹಕರ ಇಮೇಲ್‌ಗಳಿಗೆ ಇಮೇಲ್ ಕಳುಹಿಸಲಾಗುತ್ತದೆ.','An error has occurred, not all sites were upgraded successfully.'=>'ದೋಷ ಉಂಟಾಗಿದೆ, ಎಲ್ಲಾ ಸೈಟ್‌ಗಳನ್ನು ಯಶಸ್ವಿಯಾಗಿ ಅಪ್‌ಗ್ರೇಡ್ ಮಾಡಲಾಗಿಲ್ಲ.','An error occurred.'=>'ದೋಷ ಸಂಭವಿಸಿದೆ.','An event with no bookings.'=>'ಬುಕಿಂಗ್‌ಗಳಿಲ್ಲದ ಈವೆಂಟ್.','An event with this name and start is already on this site (event %d).'=>'ಈ ಹೆಸರು ಮತ್ತು ಆರಂಭದ ಈವೆಂಟ್ ಈಗಾಗಲೇ ಈ ಸೈಟ್‌ನಲ್ಲಿದೆ (ಈವೆಂಟ್ %d).','An import is running. Wait for it to finish, or pause it first.'=>'ಆಮದು ನಡೆಯುತ್ತಿದೆ. ಅದು ಮುಗಿಯುವವರೆಗೆ ಕಾಯಿರಿ, ಅಥವಾ ಮೊದಲು ವಿರಾಮಗೊಳಿಸಿ.','An organizer with this name is already on this site.'=>'ಈ ಹೆಸರಿನ ಆಯೋಜಕರು ಈಗಾಗಲೇ ಈ ಸೈಟ್‌ನಲ್ಲಿದ್ದಾರೆ.','And much more'=>'ಮತ್ತು ಇನ್ನೂ ಹೆಚ್ಚು','Anonymous Submitter Info'=>'ಅನಾಮಿಕ ಸಲ್ಲಿಕೆದಾರರ ಮಾಹಿತಿ','Anonymous event submissions'=>'ಅನಾಮಿಕ ಈವೆಂಟ್ ಸಲ್ಲಿಕೆಗಳು','Anonymous submitters cannot see or modify their event once submitted. You can customize the success message they see here.'=>'ಅನಾಮಿಕ ಸಲ್ಲಿಕೆದಾರರು ಸಲ್ಲಿಸಿದ ನಂತರ ತಮ್ಮ ಈವೆಂಟ್ ಅನ್ನು ನೋಡಲು ಅಥವಾ ಮಾರ್ಪಡಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ. ಅವರಿಗೆ ಕಾಣಿಸುವ ಯಶಸ್ಸಿನ ಸಂದೇಶವನ್ನು ನೀವು ಇಲ್ಲಿ ಅಗತ್ಯಾನುಗುಣಗೊಳಿಸಬಹುದು.','Another request is already updating this online location.'=>'ಮತ್ತೊಂದು ವಿನಂತಿಯು ಈಗಾಗಲೇ ಈ ಆನ್‌ಲೈನ್ ಸ್ಥಳವನ್ನು ಅಪ್‌ಡೇಟ್ ಮಾಡುತ್ತಿದೆ.','Any Type'=>'ಯಾವುದೇ ಬಗೆ','Appears as the first default search option.'=>'ಮೊದಲ ಡೀಫಾಲ್ಟ್ ಹುಡುಕಾಟ ಆಯ್ಕೆಯಾಗಿ ಕಾಣಿಸುತ್ತದೆ.','Appears as the label for this search option.'=>'ಈ ಹುಡುಕಾಟ ಆಯ್ಕೆಯ ಲೇಬಲ್ ಆಗಿ ಕಾಣಿಸುತ್ತದೆ.','Appears on the text search filter above the categories list.'=>'ವರ್ಗಗಳ ಪಟ್ಟಿಯ ಮೇಲಿನ ಪಠ್ಯ ಹುಡುಕಾಟ ಶೋಧಕದಲ್ಲಿ ಕಾಣಿಸುತ್ತದೆ.','Appears on the text search filter above the tags list.'=>'ಟ್ಯಾಗ್‌ಗಳ ಪಟ್ಟಿಯ ಮೇಲಿನ ಪಠ್ಯ ಹುಡುಕಾಟ ಶೋಧಕದಲ್ಲಿ ಕಾಣಿಸುತ್ತದೆ.','Appears within the input box.'=>'ಇನ್‌ಪುಟ್ ಪೆಟ್ಟಿಗೆಯ ಒಳಗೆ ಕಾಣಿಸುತ್ತದೆ.','Apply global capabilities?'=>'ಜಾಗತಿಕ ಅರ್ಹತೆಗಳನ್ನು ಅನ್ವಯಿಸಬೇಕೇ?','Approval Required?'=>'ಅನುಮೋದನೆ ಅಗತ್ಯವೇ?','Approve'=>'ಅನುಮೋದಿಸಿ','Approved'=>'ಅನುಮೋದಿಸಿದೆ','Archetype'=>'ಆರ್ಕಿಟೈಪ್','Archetypes UI Builder'=>'ಆರ್ಕಿಟೈಪ್‌ಗಳ UI ಬಿಲ್ಡರ್','Are current events past events?'=>'ಪ್ರಸ್ತುತ ಈವೆಂಟ್‌ಗಳು ಹಿಂದಿನ ಈವೆಂಟ್‌ಗಳೇ?','Are you sure you want to cancel your booking?'=>'ನಿಮ್ಮ ಬುಕಿಂಗ್ ಅನ್ನು ರದ್ದುಗೊಳಿಸಲು ನೀವು ಖಚಿತವಾಗಿ ಬಯಸುವಿರಾ?','Are you sure you want to continue?'=>'ಮುಂದುವರಿಸಲು ನೀವು ಖಚಿತವಾಗಿ ಬಯಸುವಿರಾ?','Are you sure you want to convert all repeating events into recurring events?'=>'ಎಲ್ಲಾ ಪುನರಾವರ್ತಿಸುವ ಈವೆಂಟ್‌ಗಳನ್ನು ಪುನರಾವರ್ತಿತ ಈವೆಂಟ್‌ಗಳಾಗಿ ಪರಿವರ್ತಿಸಲು ನೀವು ಖಚಿತವಾಗಿ ಬಯಸುವಿರಾ?','Are you sure you want to convert this repeating event?'=>'ಈ ಪುನರಾವರ್ತಿತ ಈವೆಂಟ್ ಅನ್ನು ಪರಿವರ್ತಿಸಲು ನೀವು ಖಚಿತವಾಗಿ ಬಯಸುವಿರಾ?','Are you sure you want to delete all recurrences of this event?'=>'ಈ ಈವೆಂಟ್‌ನ ಎಲ್ಲಾ ಪುನರಾವರ್ತನೆಗಳನ್ನು ಅಳಿಸಲು ನೀವು ಖಚಿತವಾಗಿ ಬಯಸುವಿರಾ?','Are you sure you want to delete this archetype? This action cannot be undone.'=>'ಈ ಆರ್ಕಿಟೈಪ್ ಅನ್ನು ಅಳಿಸಲು ನೀವು ಖಚಿತವಾಗಿ ಬಯಸುವಿರಾ? ಈ ಕ್ರಿಯೆಯನ್ನು ರದ್ದುಗೊಳಿಸಲಾಗದು.','Are you sure you want to delete this file? It will be deleted upon submission.'=>'ಈ ಕಡತವನ್ನು ಅಳಿಸಲು ನೀವು ಖಚಿತವಾಗಿ ಬಯಸುವಿರಾ? ಸಲ್ಲಿಸಿದಾಗ ಅದನ್ನು ಅಳಿಸಲಾಗುತ್ತದೆ.','Are you sure you want to delete this item? This action cannot be undone.'=>'ಈ ಐಟಂ ಅನ್ನು ಅಳಿಸಲು ನೀವು ಖಚಿತವಾಗಿ ಬಯಸುವಿರಾ? ಈ ಕ್ರಿಯೆಯನ್ನು ಹಿಂದಿರುಗಿಸಲಾಗುವುದಿಲ್ಲ.','Are you sure you want to delete this ticket?'=>'ಈ ಟಿಕೆಟ್ ಅನ್ನು ಅಳಿಸಲು ನೀವು ಖಚಿತವಾಗಿ ಬಯಸುವಿರಾ?','Are you sure you want to delete this ticket? All bookings related to this ticket will be deleted once you save this %s.'=>'ಈ ಟಿಕೆಟ್ ಅನ್ನು ಅಳಿಸಲು ನೀವು ಖಚಿತವಾಗಿ ಬಯಸುವಿರಾ? ನೀವು ಈ %s ಅನ್ನು ಉಳಿಸಿದ ನಂತರ ಈ ಟಿಕೆಟ್‌ಗೆ ಸಂಬಂಧಿಸಿದ ಎಲ್ಲಾ ಬುಕಿಂಗ್‌ಗಳನ್ನು ಅಳಿಸಲಾಗುತ್ತದೆ.','Are you sure you want to delete?'=>'ಅಳಿಸಲು ನೀವು ಖಚಿತವಾಗಿ ಬಯಸುವಿರಾ?','Are you sure you want to delete? This action cannot be undone.'=>'ಅಳಿಸಲು ನೀವು ಖಚಿತವಾಗಿ ಬಯಸುವಿರಾ? ಈ ಕ್ರಿಯೆಯನ್ನು ಹಿಂದಿರುಗಿಸಲಾಗುವುದಿಲ್ಲ.','Are you sure you want to detach this event? By doing so, this event will be independent of the recurring set of events.'=>'ಈ ಈವೆಂಟ್ ಅನ್ನು ಬೇರ್ಪಡಿಸಲು ನೀವು ಖಚಿತವಾಗಿ ಬಯಸುವಿರಾ? ಹಾಗೆ ಮಾಡಿದರೆ, ಈ ಈವೆಂಟ್ ಪುನರಾವರ್ತಿತ ಈವೆಂಟ್‌ಗಳ ಗುಂಪಿನಿಂದ ಸ್ವತಂತ್ರವಾಗುತ್ತದೆ.','Are you sure you want to disable bookings? If you do this and save, you will lose all previous bookings. If you wish to prevent further bookings, reduce the number of spaces available to the amount of bookings you currently have'=>'ಬುಕಿಂಗ್‌ಗಳನ್ನು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಲು ನೀವು ಖಚಿತವಾಗಿ ಬಯಸುವಿರಾ? ನೀವು ಹೀಗೆ ಮಾಡಿ ಉಳಿಸಿದರೆ, ಎಲ್ಲಾ ಹಿಂದಿನ ಬುಕಿಂಗ್‌ಗಳನ್ನು ಕಳೆದುಕೊಳ್ಳುತ್ತೀರಿ. ಹೆಚ್ಚಿನ ಬುಕಿಂಗ್‌ಗಳನ್ನು ತಡೆಯಲು ಬಯಸಿದರೆ, ಲಭ್ಯವಿರುವ ಸ್ಥಾನಗಳ ಸಂಖ್ಯೆಯನ್ನು ನಿಮ್ಮ ಪ್ರಸ್ತುತ ಬುಕಿಂಗ್‌ಗಳ ಸಂಖ್ಯೆಗೆ ಇಳಿಸಿ','Are you sure you want to proceed? We recommend you back up your database first, just in case!'=>'ನೀವು ಮುಂದುವರಿಯಲು ಖಚಿತವಾಗಿ ಬಯಸುವಿರಾ? ಮುನ್ನೆಚ್ಚರಿಕೆಯಾಗಿ ಮೊದಲು ನಿಮ್ಮ ಡೇಟಾಬೇಸ್ ಅನ್ನು ಬ್ಯಾಕಪ್ ಮಾಡಲು ನಾವು ಶಿಫಾರಸು ಮಾಡುತ್ತೇವೆ!','Are you sure you want to reset Events Manager?'=>'Events Manager ಅನ್ನು ಮರುಹೊಂದಿಸಲು ನೀವು ಖಚಿತವಾಗಿ ಬಯಸುವಿರಾ?','Are you sure you want to uninstall Events Manager?'=>'Events Manager ಅನ್ನು ಅನ್‌ಇನ್‌ಸ್ಟಾಲ್ ಮಾಡಲು ನೀವು ಖಚಿತವಾಗಿ ಬಯಸುವಿರಾ?','As a site admin, you see all group events, users will only be able to choose groups they are admins of.'=>'ಜಾಲತಾಣ ನಿರ್ವಹಣೆಗಾರರಾಗಿ ನೀವು ಎಲ್ಲಾ ಗುಂಪು ಈವೆಂಟ್‌ಗಳನ್ನು ನೋಡುತ್ತೀರಿ, ಬಳಕೆದಾರರು ತಾವು ನಿರ್ವಾಹಕರಾಗಿರುವ ಗುಂಪುಗಳನ್ನು ಮಾತ್ರ ಆಯ್ಕೆ ಮಾಡಬಹುದು.','Ascending'=>'ಆರೋಹಣ','Aside from pages we automatically generate and include certain jQuery files, if you are using Widgets, Shortcode or PHP to display specific items you may need to tell us where you are using them for them to work properly. Below are options for you to include specific jQuery dependencies only on certain pages.'=>'ನಾವು ಸ್ವಯಂಚಾಲಿತವಾಗಿ ರಚಿಸುವ ಮತ್ತು ಕೆಲವು jQuery ಫೈಲ್‌ಗಳನ್ನು ಸೇರಿಸುವ ಪುಟಗಳ ಹೊರತಾಗಿ, ನೀವು ವಿಜೆಟ್‌ಗಳು, ಶಾರ್ಟ್‌ಕೋಡ್ ಅಥವಾ PHP ಬಳಸಿ ನಿರ್ದಿಷ್ಟ ಐಟಂಗಳನ್ನು ಪ್ರದರ್ಶಿಸುತ್ತಿದ್ದರೆ, ಅವು ಸರಿಯಾಗಿ ಕೆಲಸ ಮಾಡಲು ನೀವು ಅವುಗಳನ್ನು ಎಲ್ಲಿ ಬಳಸುತ್ತಿದ್ದೀರಿ ಎಂದು ನಮಗೆ ತಿಳಿಸಬೇಕಾಗಬಹುದು. ನಿರ್ದಿಷ್ಟ ಪುಟಗಳಲ್ಲಿ ಮಾತ್ರ ನಿರ್ದಿಷ್ಟ jQuery ಅವಲಂಬನೆಗಳನ್ನು ಸೇರಿಸಲು ಆಯ್ಕೆಗಳು ಕೆಳಗಿವೆ.','Attachment ID not found.'=>'ಲಗತ್ತು ID ಕಂಡುಬಂದಿಲ್ಲ.','Attendee %d'=>'ಹಾಜರಾತಿದಾರ %d','Attendee %s'=>'ಹಾಜರಾತಿದಾರ %s','Attendee (Per Space Booked)'=>'ಹಾಜರಾತಿದಾರ (ಬುಕ್ ಮಾಡಿದ ಪ್ರತಿ ಸ್ಥಾನಕ್ಕೆ)','Attendee names, answers to attendee fields and check-in status are copied and kept with each ticket. Without Events Manager Pro they are not shown, so you will see each booking, its tickets and the person who booked.'=>'ಹಾಜರಾತಿದಾರರ ಹೆಸರುಗಳು, ಹಾಜರಾತಿದಾರರ ಕ್ಷೇತ್ರಗಳಿಗೆ ಉತ್ತರಗಳು ಮತ್ತು ಚೆಕ್-ಇನ್ ಸ್ಥಿತಿಯನ್ನು ನಕಲಿಸಿ ಪ್ರತಿ ಟಿಕೆಟ್‌ನೊಂದಿಗೆ ಇರಿಸಲಾಗುತ್ತದೆ. Events Manager Pro ಇಲ್ಲದಿದ್ದರೆ ಅವು ತೋರಿಸುವುದಿಲ್ಲ, ಆದ್ದರಿಂದ ನೀವು ಪ್ರತಿ ಬುಕಿಂಗ್, ಅದರ ಟಿಕೆಟ್‌ಗಳು ಮತ್ತು ಬುಕ್ ಮಾಡಿದ ವ್ಯಕ್ತಿಯನ್ನು ನೋಡುತ್ತೀರಿ.','Attendees'=>'ಹಾಜರಾತಿದಾರರು','Attending'=>'ಹಾಜರಾಗುತ್ತಿದ್ದಾರೆ','Attributes'=>'ಗುಣಲಕ್ಷಣಗಳು','AutoTLS'=>'ಆಟೋ TLS','Avail. Spaces'=>'ಲಭ್ಯ ಸ್ಥಾನಗಳು','Availability'=>'ಲಭ್ಯತೆ','Available'=>'ಲಭ್ಯವಿದೆ','Available Archetypes'=>'ಲಭ್ಯವಿರುವ ಆರ್ಕಿಟೈಪ್‌ಗಳು','Available Spaces'=>'ಲಭ್ಯವಿರುವ ಸ್ಥಾನಗಳು','Available for'=>'ಇವರಿಗೆ ಲಭ್ಯ','Available from'=>'ಇಂದಿನಿಂದ ಲಭ್ಯ','Available spaces'=>'ಲಭ್ಯವಿರುವ ಸ್ಥಾನಗಳು','Available until'=>'ಇದರವರೆಗೆ ಲಭ್ಯ','Average Sale'=>'ಸರಾಸರಿ ಮಾರಾಟ','Average Ticket'=>'ಸರಾಸರಿ ಟಿಕೆಟ್','Awaiting Online Payment'=>'ಆನ್‌ಲೈನ್ ಪಾವತಿಗಾಗಿ ಕಾಯಲಾಗುತ್ತಿದೆ','Awaiting Payment'=>'ಪಾವತಿಗಾಗಿ ಕಾಯಲಾಗುತ್ತಿದೆ','Bar Graph'=>'ಬಾರ್ ಗ್ರಾಫ್','Base Event Settings'=>'ಮೂಲ ಈವೆಂಟ್ ಸೆಟ್ಟಿಂಗ್‌ಗಳು','Base Location Settings'=>'ಮೂಲ ಸ್ಥಳ ಸೆಟ್ಟಿಂಗ್‌ಗಳು','Base font size'=>'ಮೂಲ ಫಾಂಟ್ ಗಾತ್ರ','Base font weight'=>'ಮೂಲ ಫಾಂಟ್ ತೂಕ','Base line height'=>'ಮೂಲ ಸಾಲಿನ ಎತ್ತರ','Basic HTML is allowed in ticket labels and descriptions.'=>'ಟಿಕೆಟ್ ಲೇಬಲ್‌ಗಳು ಮತ್ತು ವಿವರಣೆಗಳಲ್ಲಿ ಮೂಲ HTML ಅನ್ನು ಅನುಮತಿಸಲಾಗಿದೆ.','Basic Only'=>'ಮೂಲ ಮಾತ್ರ','Be aware that some themes will not work with this option, if so (or you want to make your own changes), you can create a file named <code>single-%s.php</code> <a href=\'#\'>as shown on the WordPress codex</a>, and leave this set to Posts.'=>'ಕೆಲವು ಥೀಮ್‌ಗಳು ಈ ಆಯ್ಕೆಯೊಂದಿಗೆ ಕೆಲಸ ಮಾಡುವುದಿಲ್ಲ ಎಂಬುದನ್ನು ಗಮನಿಸಿ, ಹಾಗಿದ್ದರೆ (ಅಥವಾ ನೀವು ನಿಮ್ಮದೇ ಬದಲಾವಣೆಗಳನ್ನು ಮಾಡಲು ಬಯಸಿದರೆ), <a href=\'#\'>WordPress ಕೋಡೆಕ್ಸ್‌ನಲ್ಲಿ ತೋರಿಸಿರುವಂತೆ</a> <code>single-%s.php</code> ಹೆಸರಿನ ಫೈಲ್ ರಚಿಸಬಹುದು, ಮತ್ತು ಇದನ್ನು ಪೋಸ್ಟ್‌ಗಳು ಎಂದೇ ಬಿಡಿ.','Before'=>'ಮೊದಲು','Before you save your changes, you can quickly send yourself a test email by clicking this button.'=>'ನಿಮ್ಮ ಬದಲಾವಣೆಗಳನ್ನು ಉಳಿಸುವ ಮೊದಲು, ಈ ಬಟನ್ ಕ್ಲಿಕ್ ಮಾಡುವ ಮೂಲಕ ನಿಮಗೇ ತ್ವರಿತವಾಗಿ ಪರೀಕ್ಷಾ ಇಮೇಲ್ ಕಳುಹಿಸಬಹುದು.','Below are translations for your location address. If left blank, the language of the original event will be used.'=>'ನಿಮ್ಮ ಸ್ಥಳದ ವಿಳಾಸದ ಭಾಷಾಂತರಗಳು ಕೆಳಗಿವೆ. ಖಾಲಿ ಬಿಟ್ಟರೆ, ಮೂಲ ಈವೆಂಟ್‌ನ ಭಾಷೆಯನ್ನು ಬಳಸಲಾಗುತ್ತದೆ.','Below are translations for your tickets. If left blank, the language of the original event will be used.'=>'ನಿಮ್ಮ ಟಿಕೆಟ್‌ಗಳ ಭಾಷಾಂತರಗಳು ಕೆಳಗಿವೆ. ಖಾಲಿ ಬಿಟ್ಟರೆ, ಮೂಲ ಈವೆಂಟ್‌ನ ಭಾಷೆಯನ್ನು ಬಳಸಲಾಗುತ್ತದೆ.','Below you will find texts that will be displayed to users in various areas during the bookings process, particularly on booking forms.'=>'ಬುಕಿಂಗ್ ಪ್ರಕ್ರಿಯೆಯ ವಿವಿಧ ಭಾಗಗಳಲ್ಲಿ, ವಿಶೇಷವಾಗಿ ಬುಕಿಂಗ್ ಫಾರ್ಮ್‌ಗಳಲ್ಲಿ, ಬಳಕೆದಾರರಿಗೆ ಪ್ರದರ್ಶಿಸಲಾಗುವ ಪಠ್ಯಗಳನ್ನು ಕೆಳಗೆ ಕಾಣಬಹುದು.','Block Editor (Gutenberg)'=>'ಬ್ಲಾಕ್ ಸಂಪಾದಕ (Gutenberg)','Block Editor development is still ongoing, switch back to the Classic Editor if you experience issues.'=>'ಬ್ಲಾಕ್ ಸಂಪಾದಕದ ಅಭಿವೃದ್ಧಿ ಇನ್ನೂ ಮುಂದುವರಿದಿದೆ, ಸಮಸ್ಯೆಗಳು ಎದುರಾದರೆ ಕ್ಲಾಸಿಕ್ ಸಂಪಾದಕಕ್ಕೆ ಹಿಂತಿರುಗಿ.','Block editor layout'=>'ಬ್ಲಾಕ್ ಸಂಪಾದಕದ ಲೆಔಟ್','Blog Default Timezone'=>'ಬ್ಲಾಗ್ ಡೀಫಾಲ್ಟ್ ಸಮಯವಲಯ','Body Classes'=>'ಬಾಡಿ ಕ್ಲಾಸ್‌ಗಳು','Book Now'=>'ಈಗಲೇ ಬುಕ್ ಮಾಡಿ','Book Now!'=>'ಈಗಲೇ ಬುಕ್ ಮಾಡಿ!','Booked'=>'ಬುಕ್ ಆಗಿದೆ','Booked Spaces'=>'ಬುಕ್ ಆದ ಸ್ಥಾನಗಳು','Booked User Emails'=>'ಬುಕ್ ಮಾಡಿದ ಬಳಕೆದಾರರ ಇಮೇಲ್‌ಗಳು','Booked/Available'=>'ಬುಕ್ ಆದ/ಲಭ್ಯ','Booking'=>'ಬುಕಿಂಗ್','Booking %s'=>'ಬುಕಿಂಗ್ %s','Booking %s.'=>'ಬುಕಿಂಗ್ %s.','Booking Actions'=>'ಬುಕಿಂಗ್ ಕ್ರಿಯೆಗಳು','Booking Cancellation Warning'=>'ಬುಕಿಂಗ್ ರದ್ದತಿ ಎಚ್ಚರಿಕೆ','Booking Cancelled'=>'ಬುಕಿಂಗ್ ರದ್ದುಗೊಳಿಸಲಾಗಿದೆ','Booking Chart'=>'ಬುಕಿಂಗ್ ಚಾರ್ಟ್','Booking Comment'=>'ಬುಕಿಂಗ್ ಪ್ರತಿಕ್ರಿಯೆ','Booking Confirmation'=>'ಬುಕಿಂಗ್ ದೃಢೀಕರಣ','Booking Confirmed'=>'ಬುಕಿಂಗ್ ದೃಢೀಕರಿಸಲಾಗಿದೆ','Booking Cut-Off Date'=>'ಬುಕಿಂಗ್ ಕೊನೆಯ ದಿನಾಂಕ','Booking Data'=>'ಬುಕಿಂಗ್ ಡೇಟಾ','Booking Date'=>'ಬುಕಿಂಗ್ ದಿನಾಂಕ','Booking Details'=>'ಬುಕಿಂಗ್ ವಿವರಗಳು','Booking Email Templates'=>'ಬುಕಿಂಗ್ ಇಮೇಲ್ ಟೆಂಪ್ಲೇಟ್‌ಗಳು','Booking Form'=>'ಬುಕಿಂಗ್ ಫಾರ್ಮ್','Booking ID'=>'ಬುಕಿಂಗ್ ID','Booking ID.'=>'ಬುಕಿಂಗ್ ID.','Booking Intent'=>'ಬುಕಿಂಗ್ ಉದ್ದೇಶ','Booking Management Pages'=>'ಬುಕಿಂಗ್ ನಿರ್ವಹಣೆ ಪುಟಗಳು','Booking Meta'=>'ಬುಕಿಂಗ್ ಮೆಟಾ','Booking Notes'=>'ಬುಕಿಂಗ್ ಟಿಪ್ಪಣಿಗಳು','Booking Pending'=>'ಬುಕಿಂಗ್ ಬಾಕಿಯಿದೆ','Booking RSVP'=>'ಬುಕಿಂಗ್ RSVP','Booking RSVP status set to \'%s\'.'=>'ಬುಕಿಂಗ್ RSVP ಸ್ಥಿತಿಯನ್ನು \'%s\' ಎಂದು ಹೊಂದಿಸಲಾಗಿದೆ.','Booking Rejected'=>'ಬುಕಿಂಗ್ ತಿರಸ್ಕರಿಸಲಾಗಿದೆ','Booking Related Placeholders'=>'ಬುಕಿಂಗ್ ಸಂಬಂಧಿತ ಪ್ಲೇಸ್‌ಹೋಲ್ಡರ್‌ಗಳು','Booking Status'=>'ಬುಕಿಂಗ್ ಸ್ಥಿತಿ','Booking Statuses'=>'ಬುಕಿಂಗ್ ಸ್ಥಿತಿಗತಿಗಳು','Booking Submit Button'=>'ಬುಕಿಂಗ್ ಸಲ್ಲಿಕೆ ಗುಂಡಿ','Booking Summary'=>'ಬುಕಿಂಗ್ ಸಾರಾಂಶ','Booking admin pages'=>'ಬುಕಿಂಗ್ ನಿರ್ವಾಹಕ ಪುಟಗಳು','Booking already made'=>'ಬುಕಿಂಗ್ ಈಗಾಗಲೇ ಮಾಡಲಾಗಿದೆ','Booking button feedback messages'=>'ಬುಕಿಂಗ್ ಗುಂಡಿಯ ಅನಿಸಿಕೆ ಸಂದೇಶಗಳು','Booking cancellation emails are not sent.'=>'ಬುಕಿಂಗ್ ರದ್ದತಿ ಇಮೇಲ್‌ಗಳನ್ನು ಕಳುಹಿಸಲಾಗುವುದಿಲ್ಲ.','Booking cancellation emails will be sent.'=>'ಬುಕಿಂಗ್ ರದ್ದತಿ ಇಮೇಲ್‌ಗಳನ್ನು ಕಳುಹಿಸಲಾಗುತ್ತದೆ.','Booking cancellations'=>'ಬುಕಿಂಗ್ ರದ್ದತಿಗಳು','Booking cancelled'=>'ಬುಕಿಂಗ್ ರದ್ದುಗೊಳಿಸಲಾಗಿದೆ','Booking cancelled email'=>'ಬುಕಿಂಗ್ ರದ್ದತಿ ಇಮೇಲ್','Booking cancelled email subject'=>'ಬುಕಿಂಗ್ ರದ್ದತಿ ಇಮೇಲ್‌ನ ವಿಷಯ','Booking cannot be made, not enough spaces available!'=>'ಬುಕಿಂಗ್ ಮಾಡಲು ಸಾಧ್ಯವಿಲ್ಲ, ಸಾಕಷ್ಟು ಸ್ಥಾನಗಳು ಲಭ್ಯವಿಲ್ಲ!','Booking complete'=>'ಬುಕಿಂಗ್ ಪೂರ್ಣಗೊಂಡಿದೆ','Booking confirmed email'=>'ಬುಕಿಂಗ್ ದೃಢೀಕರಣ ಇಮೇಲ್','Booking confirmed email subject'=>'ಬುಕಿಂಗ್ ದೃಢೀಕರಣ ಇಮೇಲ್‌ನ ವಿಷಯ','Booking could not be %s.'=>'ಬುಕಿಂಗ್ ಅನ್ನು %s ಮಾಡಲಾಗಲಿಲ್ಲ.','Booking could not be created'=>'ಬುಕಿಂಗ್ ಅನ್ನು ರಚಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ','Booking could not be deleted.'=>'ಬುಕಿಂಗ್ ಅನ್ನು ಅಳಿಸಲಾಗಲಿಲ್ಲ.','Booking could not be saved.'=>'ಬುಕಿಂಗ್ ಅನ್ನು ಉಳಿಸಲಾಗಲಿಲ್ಲ.','Booking data is invalid.'=>'ಬುಕಿಂಗ್ ಡೇಟಾ ಅಮಾನ್ಯವಾಗಿದೆ.','Booking error'=>'ಬುಕಿಂಗ್ ದೋಷ','Booking form feedback messages'=>'ಬುಕಿಂಗ್ ಫಾರ್ಮ್ ಅನಿಸಿಕೆ ಸಂದೇಶಗಳು','Booking form section headers'=>'ಬುಕಿಂಗ್ ಫಾರ್ಮ್ ವಿಭಾಗದ ಶೀರ್ಷಿಕೆಗಳು','Booking form texts/messages'=>'ಬುಕಿಂಗ್ ಫಾರ್ಮ್ ಪಠ್ಯಗಳು/ಸಂದೇಶಗಳು','Booking in progress'=>'ಬುಕಿಂಗ್ ಪ್ರಗತಿಯಲ್ಲಿದೆ','Booking not found.'=>'ಬುಕಿಂಗ್ ಕಂಡುಬಂದಿಲ್ಲ.','Booking note successfully added.'=>'ಬುಕಿಂಗ್ ಟಿಪ್ಪಣಿಯನ್ನು ಯಶಸ್ವಿಯಾಗಿ ಸೇರಿಸಲಾಗಿದೆ.','Booking pending email'=>'ಬಾಕಿಯಿರುವ ಬುಕಿಂಗ್ ಇಮೇಲ್','Booking pending email subject'=>'ಬಾಕಿಯಿರುವ ಬುಕಿಂಗ್ ಇಮೇಲ್‌ನ ವಿಷಯ','Booking reference'=>'ಬುಕಿಂಗ್ ಉಲ್ಲೇಖ','Booking rejected email'=>'ಬುಕಿಂಗ್ ತಿರಸ್ಕಾರ ಇಮೇಲ್','Booking rejected email subject'=>'ಬುಕಿಂಗ್ ತಿರಸ್ಕಾರ ಇಮೇಲ್‌ನ ವಿಷಯ','Booking status could not be changed.'=>'ಬುಕಿಂಗ್ ಸ್ಥಿತಿಯನ್ನು ಬದಲಾಯಿಸಲಾಗಲಿಲ್ಲ.','Booking status is invalid.'=>'ಬುಕಿಂಗ್ ಸ್ಥಿತಿ ಅಮಾನ್ಯವಾಗಿದೆ.','Booking successful, pending confirmation (you will also receive an email once confirmed).'=>'ಬುಕಿಂಗ್ ಯಶಸ್ವಿಯಾಗಿದೆ, ದೃಢೀಕರಣಕ್ಕಾಗಿ ಬಾಕಿಯಿದೆ (ದೃಢೀಕರಿಸಿದ ನಂತರ ನಿಮಗೆ ಇಮೇಲ್ ಕೂಡ ಬರುತ್ತದೆ).','Booking successful.'=>'ಬುಕಿಂಗ್ ಯಶಸ್ವಿಯಾಗಿದೆ.','Booking summary default text'=>'ಬುಕಿಂಗ್ ಸಾರಾಂಶದ ಡೀಫಾಲ್ಟ್ ಪಠ್ಯ','Booking...'=>'ಬುಕ್ ಮಾಡಲಾಗುತ್ತಿದೆ...','Bookings'=>'ಬುಕಿಂಗ್‌ಗಳು','Bookings %s. Mails Sent.'=>'ಬುಕಿಂಗ್‌ಗಳು %s. ಮೇಲ್‌ಗಳನ್ನು ಕಳುಹಿಸಲಾಗಿದೆ.','Bookings Consent Error'=>'ಬುಕಿಂಗ್‌ಗಳ ಒಪ್ಪಿಗೆ ದೋಷ','Bookings Forms'=>'ಬುಕಿಂಗ್ ಫಾರ್ಮ್‌ಗಳು','Bookings Stats'=>'ಬುಕಿಂಗ್ ಅಂಕಿಅಂಶಗಳು','Bookings Table Settings'=>'ಬುಕಿಂಗ್ ಕೋಷ್ಟಕ ಸೆಟ್ಟಿಂಗ್ ಗಳು','Bookings View'=>'ಬುಕಿಂಗ್‌ಗಳ ವೀಕ್ಷಣೆ','Bookings are closed for this event.'=>'ಈ ಈವೆಂಟ್‌ಗೆ ಬುಕಿಂಗ್‌ಗಳನ್ನು ಮುಚ್ಚಲಾಗಿದೆ.','Bookings are disabled in Events Manager. Migrating tickets turns them on.'=>'Events Manager ನಲ್ಲಿ ಬುಕಿಂಗ್‌ಗಳು ನಿಷ್ಕ್ರಿಯಗೊಂಡಿವೆ. ಟಿಕೆಟ್‌ಗಳನ್ನು ವರ್ಗಾಯಿಸುವುದರಿಂದ ಅವು ಸಕ್ರಿಯಗೊಳ್ಳುತ್ತವೆ.','Bookings closed'=>'ಬುಕಿಂಗ್‌ಗಳು ಮುಚ್ಚಲಾಗಿದೆ','Bookings data'=>'ಬುಕಿಂಗ್‌ಗಳ ಡೇಟಾ','Bookings disabled'=>'ಬುಕಿಂಗ್‌ಗಳು ನಿಷ್ಕ್ರಿಯಗೊಂಡಿವೆ','Bookings for %s'=>'%s ಗಾಗಿ ಬುಕಿಂಗ್‌ಗಳು','Bookings have closed (e.g. event has started).'=>'ಬುಕಿಂಗ್‌ಗಳು ಮುಚ್ಚಲ್ಪಟ್ಟಿವೆ (ಉದಾ. ಈವೆಂಟ್ ಪ್ರಾರಂಭವಾಗಿದೆ).','Bookings that are uncancelled are returned to their previous state (if available), the %1$s PHP constant value or if previous options are not available then pending/approved according to your booking approval settings.'=>'ರದ್ದತಿ ತೆಗೆದ ಬುಕಿಂಗ್‌ಗಳು ಅವುಗಳ ಹಿಂದಿನ ಸ್ಥಿತಿಗೆ (ಲಭ್ಯವಿದ್ದರೆ), %1$s PHP ಕಾನ್ಸ್ಟಂಟ್ ಮೌಲ್ಯಕ್ಕೆ, ಅಥವಾ ಹಿಂದಿನ ಆಯ್ಕೆಗಳು ಲಭ್ಯವಿಲ್ಲದಿದ್ದರೆ ನಿಮ್ಮ ಬುಕಿಂಗ್ ಅನುಮೋದನೆ ಸೆಟ್ಟಿಂಗ್‌ಗಳ ಪ್ರಕಾರ ಬಾಕಿಯಿರುವ/ಅನುಮೋದಿತ ಸ್ಥಿತಿಗೆ ಹಿಂತಿರುಗುತ್ತವೆ.','Bookings to individual %s recurrences will be preserved unless you delete tickets or choose to reschedule and delete rescheduled recurrences.'=>'ಪ್ರತ್ಯೇಕ %s ಪುನರಾವರ್ತನೆಗಳ ಬುಕಿಂಗ್‌ಗಳನ್ನು, ನೀವು ಟಿಕೆಟ್‌ಗಳನ್ನು ಅಳಿಸದ ಹೊರತು ಅಥವಾ ಮರುನಿಗದಿ ಮಾಡಿ ಮರುನಿಗದಿಯಾದ ಪುನರಾವರ್ತನೆಗಳನ್ನು ಅಳಿಸಲು ಆಯ್ಕೆ ಮಾಡದ ಹೊರತು, ಉಳಿಸಿಕೊಳ್ಳಲಾಗುತ್ತದೆ.','Bookings to individual event recurrences will be preserved if event times and ticket settings are not modified.'=>'ಈವೆಂಟ್ ಸಮಯ ಮತ್ತು ಟಿಕೆಟ್ ಸೆಟ್ಟಿಂಗ್ ಗಳನ್ನು ಮಾರ್ಪಡಿಸದಿದ್ದರೆ ಪ್ರತ್ಯೇಕ ಈವೆಂಟ್ ಪುನರಾವರ್ತನೆಗಳ ಬುಕಿಂಗ್‌ಗಳನ್ನು ಉಳಿಸಿಕೊಳ್ಳಲಾಗುತ್ತದೆ.','Bookings will be automatically cancelled.'=>'ಬುಕಿಂಗ್‌ಗಳು ಸ್ವಯಂಚಾಲಿತವಾಗಿ ರದ್ದಾಗುತ್ತವೆ.','Bookings will not be confirmed until the event administrator approves it.'=>'ಈವೆಂಟ್ ನಿರ್ವಾಹಕರು ಅನುಮೋದಿಸುವವರೆಗೆ ಬುಕಿಂಗ್‌ಗಳನ್ನು ದೃಢೀಕರಿಸಲಾಗುವುದಿಲ್ಲ.','Bookings/Registration'=>'ಬುಕಿಂಗ್‌ಗಳು/ನೋಂದಣಿ','Buffer'=>'ಬಫರ್','Bulk Actions'=>'ಸಗಟು ಕ್ರಿಯೆಗಳು','Bulk actions'=>'ಸಗಟು ಕ್ರಿಯೆಗಳು','Button & page labels'=>'ಗುಂಡಿ ಮತ್ತು ಪುಟದ ಲೇಬಲ್‌ಗಳು','Buy %s'=>'%s ಖರೀದಿಸಿ','Buy on Woo.com'=>'Woo.com ನಲ್ಲಿ ಖರೀದಿಸಿ','By default, event spaces become unavailable once there are enough CONFIRMED bookings. To reserve spaces even if unapproved, choose yes.'=>'ಡೀಫಾಲ್ಟ್ ಆಗಿ, ಸಾಕಷ್ಟು ದೃಢೀಕರಿಸಲಾದ ಬುಕಿಂಗ್‌ಗಳಿದ್ದಾಗ ಈವೆಂಟ್ ಸ್ಥಾನಗಳು ಲಭ್ಯವಿರುವುದಿಲ್ಲ. ಅನುಮೋದಿಸದಿದ್ದರೂ ಸ್ಥಾನಗಳನ್ನು ಕಾಯ್ದಿರಿಸಲು, ಹೌದು ಎಂದು ಆರಿಸಿ.','By default, events that have an end date later than today will be included in searches, set this to yes to consider events that started \'yesterday\' as past.'=>'ಡೀಫಾಲ್ಟ್ ಆಗಿ, ಇಂದಿಗಿಂತ ನಂತರದ ಅಂತ್ಯ ದಿನಾಂಕ ಹೊಂದಿರುವ ಈವೆಂಟ್‌ಗಳನ್ನು ಹುಡುಕಾಟಗಳಲ್ಲಿ ಸೇರಿಸಲಾಗುತ್ತದೆ, \'ನಿನ್ನೆ\' ಪ್ರಾರಂಭವಾದ ಈವೆಂಟ್‌ಗಳನ್ನು ಹಿಂದಿನವು ಎಂದು ಪರಿಗಣಿಸಲು ಇದನ್ನು ಹೌದು ಎಂದು ಹೊಂದಿಸಿ.','By default, if a calendar day only has one event, it display a single event when clicking on the link of that calendar date. If you select Yes here, you will get always see a list of events.'=>'ಡೀಫಾಲ್ಟ್ ಆಗಿ, ದಿನಸೂಚಿಯ ದಿನದಲ್ಲಿ ಒಂದೇ ಈವೆಂಟ್ ಇದ್ದರೆ, ಆ ದಿನಾಂಕದ ಲಿಂಕ್ ಕ್ಲಿಕ್ ಮಾಡಿದಾಗ ಒಂದೇ ಈವೆಂಟ್ ತೋರಿಸುತ್ತದೆ. ಇಲ್ಲಿ ಹೌದು ಆರಿಸಿದರೆ, ನಿಮಗೆ ಯಾವಾಗಲೂ ಈವೆಂಟ್‌ಗಳ ಪಟ್ಟಿ ಕಾಣಿಸುತ್ತದೆ.','By default, if a guest tries to book an event using the email of a user account on your site they will be asked to log in, selecting yes will bypass this security measure.'=>'ಡೀಫಾಲ್ಟ್ ಆಗಿ, ಅತಿಥಿಯು ನಿಮ್ಮ ಜಾಲತಾಣದ ಬಳಕೆದಾರ ಖಾತೆಯ ಇಮೇಲ್ ಬಳಸಿ ಈವೆಂಟ್ ಬುಕ್ ಮಾಡಲು ಪ್ರಯತ್ನಿಸಿದರೆ ಅವರಿಗೆ ಲಾಗ್ ಇನ್ ಆಗಲು ಕೇಳಲಾಗುತ್ತದೆ; ಹೌದು ಎಂದು ಆರಿಸಿದರೆ ಈ ಭದ್ರತಾ ಕ್ರಮವನ್ನು ಬೈಪಾಸ್ ಮಾಡಲಾಗುತ್ತದೆ.','By default, when a booking is made by a user, this booking is tied to a user account, if the user is not registered nor logged in and guest bookings are enabled, an account will be created for them.'=>'ಡೀಫಾಲ್ಟ್ ಆಗಿ, ಬಳಕೆದಾರರು ಬುಕಿಂಗ್ ಮಾಡಿದಾಗ ಈ ಬುಕಿಂಗ್ ಅನ್ನು ಬಳಕೆದಾರ ಖಾತೆಗೆ ಜೋಡಿಸಲಾಗುತ್ತದೆ; ಬಳಕೆದಾರರು ನೋಂದಾಯಿತರಲ್ಲದಿದ್ದರೆ ಅಥವಾ ಲಾಗ್ ಇನ್ ಆಗಿಲ್ಲದಿದ್ದರೆ ಮತ್ತು ಅತಿಥಿ ಬುಕಿಂಗ್‌ಗಳು ಸಕ್ರಿಯವಾಗಿದ್ದರೆ, ಅವರಿಗಾಗಿ ಖಾತೆ ರಚಿಸಲಾಗುತ್ತದೆ.','By editing your primary recurrence set, you will change all subsequent default values of your other recurrences.'=>'ನಿಮ್ಮ ಪ್ರಾಥಮಿಕ ಪುನರಾವರ್ತನೆ ಗುಂಪನ್ನು ಸಂಪಾದಿಸುವ ಮೂಲಕ, ನಿಮ್ಮ ಇತರ ಪುನರಾವರ್ತನೆಗಳ ಎಲ್ಲಾ ನಂತರದ ಡೀಫಾಲ್ಟ್ ಮೌಲ್ಯಗಳನ್ನು ನೀವು ಬದಲಾಯಿಸುತ್ತೀರಿ.','By using formats, you can control how your %s are displayed from within the Events Manager <a href=\'#formats\' class=\'nav-tab-link\' rel=\'#em-menu-formats\'>Formatting</a> tab above without having to edit your theme files.'=>'ಸ್ವರೂಪಗಳನ್ನು ಬಳಸುವ ಮೂಲಕ, ನಿಮ್ಮ ಥೀಮ್ ಫೈಲ್‌ಗಳನ್ನು ಸಂಪಾದಿಸದೆಯೇ ಮೇಲಿನ Events Manager <a href=\'#formats\' class=\'nav-tab-link\' rel=\'#em-menu-formats\'>ಫಾರ್ಮ್ಯಾಟಿಂಗ್</a> ಟ್ಯಾಬ್‌ನಿಂದ ನಿಮ್ಮ %s ಹೇಗೆ ಪ್ರದರ್ಶಿಸಬೇಕೆಂದು ನೀವು ನಿಯಂತ್ರಿಸಬಹುದು.','CPT'=>'CPT','CPT (Plural)'=>'CPT (ಬಹುವಚನ)','CPT (Single)'=>'CPT (ಏಕವಚನ)','CPT name (plural) must contain only lowercase letters, numbers, and underscores.'=>'CPT ಹೆಸರು (ಬಹುವಚನ) ಕೇವಲ ಸಣ್ಣಕ್ಷರದ ಅಕ್ಷರಗಳು, ಸಂಖ್ಯೆಗಳು ಮತ್ತು ಅಂಡರ್‌ಸ್ಕೋರ್‌ಗಳನ್ನು ಮಾತ್ರ ಹೊಂದಿರಬೇಕು.','CPT name must contain only lowercase letters, numbers, and underscores.'=>'CPT ಹೆಸರು ಕೇವಲ ಸಣ್ಣಕ್ಷರದ ಅಕ್ಷರಗಳು, ಸಂಖ್ಯೆಗಳು ಮತ್ತು ಅಂಡರ್‌ಸ್ಕೋರ್‌ಗಳನ್ನು ಮಾತ್ರ ಹೊಂದಿರಬೇಕು.','CPTs'=>'CPT ಗಳು','CSS File'=>'CSS ಫೈಲ್','CSV file'=>'CSV ಫೈಲ್','CSV file does not appear to contain valid data.'=>'CSV ಫೈಲ್ ಮಾನ್ಯ ಡೇಟಾವನ್ನು ಹೊಂದಿರುವಂತೆ ತೋರುತ್ತಿಲ್ಲ.','Calendar'=>'ದಿನಸೂಚಿ','Calendar Day Event List Settings'=>'ದಿನಸೂಚಿ ದಿನದ ಈವೆಂಟ್ ಪಟ್ಟಿ ಸೆಟ್ಟಿಂಗ್‌ಗಳು','Calendar Selection'=>'ದಿನಸೂಚಿ ಆಯ್ಕೆ','Calendar Size'=>'ಕ್ಯಾಲೆಂಡರ್ ಗಾತ್ರ','Calendar events/day limit'=>'ದಿನಸೂಚಿಯ ಈವೆಂಟ್‌ಗಳು/ದಿನ ಮಿತಿ','Calendar settings'=>'ಕ್ಯಾಲೆಂಡರ್ ಸೆಟ್ಟಿಂಗ್‌ಗಳು','Calendar size'=>'ಕ್ಯಾಲೆಂಡರ್ ಗಾತ್ರ','Call get-booking-requirements with this event\'s ID for the exact required fields, their payload locations (attendee fields go under em_tickets[<ticket_id>].ticket_bookings[].attendee), and a ready-to-submit example.'=>'ನಿಖರವಾದ ಅಗತ್ಯ ಕ್ಷೇತ್ರಗಳು, ಅವುಗಳ ಪೇಲೋಡ್ ಸ್ಥಳಗಳು (ಹಾಜರಾತಿದಾರರ ಕ್ಷೇತ್ರಗಳು em_tickets[<ticket_id>].ticket_bookings[].attendee ಅಡಿಯಲ್ಲಿ ಹೋಗುತ್ತವೆ) ಮತ್ತು ಸಲ್ಲಿಸಲು ಸಿದ್ಧವಾದ ಉದಾಹರಣೆಗಾಗಿ ಈ ಈವೆಂಟ್‌ನ ID ಯೊಂದಿಗೆ get-booking-requirements ಅನ್ನು ಕರೆ ಮಾಡಿ.','Calling em_get_option() too early whilst EM\\Archetypes class is not available.'=>'EM\\Archetypes ಕ್ಲಾಸ್ ಲಭ್ಯವಿಲ್ಲದಿರುವಾಗ em_get_option() ಅನ್ನು ತುಂಬಾ ಬೇಗ ಕರೆಯಲಾಗುತ್ತಿದೆ.','Can attendees change their RSVP status? You can choose whether they can uncancel an RSVP below as well.'=>'ಹಾಜರಾತಿದಾರರು ತಮ್ಮ RSVP ಸ್ಥಿತಿಯನ್ನು ಬದಲಿಸಬಹುದೇ? RSVP ರದ್ದತಿಯನ್ನು ತೆಗೆಯಬಹುದೇ ಎಂಬುದನ್ನೂ ನೀವು ಕೆಳಗೆ ಆರಿಸಬಹುದು.','Can be in form of pixels or a percentage such as %s or %s.'=>'ಪಿಕ್ಸೆಲ್‌ಗಳು ಅಥವಾ %s ಅಥವಾ %s ನಂತಹ ಶೇಕಡಾವಾರು ರೂಪದಲ್ಲಿರಬಹುದು.','Can users cancel their booking?'=>'ಬಳಕೆದಾರರು ತಮ್ಮ ಬುಕಿಂಗ್ ಅನ್ನು ರದ್ದುಗೊಳಿಸಬಹುದೇ?','Can users uncancel their booking?'=>'ಬಳಕೆದಾರರು ತಮ್ಮ ಬುಕಿಂಗ್‌ನ ರದ್ದತಿಯನ್ನು ತೆಗೆಯಬಹುದೇ?','Cancel'=>'ರದ್ದು','Cancel Ticket Recreation'=>'ಟಿಕೆಟ್ ಮರುಸೃಷ್ಟಿಯನ್ನು ರದ್ದುಮಾಡಿ','Cancel all confirmed and pending bookings automatically.'=>'ದೃಢೀಕರಿಸಿದ ಮತ್ತು ಬಾಕಿಯಿರುವ ಎಲ್ಲಾ ಬುಕಿಂಗ್‌ಗಳನ್ನು ಸ್ವಯಂಚಾಲಿತವಾಗಿ ರದ್ದುಗೊಳಿಸಿ.','Cancel bookings?'=>'ಬುಕಿಂಗ್‌ಗಳನ್ನು ರದ್ದುಗೊಳಿಸುವುದೇ?','Cancelation complete'=>'ರದ್ದತಿ ಪೂರ್ಣಗೊಂಡಿದೆ','Cancelation error'=>'ರದ್ದತಿ ದೋಷ','Cancelation in progress'=>'ರದ್ದತಿ ಪ್ರಗತಿಯಲ್ಲಿದೆ','Canceling...'=>'ರದ್ದುಗೊಳಿಸಲಾಗುತ್ತಿದೆ...','Cancellation'=>'ರದ್ದತಿ','Cancellation Actions'=>'ರದ್ದತಿ ಕ್ರಿಯೆಗಳು','Cancellations'=>'ರದ್ದತಿಗಳು','Cancellations are not permitted for this booking.'=>'ಈ ಬುಕಿಂಗ್‌ಗೆ ರದ್ದುಗೊಳಿಸಲು ಅನುಮತಿ ಇಲ್ಲ.','Cancelled'=>'ರದ್ದುಗೊಳಿಸಲಾಗಿದೆ','Cancelled event email'=>'ರದ್ದುಗೊಂಡ ಈವೆಂಟ್ ಇಮೇಲ್','Cannot create a Archetype CPT name %s, this must be at most 20 characters long, containing letters, numbers, dashes and underscores only.'=>'%s ಹೆಸರಿನ ಆರ್ಕಿಟೈಪ್ CPT ಅನ್ನು ರಚಿಸಲಾಗುವುದಿಲ್ಲ, ಇದು ಗರಿಷ್ಠ 20 ಅಕ್ಷರಗಳ ಉದ್ದವಿರಬೇಕು ಮತ್ತು ಅಕ್ಷರಗಳು, ಸಂಖ್ಯೆಗಳು, ಡ್ಯಾಶ್‌ಗಳು ಮತ್ತು ಅಂಡರ್‌ಸ್ಕೋರ್‌ಗಳನ್ನು ಮಾತ್ರ ಹೊಂದಿರಬೇಕು.','Canvas tabs'=>'ಕ್ಯಾನ್ವಾಸ್ ಟ್ಯಾಬ್‌ಗಳು','Categories'=>'ವರ್ಗಗಳು','Categories dropdown label'=>'ವರ್ಗಗಳ ಡ್ರಾಪ್‌ಡೌನ್ ಲೇಬಲ್','Categories list page'=>'ವರ್ಗಗಳ ಪಟ್ಟಿ ಪುಟ','Category'=>'ವಿಭಾಗ','Category IDs'=>'ವರ್ಗ IDಗಳು','Category Related Placeholders'=>'ವರ್ಗ ಸಂಬಂಧಿತ ಪ್ಲೇಸ್‌ಹೋಲ್ಡರ್‌ಗಳು','Category pages'=>'ವರ್ಗ ಪುಟಗಳು','Category:'=>'ವರ್ಗ:','Change'=>'ಬದಲಿಸಿ','Changed timeslots get %s'=>'ಬದಲಾದ ಸಮಯಾವಕಾಶಗಳಿಗೆ %s','Changes a booking status, such as approving, rejecting, or cancelling it.'=>'ಬುಕಿಂಗ್ ಅನ್ನು ಅನುಮೋದಿಸುವುದು, ತಿರಸ್ಕರಿಸುವುದು ಅಥವಾ ರದ್ದುಗೊಳಿಸುವಂತಹ ಬುಕಿಂಗ್ ಸ್ಥಿತಿಯನ್ನು ಬದಲಾಯಿಸುತ್ತದೆ.','Changes saved'=>'ಬದಲಾವಣೆಗಳನ್ನು ಉಳಿಸಲಾಗಿದೆ','Changes saved.'=>'ಬದಲಾವಣೆಗಳನ್ನು ಉಳಿಸಲಾಗಿದೆ.','Changing the location of this event will delete its %s meeting or broadcast, and anyone holding the old link will no longer be able to join.'=>'ಈ ಈವೆಂಟ್‌ನ ಸ್ಥಳವನ್ನು ಬದಲಾಯಿಸುವುದರಿಂದ ಅದರ %s ಮೀಟಿಂಗ್ ಅಥವಾ ಪ್ರಸಾರ ಅಳಿಸಲ್ಪಡುತ್ತದೆ, ಮತ್ತು ಹಳೆಯ ಲಿಂಕ್ ಹೊಂದಿರುವವರು ಇನ್ನು ಸೇರಲು ಸಾಧ್ಯವಾಗುವುದಿಲ್ಲ.','Chart Options'=>'ಚಾರ್ಟ್ ಆಯ್ಕೆಗಳು','Chart Type'=>'ಚಾರ್ಟ್ ಪ್ರಕಾರ','Check Dev Versions'=>'ಡೆವ್ ಆವೃತ್ತಿಗಳನ್ನು ಪರಿಶೀಲಿಸಿ','Check attendees in at the door by scanning tickets, manage events and bookings, and follow booking and sales status from your phone. Available on the App Store for iPhone and iPad. Included with Pro Plus, or available by subscription for any Events Manager site.'=>'ಟಿಕೆಟ್‌ಗಳನ್ನು ಸ್ಕ್ಯಾನ್ ಮಾಡುವ ಮೂಲಕ ಬಾಗಿಲಲ್ಲಿ ಹಾಜರಾತಿದಾರರನ್ನು ಚೆಕ್ ಇನ್ ಮಾಡಿ, ಈವೆಂಟ್‌ಗಳು ಮತ್ತು ಬುಕಿಂಗ್‌ಗಳನ್ನು ನಿರ್ವಹಿಸಿ, ಮತ್ತು ನಿಮ್ಮ ಫೋನ್‌ನಿಂದ ಬುಕಿಂಗ್ ಮತ್ತು ಮಾರಾಟ ಸ್ಥಿತಿಯನ್ನು ಅನುಸರಿಸಿ. iPhone ಮತ್ತು iPad ಗಾಗಿ App Store ನಲ್ಲಿ ಲಭ್ಯವಿದೆ. Pro Plus ನೊಂದಿಗೆ ಸೇರಿಸಲಾಗಿದೆ, ಅಥವಾ ಯಾವುದೇ Events Manager ಸೈಟ್‌ಗೆ ಚಂದಾದಾರಿಕೆಯ ಮೂಲಕ ಲಭ್ಯವಿದೆ.','Check this option if you want the event contact to receive an email when someone books places. An email will be sent when a booking is first made (regardless if confirmed or pending)'=>'ಯಾರಾದರೂ ಸ್ಥಾನಗಳನ್ನು ಬುಕ್ ಮಾಡಿದಾಗ ಈವೆಂಟ್ ಸಂಪರ್ಕದವರಿಗೆ ಇಮೇಲ್ ಬರಬೇಕೆಂದಿದ್ದರೆ ಈ ಆಯ್ಕೆಯನ್ನು ಗುರುತಿಸಿ. ಬುಕಿಂಗ್ ಮೊದಲ ಬಾರಿ ಮಾಡಿದಾಗ (ದೃಢೀಕೃತ ಅಥವಾ ಬಾಕಿಯಿರುವ ಎಂಬುದನ್ನು ಲೆಕ್ಕಿಸದೆ) ಇಮೇಲ್ ಕಳುಹಿಸಲಾಗುತ್ತದೆ','Check this option if you want to prevent the WordPress registration email from going out when a user anonymously books an event.'=>'ಬಳಕೆದಾರರು ಅನಾಮಧೇಯವಾಗಿ ಈವೆಂಟ್ ಬುಕ್ ಮಾಡಿದಾಗ WordPress ನೋಂದಣಿ ಇಮೇಲ್ ಹೋಗುವುದನ್ನು ತಡೆಯಬೇಕೆಂದಿದ್ದರೆ ಈ ಆಯ್ಕೆಯನ್ನು ಗುರುತಿಸಿ.','Check this option to enable Google Map integration.'=>'Google ನಕ್ಷೆಗಳ ಏಕೀಕರಣವನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಲು ಈ ಆಯ್ಕೆಯನ್ನು ಟಿಕ್ ಮಾಡಿ.','Checking for dev versions.'=>'ಡೆವ್ ಆವೃತ್ತಿಗಳಿಗಾಗಿ ಪರಿಶೀಲಿಸಲಾಗುತ್ತಿದೆ.','Checking for the latest stable version.'=>'ಇತ್ತೀಚಿನ ಸ್ಥಿರ ಆವೃತ್ತಿಗಾಗಿ ಪರಿಶೀಲಿಸಲಾಗುತ್ತಿದೆ.','Checking...'=>'ಪರಿಶೀಲಿಸಲಾಗುತ್ತಿದೆ...','Checks WordPress.org directly for the latest stable release, skipping the staggered rollout delay (which can take up to 24 hours). Any newer stable version will appear on your Plugins or Updates page for a manual update.'=>'ಹಂತಹಂತದ ಬಿಡುಗಡೆಯ ವಿಳಂಬವನ್ನು (24 ಗಂಟೆಗಳವರೆಗೆ ಆಗಬಹುದು) ಬಿಟ್ಟು, ಇತ್ತೀಚಿನ ಸ್ಥಿರ ಬಿಡುಗಡೆಗಾಗಿ WordPress.org ಅನ್ನು ನೇರವಾಗಿ ಪರಿಶೀಲಿಸುತ್ತದೆ. ಯಾವುದೇ ಹೊಸ ಸ್ಥಿರ ಆವೃತ್ತಿಯು ಕೈಯಾರೆ ಅಪ್‌ಡೇಟ್ ಮಾಡಲು ನಿಮ್ಮ ಪ್ಲಗಿನ್‌ಗಳು ಅಥವಾ ಅಪ್‌ಡೇಟ್‌ಗಳ ಪುಟದಲ್ಲಿ ಕಾಣಿಸುತ್ತದೆ.','Choose a color for your %s. You can access this using the %s placeholder.'=>'ನಿಮ್ಮ %s ಗಾಗಿ ಒಂದು ಬಣ್ಣವನ್ನು ಆರಿಸಿ. ಇದನ್ನು %s ಪ್ಲೇಸ್‌ಹೋಲ್ಡರ್ ಬಳಸಿ ಪಡೆಯಬಹುದು.','Choose a settings file saved from a backup or another Events Manager installation and click the \'%s\' button.'=>'ಬ್ಯಾಕಪ್‌ನಿಂದ ಅಥವಾ ಇನ್ನೊಂದು Events Manager ಸ್ಥಾಪನೆಯಿಂದ ಉಳಿಸಿದ ಸೆಟ್ಟಿಂಗ್‌ಗಳ ಕಡತವನ್ನು ಆರಿಸಿ ಮತ್ತು \'%s\' ಗುಂಡಿಯನ್ನು ಕ್ಲಿಕ್ ಮಾಡಿ.','Choose an image for your %s, which can be displayed using the %s placeholder.'=>'ನಿಮ್ಮ %s ಗಾಗಿ ಒಂದು ಚಿತ್ರವನ್ನು ಆರಿಸಿ, ಅದನ್ನು %s ಪ್ಲೇಸ್‌ಹೋಲ್ಡರ್ ಬಳಸಿ ಪ್ರದರ್ಶಿಸಬಹುದು.','Choose another file'=>'ಬೇರೆ ಫೈಲ್ ಆಯ್ಕೆಮಾಡಿ','Choose from most used %s'=>'ಹೆಚ್ಚು ಬಳಸಿದ %s ಇಂದ ಆರಿಸಿ','Choose from most used event categories'=>'ಹೆಚ್ಚು ಬಳಸಿದ ಈವೆಂಟ್ ವರ್ಗಗಳಿಂದ ಆರಿಸಿ','Choose from most used event tags'=>'ಹೆಚ್ಚು ಬಳಸಿದ ಈವೆಂಟ್ ಟ್ಯಾಗ್‌ಗಳಿಂದ ಆರಿಸಿ','Choose graph type and stacking view options. Some views and stacking may not be available for all setting combinations.'=>'ಗ್ರಾಫ್ ಪ್ರಕಾರ ಮತ್ತು ಸ್ಟ್ಯಾಕಿಂಗ್ ವೀಕ್ಷಣೆ ಆಯ್ಕೆಗಳನ್ನು ಆರಿಸಿ. ಎಲ್ಲಾ ಸೆಟ್ಟಿಂಗ್ ಸಂಯೋಜನೆಗಳಿಗೆ ಕೆಲವು ವೀಕ್ಷಣೆಗಳು ಮತ್ತು ಸ್ಟ್ಯಾಕಿಂಗ್ ಲಭ್ಯವಿಲ್ಲದಿರಬಹುದು.','Choose how prices are displayed. <code>@</code> will be replaced by the currency symbol, and <code>#</code> will be replaced by the number.'=>'ಬೆಲೆಗಳನ್ನು ಹೇಗೆ ಪ್ರದರ್ಶಿಸಬೇಕೆಂದು ಆರಿಸಿ. <code>@</code> ಅನ್ನು ಕರೆನ್ಸಿ ಚಿಹ್ನೆಯಿಂದ ಮತ್ತು <code>#</code> ಅನ್ನು ಸಂಖ್ಯೆಯಿಂದ ಬದಲಾಯಿಸಲಾಗುತ್ತದೆ.','Choose how timeslots are listed in booking forms for recurring events and events with multiple timeslots.'=>'ಪುನರಾವರ್ತಿತ ಈವೆಂಟ್‌ಗಳು ಮತ್ತು ಬಹು ಸಮಯ ಸ್ಲಾಟ್‌ಗಳಿರುವ ಈವೆಂಟ್‌ಗಳಿಗಾಗಿ ಬುಕಿಂಗ್ ಫಾರ್ಮ್‌ಗಳಲ್ಲಿ ಸಮಯ ಸ್ಲಾಟ್‌ಗಳನ್ನು ಹೇಗೆ ಪಟ್ಟಿ ಮಾಡಬೇಕೆಂದು ಆರಿಸಿ.','Choose how to format your group heading dates. Leave blank for default.'=>'ನಿಮ್ಮ ಗುಂಪು ಶಿರೋನಾಮೆಯ ದಿನಾಂಕಗಳನ್ನು ಹೇಗೆ ಫಾರ್ಮ್ಯಾಟ್ ಮಾಡಬೇಕೆಂದು ಆರಿಸಿ. ಡೀಫಾಲ್ಟ್‌ಗಾಗಿ ಖಾಲಿ ಬಿಡಿ.','Choose how to format your group headings.'=>'ನಿಮ್ಮ ಗುಂಪು ಶಿರೋನಾಮೆಗಳನ್ನು ಹೇಗೆ ಫಾರ್ಮ್ಯಾಟ್ ಮಾಡಬೇಕೆಂದು ಆರಿಸಿ.','Choose how to show a information about an event when clicking or hovering over a single event on the calendar.'=>'ದಿನಸೂಚಿಯಲ್ಲಿ ಒಂದು ಈವೆಂಟ್ ಮೇಲೆ ಕ್ಲಿಕ್ ಮಾಡಿದಾಗ ಅಥವಾ ಸುಳಿದಾಡಿದಾಗ ಅದರ ಮಾಹಿತಿಯನ್ನು ಹೇಗೆ ತೋರಿಸಬೇಕೆಂದು ಆರಿಸಿ.','Choose the start date for comparing equivalent date ranges. The latest comparison end date is day before main duration start date.'=>'ಸಮಾನ ದಿನಾಂಕ ಶ್ರೇಣಿಗಳನ್ನು ಹೋಲಿಸಲು ಆರಂಭ ದಿನಾಂಕವನ್ನು ಆರಿಸಿ. ಹೋಲಿಕೆಯ ಕೊನೆಯ ದಿನಾಂಕವು ಮುಖ್ಯ ಅವಧಿಯ ಆರಂಭ ದಿನಾಂಕದ ಹಿಂದಿನ ದಿನವಾಗಿರುತ್ತದೆ.','Choose to show events within a specific time range.'=>'ನಿರ್ದಿಷ್ಟ ಸಮಯದ ವ್ಯಾಪ್ತಿಯೊಳಗಿನ ಈವೆಂಟ್‌ಗಳನ್ನು ತೋರಿಸಲು ಆರಿಸಿ.','Choose what to show users on their booking management page.'=>'ಬಳಕೆದಾರರ ಬುಕಿಂಗ್ ನಿರ್ವಹಣಾ ಪುಟದಲ್ಲಿ ಅವರಿಗೆ ಏನನ್ನು ತೋರಿಸಬೇಕೆಂದು ಆರಿಸಿ.','Choose whether or not to display a login form in the booking form area to remind your members to log in before booking.'=>'ನಿಮ್ಮ ಸದಸ್ಯರಿಗೆ ಬುಕಿಂಗ್ ಮಾಡುವ ಮೊದಲು ಲಾಗ್ ಇನ್ ಆಗಲು ನೆನಪಿಸಲು, ಬುಕಿಂಗ್ ಫಾರ್ಮ್ ಪ್ರದೇಶದಲ್ಲಿ ಲಾಗಿನ್ ಫಾರ್ಮ್ ಅನ್ನು ಪ್ರದರ್ಶಿಸಬೇಕೇ ಬೇಡವೇ ಎಂದು ಆರಿಸಿ.','Choose whether to display the main search bar. If disabled, advanced search fields will be shown in \'Inline\' mode automatically. You must also choose to enable at least one advanced search field, to avoid having an emtpy search form.'=>'ಮುಖ್ಯ ಹುಡುಕಾಟ ಪಟ್ಟಿಯನ್ನು ತೋರಿಸಬೇಕೇ ಎಂದು ಆರಿಸಿ. ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಿದರೆ, ಸುಧಾರಿತ ಹುಡುಕಾಟ ಕ್ಷೇತ್ರಗಳನ್ನು \'Inline\' ಮೋಡ್‌ನಲ್ಲಿ ಸ್ವಯಂಚಾಲಿತವಾಗಿ ತೋರಿಸಲಾಗುತ್ತದೆ. ಹುಡುಕಾಟ ಫಾರ್ಮ್ ಖಾಲಿಯಾಗದಂತೆ ನೀವು ಕನಿಷ್ಠ ಒಂದು ಸುಧಾರಿತ ಹುಡುಕಾಟ ಕ್ಷೇತ್ರವನ್ನಾದರೂ ಸಕ್ರಿಯಗೊಳಿಸಬೇಕು.','Choose whether to show a preview of the upcoming events for the date clicked on, or directly link to the calendar day.'=>'ಕ್ಲಿಕ್ ಮಾಡಿದ ದಿನಾಂಕದ ಮುಂಬರುವ ಈವೆಂಟ್‌ಗಳ ಮುನ್ನೋಟವನ್ನು ತೋರಿಸಬೇಕೇ ಅಥವಾ ದಿನಸೂಚಿಯ ದಿನಕ್ಕೆ ನೇರವಾಗಿ ಲಿಂಕ್ ಮಾಡಬೇಕೇ ಎಂದು ಆರಿಸಿ.','Choose which %s account hosts this event.'=>'ಈ ಈವೆಂಟ್ ಅನ್ನು ಯಾವ %s ಖಾತೆ ಆಯೋಜಿಸುತ್ತದೆ ಎಂಬುದನ್ನು ಆಯ್ಕೆಮಾಡಿ.','Choose which order your tickets appear.'=>'ನಿಮ್ಮ ಟಿಕೆಟ್‌ಗಳು ಯಾವ ಕ್ರಮದಲ್ಲಿ ಕಾಣಿಸಬೇಕೆಂದು ಆರಿಸಿ.','Choose your currency for displaying event pricing.'=>'ಈವೆಂಟ್ ಬೆಲೆಗಳನ್ನು ಪ್ರದರ್ಶಿಸಲು ನಿಮ್ಮ ಕರೆನ್ಸಿಯನ್ನು ಆರಿಸಿ.','Choose/Upload Image'=>'ಚಿತ್ರವನ್ನು ಆರಿಸಿ/ಅಪ್‌ಲೋಡ್ ಮಾಡಿ','City'=>'ನಗರ','City/Town'=>'ನಗರ/ಪಟ್ಟಣ','City/Town:'=>'ನಗರ/ಪಟ್ಟಣ:','Classic Editor'=>'ಕ್ಲಾಸಿಕ್ ಸಂಪಾದಕ','Clear All'=>'ಎಲ್ಲವನ್ನೂ ತೆರವುಗೊಳಿಸಿ','Click the button below to mass-convert all your repeating events into recurring events.'=>'ನಿಮ್ಮ ಎಲ್ಲಾ ಪುನರಾವರ್ತಿಸುವ ಈವೆಂಟ್‌ಗಳನ್ನು ಒಮ್ಮೆಗೇ ಪುನರಾವರ್ತಿತ ಈವೆಂಟ್‌ಗಳಾಗಿ ಪರಿವರ್ತಿಸಲು ಕೆಳಗಿನ ಗುಂಡಿಯನ್ನು ಕ್ಲಿಕ್ ಮಾಡಿ.','Click to toggle'=>'ಟಾಗಲ್ ಮಾಡಲು ಕ್ಲಿಕ್ ಮಾಡಿ','Clicking these buttons will not have any effect until you save your settings!'=>'ನೀವು ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಉಳಿಸುವವರೆಗೆ ಈ ಗುಂಡಿಗಳನ್ನು ಕ್ಲಿಕ್ ಮಾಡುವುದರಿಂದ ಯಾವುದೇ ಪರಿಣಾಮ ಆಗುವುದಿಲ್ಲ!','Close Ticket Editor'=>'ಟಿಕೆಟ್ ಸಂಪಾದಕವನ್ನು ಮುಚ್ಚಿ','Collapse All'=>'ಎಲ್ಲವನ್ನೂ ಕಿರಿದುಗೊಳಿಸಿ','Color'=>'ಬಣ್ಣ','Column %d'=>'ಕಾಲಮ್ %d','Column in the file'=>'ಫೈಲ್‌ನಲ್ಲಿರುವ ಕಾಲಮ್','Columns for repeating events'=>'ಪುನರಾವರ್ತಿತ ಈವೆಂಟ್‌ಗಳ ಕಾಲಮ್‌ಗಳು','Columns to choose'=>'ಆಯ್ಕೆ ಮಾಡಬೇಕಾದ ಅಂಕಣಗಳು','Columns to export'=>'ರಫ್ತು ಮಾಡಬೇಕಾದ ಅಂಕಣಗಳು','Columns to show'=>'ತೋರಿಸಬೇಕಾದ ಅಂಕಣಗಳು','Comma-separated address(es) notified of each withdrawal for manual review. Leave blank to use the site admin email.'=>'ಹಸ್ತಚಾಲಿತ ಪರಿಶೀಲನೆಗಾಗಿ ಪ್ರತಿ ಹಿಂಪಡೆಯುವಿಕೆಯ ಬಗ್ಗೆ ಸೂಚಿಸಲಾಗುವ, ಅಲ್ಪವಿರಾಮದಿಂದ ಪ್ರತ್ಯೇಕಿಸಿದ ವಿಳಾಸ(ಗಳು). ತಾಣ ನಿರ್ವಾಹಕರ ಇಮೇಲ್ ಬಳಸಲು ಖಾಲಿ ಬಿಡಿ.','Comma-separated list of allowed file extensions: %s. Leave blank to allow any.'=>'ಅನುಮತಿಸಿದ ಕಡತ ವಿಸ್ತರಣೆಗಳ ಅಲ್ಪವಿರಾಮ-ಬೇರ್ಪಡಿಸಿದ ಪಟ್ಟಿ: %s. ಯಾವುದನ್ನಾದರೂ ಅನುಮತಿಸಲು ಖಾಲಿ ಬಿಡಿ.','Comment'=>'ಪ್ರತಿಕ್ರಿಯೆ','Communications Consent'=>'ಸಂವಹನ ಒಪ್ಪಿಗೆ','Compare With'=>'ಇದರೊಂದಿಗೆ ಹೋಲಿಸಿ','Compare features'=>'ವೈಶಿಷ್ಟ್ಯಗಳನ್ನು ಹೋಲಿಸಿ','Compared to'=>'ಇದರೊಂದಿಗೆ ಹೋಲಿಸಿದರೆ','Configure the base settings for your events. These settings affect how events are stored and accessed in the database.'=>'ನಿಮ್ಮ ಈವೆಂಟ್‌ಗಳ ಮೂಲ ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಸಂರಚಿಸಿ. ಈ ಸೆಟ್ಟಿಂಗ್‌ಗಳು ಈವೆಂಟ್‌ಗಳನ್ನು ಡೇಟಾಬೇಸ್‌ನಲ್ಲಿ ಹೇಗೆ ಸಂಗ್ರಹಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ಪ್ರವೇಶಿಸಲಾಗುತ್ತದೆ ಎಂಬುದರ ಮೇಲೆ ಪರಿಣಾಮ ಬೀರುತ್ತವೆ.','Configure the base settings for your locations. These settings affect how locations are stored and accessed in the database.'=>'ನಿಮ್ಮ ಸ್ಥಳಗಳ ಮೂಲ ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಸಂರಚಿಸಿ. ಈ ಸೆಟ್ಟಿಂಗ್‌ಗಳು ಸ್ಥಳಗಳನ್ನು ಡೇಟಾಬೇಸ್‌ನಲ್ಲಿ ಹೇಗೆ ಸಂಗ್ರಹಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ಪ್ರವೇಶಿಸಲಾಗುತ್ತದೆ ಎಂಬುದರ ಮೇಲೆ ಪರಿಣಾಮ ಬೀರುತ್ತವೆ.','Confirm'=>'ದೃಢೀಕರಿಸಿ','Confirm button'=>'ದೃಢೀಕರಣ ಗುಂಡಿ','Confirmation email could not be sent to admin. Registrant should have gotten their email (only admin see this warning).'=>'ನಿರ್ವಾಹಕರಿಗೆ ದೃಢೀಕರಣ ಇಮೇಲ್ ಕಳುಹಿಸಲಾಗಲಿಲ್ಲ. ನೋಂದಣಿದಾರರಿಗೆ ಅವರ ಇಮೇಲ್ ತಲುಪಿರಬೇಕು (ಈ ಎಚ್ಚರಿಕೆಯನ್ನು ನಿರ್ವಾಹಕರು ಮಾತ್ರ ನೋಡುತ್ತಾರೆ).','Confirmations'=>'ದೃಢೀಕರಣಗಳು','Confirmed'=>'ದೃಢೀಕರಿಸಲಾಗಿದೆ','Confirmed Spaces'=>'ದೃಢೀಕರಿಸಿದ ಸ್ಥಾನಗಳು','Confirmed booking email'=>'ದೃಢೀಕೃತ ಬುಕಿಂಗ್ ಇಮೇಲ್','Congratulations! Your email settings work.'=>'ಅಭಿನಂದನೆಗಳು! ನಿಮ್ಮ ಇಮೇಲ್ ಸೆಟ್ಟಿಂಗ್‌ಗಳು ಕೆಲಸ ಮಾಡುತ್ತಿವೆ.','Connect'=>'ಕನೆಕ್ಟ್','Connect Events Manager to MCP-compatible AI clients (Claude, Cursor, ChatGPT custom connectors, VS Code, Codex) by exposing Events Manager Abilities through the WordPress MCP Adapter. Clients authenticate through a one-click consent screen and a refreshable Application Password — no manual key juggling.'=>'WordPress MCP Adapter ಮೂಲಕ Events Manager ಸಾಮರ್ಥ್ಯಗಳನ್ನು ಒದಗಿಸುವ ಮೂಲಕ Events Manager ಅನ್ನು MCP-ಹೊಂದಾಣಿಕೆಯ AI ಕ್ಲೈಂಟ್‌ಗಳಿಗೆ (Claude, Cursor, ChatGPT ಕಸ್ಟಮ್ ಕನೆಕ್ಟರ್‌ಗಳು, VS Code, Codex) ಸಂಪರ್ಕಿಸಿ. ಕ್ಲೈಂಟ್‌ಗಳು ಒಂದು-ಕ್ಲಿಕ್ ಒಪ್ಪಿಗೆ ಪರದೆ ಮತ್ತು ರಿಫ್ರೆಶ್ ಮಾಡಬಹುದಾದ ಅಪ್ಲಿಕೇಶನ್ ಪಾಸ್‌ವರ್ಡ್ ಮೂಲಕ ದೃಢೀಕರಿಸುತ್ತವೆ, ಕೀಗಳನ್ನು ಕೈಯಾರೆ ನಿರ್ವಹಿಸುವ ಅಗತ್ಯವಿಲ್ಲ.','Connect a %s account in the Events Manager settings before using it as an event location.'=>'ಈವೆಂಟ್ ಸ್ಥಳವಾಗಿ ಬಳಸುವ ಮೊದಲು Events Manager ಸೆಟ್ಟಿಂಗ್‌ಗಳಲ್ಲಿ %s ಖಾತೆಯನ್ನು ಕನೆಕ್ಟ್ ಮಾಡಿ.','Connect an account'=>'ಖಾತೆಯನ್ನು ಕನೆಕ್ಟ್ ಮಾಡಿ','Connect to import events and locations from %s.'=>'%s ನಿಂದ ಈವೆಂಟ್‌ಗಳು ಮತ್ತು ಸ್ಥಳಗಳನ್ನು ಆಮದು ಮಾಡಲು ಸಂಪರ್ಕಿಸಿ.','Consent'=>'ಒಪ್ಪಿಗೆ','Consent %s on %s'=>'%s ರಂದು %s ಒಪ್ಪಿಗೆ','Consent Error'=>'ಒಪ್ಪಿಗೆ ದೋಷ','Consent Text'=>'ಒಪ್ಪಿಗೆ ಪಠ್ಯ','Consent previously %s on %s'=>'ಒಪ್ಪಿಗೆಯನ್ನು ಹಿಂದೆ %s ರಂದು %s','Consented By Default'=>'ಡೀಫಾಲ್ಟ್ ಆಗಿ ಒಪ್ಪಿಗೆ ನೀಡಲಾಗಿದೆ','Contact a site administrator for your password.'=>'ನಿಮ್ಮ ಗುಪ್ತಪದಕ್ಕಾಗಿ ಜಾಲತಾಣ ನಿರ್ವಾಹಕರನ್ನು ಸಂಪರ್ಕಿಸಿ.','Content supplied within shortcode tags and the %s parameters will be HTML entity-decoded and sanitized.'=>'ಶಾರ್ಟ್‌ಕೋಡ್ ಟ್ಯಾಗ್‌ಗಳೊಳಗೆ ನೀಡಿದ ವಿಷಯ ಮತ್ತು %s ಪ್ಯಾರಾಮೀಟರ್‌ಗಳನ್ನು HTML ಎಂಟಿಟಿ-ಡಿಕೋಡ್ ಮಾಡಿ ಸ್ಯಾನಿಟೈಸ್ ಮಾಡಲಾಗುತ್ತದೆ.','Content supplied within shortcode tags like %s will be HTML entity-decoded.'=>'%s ನಂತಹ ಶಾರ್ಟ್‌ಕೋಡ್ ಟ್ಯಾಗ್‌ಗಳೊಳಗೆ ನೀಡಿದ ವಿಷಯವನ್ನು HTML ಎಂಟಿಟಿ-ಡಿಕೋಡ್ ಮಾಡಲಾಗುತ್ತದೆ.','Control how subsites use Archetypes. Define network-wide types here and decide whether subsites can create, choose, or must use your list. You can also allow/deny renaming specific base settings.'=>'ಸಬ್‌ಸೈಟ್‌ಗಳು ಆರ್ಕಿಟೈಪ್‌ಗಳನ್ನು ಹೇಗೆ ಬಳಸುತ್ತವೆ ಎಂಬುದನ್ನು ನಿಯಂತ್ರಿಸಿ. ನೆಟ್‌ವರ್ಕ್-ವ್ಯಾಪಿ ಬಗೆಗಳನ್ನು ಇಲ್ಲಿ ವ್ಯಾಖ್ಯಾನಿಸಿ ಮತ್ತು ಸಬ್‌ಸೈಟ್‌ಗಳು ರಚಿಸಬಹುದೇ, ಆರಿಸಬಹುದೇ, ಅಥವಾ ನಿಮ್ಮ ಪಟ್ಟಿಯನ್ನೇ ಬಳಸಬೇಕೇ ಎಂದು ನಿರ್ಧರಿಸಿ. ನಿರ್ದಿಷ್ಟ ಮೂಲ ಸೆಟ್ಟಿಂಗ್‌ಗಳ ಹೆಸರು ಬದಲಿಸಲು ಅನುಮತಿಸುವುದನ್ನು/ನಿರಾಕರಿಸುವುದನ್ನೂ ಮಾಡಬಹುದು.','Controls how many events being held at a location are shown per page when using placeholders such as %s. Leave blank for no limit.'=>'%s ನಂತಹ ಪ್ಲೇಸ್‌ಹೋಲ್ಡರ್‌ಗಳನ್ನು ಬಳಸುವಾಗ ಒಂದು ಸ್ಥಳದಲ್ಲಿ ನಡೆಯುವ ಎಷ್ಟು ಈವೆಂಟ್‌ಗಳನ್ನು ಪ್ರತಿ ಪುಟದಲ್ಲಿ ತೋರಿಸಬೇಕೆಂದು ನಿಯಂತ್ರಿಸುತ್ತದೆ. ಮಿತಿ ಬೇಡವಾದರೆ ಖಾಲಿ ಬಿಡಿ.','Controls how many events belonging to a category are shown per page when using placeholders such as %s. Leave blank for no limit.'=>'%s ನಂತಹ ಪ್ಲೇಸ್‌ಹೋಲ್ಡರ್‌ಗಳನ್ನು ಬಳಸುವಾಗ ಒಂದು ವರ್ಗಕ್ಕೆ ಸೇರಿದ ಎಷ್ಟು ಈವೆಂಟ್‌ಗಳನ್ನು ಪ್ರತಿ ಪುಟದಲ್ಲಿ ತೋರಿಸಬೇಕೆಂದು ನಿಯಂತ್ರಿಸುತ್ತದೆ. ಮಿತಿ ಬೇಡವಾದರೆ ಖಾಲಿ ಬಿಡಿ.','Controls how many events belonging to a tag are shown per page when using placeholders such as %s. Leave blank for no limit.'=>'%s ನಂತಹ ಪ್ಲೇಸ್‌ಹೋಲ್ಡರ್‌ಗಳನ್ನು ಬಳಸುವಾಗ ಒಂದು ಟ್ಯಾಗ್‌ಗೆ ಸೇರಿದ ಎಷ್ಟು ಈವೆಂಟ್‌ಗಳನ್ನು ಪ್ರತಿ ಪುಟದಲ್ಲಿ ತೋರಿಸಬೇಕೆಂದು ನಿಯಂತ್ರಿಸುತ್ತದೆ. ಮಿತಿ ಬೇಡವಾದರೆ ಖಾಲಿ ಬಿಡಿ.','Convert ALL Repeating Events'=>'ಎಲ್ಲಾ ಪುನರಾವರ್ತಿಸುವ ಈವೆಂಟ್‌ಗಳನ್ನು ಪರಿವರ್ತಿಸಿ','Convert Recurring'=>'ಪುನರಾವರ್ತಿತವನ್ನಾಗಿ ಪರಿವರ್ತಿಸಿ','Convert and Deactivate Repeating Events'=>'ಪುನರಾವರ್ತಿತ ಈವೆಂಟ್‌ಗಳನ್ನು ಪರಿವರ್ತಿಸಿ ಮತ್ತು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಿ','Coordinates'=>'ನಿರ್ದೇಶಾಂಕಗಳು','Copies your events, venues, organizers, tickets and attendees from %s into Events Manager. Nothing in the original plugin is changed or deleted, so you can run this, check the result, and roll it back or run it again.'=>'ನಿಮ್ಮ ಈವೆಂಟ್‌ಗಳು, ಸ್ಥಳಗಳು, ಆಯೋಜಕರು, ಟಿಕೆಟ್‌ಗಳು ಮತ್ತು ಹಾಜರಾತಿದಾರರನ್ನು %s ನಿಂದ Events Manager ಗೆ ನಕಲಿಸುತ್ತದೆ. ಮೂಲ ಪ್ಲಗಿನ್‌ನಲ್ಲಿ ಯಾವುದನ್ನೂ ಬದಲಾಯಿಸಲಾಗುವುದಿಲ್ಲ ಅಥವಾ ಅಳಿಸಲಾಗುವುದಿಲ್ಲ, ಆದ್ದರಿಂದ ನೀವು ಇದನ್ನು ಚಲಾಯಿಸಿ, ಫಲಿತಾಂಶವನ್ನು ಪರಿಶೀಲಿಸಿ, ಹಿಂದಕ್ಕೆ ಸರಿಸಬಹುದು ಅಥವಾ ಮತ್ತೆ ಚಲಾಯಿಸಬಹುದು.','Copy default value'=>'ಡೀಫಾಲ್ಟ್ ಮೌಲ್ಯವನ್ನು ನಕಲಿಸಿ','Copy over our new v6 formats to make the best of our new UI design!'=>'ನಮ್ಮ ಹೊಸ UI ವಿನ್ಯಾಸದ ಪೂರ್ಣ ಲಾಭ ಪಡೆಯಲು ನಮ್ಮ ಹೊಸ v6 ಫಾರ್ಮ್ಯಾಟ್‌ಗಳನ್ನು ನಕಲಿಸಿ!','Cost'=>'ವೆಚ್ಚ','Could not check event validation. Saving without pre-check — please verify the event details.'=>'ಈವೆಂಟ್ ಮಾನ್ಯತೆಯನ್ನು ಪರಿಶೀಲಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ. ಪೂರ್ವ ಪರಿಶೀಲನೆ ಇಲ್ಲದೆ ಉಳಿಸಲಾಗುತ್ತಿದೆ, ದಯವಿಟ್ಟು ಈವೆಂಟ್ ವಿವರಗಳನ್ನು ಪರಿಶೀಲಿಸಿ.','Could not open the PDF file for inspection.'=>'ಪರಿಶೀಲನೆಗಾಗಿ ಪಿಡಿಎಫ್ ಫೈಲ್ ಅನ್ನು ತೆರೆಯಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ.','Could not open the file for inspection.'=>'ಪರಿಶೀಲನೆಗಾಗಿ ಫೈಲ್ ಅನ್ನು ತೆರೆಯಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ.','Could not read image size information.'=>'ಚಿತ್ರದ ಗಾತ್ರದ ಮಾಹಿತಿಯನ್ನು ಓದಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ.','Count'=>'ಎಣಿಕೆ','Country'=>'ರಾಷ್ಟ್ರ','Coupons and discount codes'=>'ಕೂಪನ್‌ಗಳು ಮತ್ತು ರಿಯಾಯಿತಿ ಕೋಡ್‌ಗಳು','Create %s'=>'%s ರಚಿಸಿ','Create Zoom meetings and webinars from the event editor, and register attendees on Zoom when they book. With Pro, attendees are registered once they pay and receive their own join links.'=>'ಈವೆಂಟ್ ಸಂಪಾದಕದಿಂದ Zoom ಮೀಟಿಂಗ್‌ಗಳು ಮತ್ತು ವೆಬಿನಾರ್‌ಗಳನ್ನು ರಚಿಸಿ, ಮತ್ತು ಹಾಜರಾತಿದಾರರು ಬುಕ್ ಮಾಡಿದಾಗ Zoom ನಲ್ಲಿ ಅವರನ್ನು ನೋಂದಾಯಿಸಿ. Pro ನೊಂದಿಗೆ, ಹಾಜರಾತಿದಾರರು ಪಾವತಿಸಿದ ನಂತರ ನೋಂದಾಯಿಸಲ್ಪಡುತ್ತಾರೆ ಮತ್ತು ತಮ್ಮದೇ ಸೇರುವ ಲಿಂಕ್‌ಗಳನ್ನು ಪಡೆಯುತ್ತಾರೆ.','Create a location or start typing to search a previously created location.'=>'ಸ್ಥಳವನ್ನು ರಚಿಸಿ ಅಥವಾ ಈ ಮೊದಲು ರಚಿಸಿದ ಸ್ಥಳವನ್ನು ಹುಡುಕಲು ಟೈಪ್ ಮಾಡಲು ಪ್ರಾರಂಭಿಸಿ.','Create booking'=>'ಬುಕಿಂಗ್ ರಚಿಸಿ','Create event'=>'ಈವೆಂಟ್ ರಚಿಸಿ','Create event ticket'=>'ಈವೆಂಟ್ ಟಿಕೆಟ್ ರಚಿಸಿ','Create location'=>'ಸ್ಥಳ ರಚಿಸಿ','Creates a ticket for an Events Manager event.'=>'ಒಂದು Events Manager ಈವೆಂಟ್‌ಗೆ ಟಿಕೆಟ್ ಅನ್ನು ರಚಿಸುತ್ತದೆ.','Creates an Events Manager %s.'=>'ಒಂದು Events Manager %s ಅನ್ನು ರಚಿಸುತ್ತದೆ.','Creates an Events Manager booking. Call get-booking-requirements first to get this event\'s required fields, payload locations, and an example payload.'=>'ಒಂದು Events Manager ಬುಕಿಂಗ್ ಅನ್ನು ರಚಿಸುತ್ತದೆ. ಈ ಈವೆಂಟ್‌ಗೆ ಬೇಕಾದ ಕ್ಷೇತ್ರಗಳು, ಪೇಲೋಡ್ ಸ್ಥಳಗಳು ಮತ್ತು ಉದಾಹರಣೆ ಪೇಲೋಡ್ ಪಡೆಯಲು ಮೊದಲು get-booking-requirements ಅನ್ನು ಕರೆ ಮಾಡಿ.','Creates an Events Manager event.'=>'ಒಂದು Events Manager ಈವೆಂಟ್ ಅನ್ನು ರಚಿಸುತ್ತದೆ.','Creates an Events Manager location.'=>'ಒಂದು Events Manager ಸ್ಥಳವನ್ನು ರಚಿಸುತ್ತದೆ.','Currency'=>'ಕರೆನ್ಸಿ','Currency Format'=>'ಕರೆನ್ಸಿ ನಮೂನೆ','Currency code'=>'ಕರೆನ್ಸಿ ಕೋಡ್','Currency position (prefix or suffix)'=>'ಕರೆನ್ಸಿ ಸ್ಥಾನ (prefix ಅಥವಾ suffix)','Currency symbol'=>'ಕರೆನ್ಸಿ ಚಿಹ್ನೆ','Currently overridden by the EM_GUTENBERG constant in wp-config.php (%s).'=>'ಪ್ರಸ್ತುತ wp-config.php ನಲ್ಲಿರುವ EM_GUTENBERG ಸ್ಥಿರಾಂಕದಿಂದ ಅತಿಕ್ರಮಿಸಲಾಗಿದೆ (%s).','Custom Dates'=>'ಕಸ್ಟಮ್ ದಿನಾಂಕಗಳು','Custom Link'=>'ಕಸ್ಟಮ್ ಲಿಂಕ್','Custom Links'=>'ಕಸ್ಟಮ್ ಲಿಂಕ್‌ಗಳು','Custom booking forms and individual attendee forms'=>'ಕಸ್ಟಮ್ ಬುಕಿಂಗ್ ಫಾರ್ಮ್‌ಗಳು ಮತ್ತು ಪ್ರತ್ಯೇಕ ಹಾಜರಾತಿದಾರರ ಫಾರ್ಮ್‌ಗಳು','Custom fields are the same as attributes, except you cannot restrict specific values, users can add any kind of custom field name/value pair. Only available in the WordPress admin area.'=>'ಕಸ್ಟಮ್ ಕ್ಷೇತ್ರಗಳು ಗುಣಲಕ್ಷಣಗಳಂತೆಯೇ ಇವೆ, ಆದರೆ ನಿರ್ದಿಷ್ಟ ಮೌಲ್ಯಗಳನ್ನು ನಿರ್ಬಂಧಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ, ಬಳಕೆದಾರರು ಯಾವುದೇ ರೀತಿಯ ಕಸ್ಟಮ್ ಕ್ಷೇತ್ರದ ಹೆಸರು/ಮೌಲ್ಯ ಜೋಡಿಯನ್ನು ಸೇರಿಸಬಹುದು. WordPress ನಿರ್ವಾಹಕ ಪ್ರದೇಶದಲ್ಲಿ ಮಾತ್ರ ಲಭ್ಯ.','Customize Feedback Messages'=>'ಅನಿಸಿಕೆ ಸಂದೇಶಗಳನ್ನು ಅಗತ್ಯಾನುಗುಣಗೊಳಿಸಿ','Customize the format of the selected search dates, we recommend a brief format to keep things short.'=>'ಆಯ್ದ ಹುಡುಕಾಟ ದಿನಾಂಕಗಳ ನಮೂನೆಯನ್ನು ಅಗತ್ಯಾನುಗುಣಗೊಳಿಸಿ; ಚಿಕ್ಕದಾಗಿಡಲು ಸಂಕ್ಷಿಪ್ತ ನಮೂನೆಯನ್ನು ನಾವು ಶಿಫಾರಸು ಮಾಡುತ್ತೇವೆ.','Customize the message your user sees when they resubmit/update their event.'=>'ಬಳಕೆದಾರರು ತಮ್ಮ ಈವೆಂಟ್ ಅನ್ನು ಮರುಸಲ್ಲಿಸಿದಾಗ/ನವೀಕರಿಸಿದಾಗ ಅವರಿಗೆ ಕಾಣಿಸುವ ಸಂದೇಶವನ್ನು ಅಗತ್ಯಾನುಗುಣಗೊಳಿಸಿ.','Customize the message your user sees when they submitted their event.'=>'ಬಳಕೆದಾರರು ತಮ್ಮ ಈವೆಂಟ್ ಅನ್ನು ಸಲ್ಲಿಸಿದಾಗ ಅವರಿಗೆ ಕಾಣಿಸುವ ಸಂದೇಶವನ್ನು ಅಗತ್ಯಾನುಗುಣಗೊಳಿಸಿ.','Customizer'=>'ಅಗತ್ಯಾನುಗುಣಗೊಳಿಸುಗ','Daily'=>'ದೈನಂದಿನ','Database Cleanup'=>'ಡೇಟಾಬೇಸ್ ಸ್ವಚ್ಛಗೊಳಿಸುವಿಕೆ','Date'=>'ದಿನಾಂಕ','Date Format'=>'ದಿನಾಂಕದ ನಮೂನೆ','Date Picker Format'=>'ದಿನಾಂಕ ಆಯ್ಕೆಗಾರದ ನಮೂನೆ','Date Preview Mode'=>'ದಿನಾಂಕ ಮುನ್ನೋಟ ಮೋಡ್','Date Separator'=>'ದಿನಾಂಕ ವಿಭಜಕ','Date and Time'=>'ದಿನಾಂಕ ಮತ್ತು ಸಮಯ','Date and Time formats follow the <a href="%s">WordPress time formatting conventions</a>'=>'ದಿನಾಂಕ ಮತ್ತು ಸಮಯದ ನಮೂನೆಗಳು <a href="%s">WordPress ಸಮಯ ಫಾರ್ಮ್ಯಾಟಿಂಗ್ ಸಂಪ್ರದಾಯಗಳನ್ನು</a> ಅನುಸರಿಸುತ್ತವೆ','Date and time'=>'ದಿನಾಂಕ ಮತ್ತು ಸಮಯ','Date/Time'=>'ದಿನಾಂಕ/ಸಮಯ','Dates'=>'ದಿನಾಂಕಗಳು','Dates must have correct formatting. Please use the date picker provided.'=>'ದಿನಾಂಕಗಳು ಸರಿಯಾದ ನಮೂನೆಯಲ್ಲಿರಬೇಕು. ದಯವಿಟ್ಟು ಒದಗಿಸಿದ ದಿನಾಂಕ ಆಯ್ಕೆಕಾರಕವನ್ನು ಬಳಸಿ.','Dates such as 2027-03-04 or March 4, 2027 are always read the same way.'=>'2027-03-04 ಅಥವಾ March 4, 2027 ನಂತಹ ದಿನಾಂಕಗಳನ್ನು ಯಾವಾಗಲೂ ಒಂದೇ ರೀತಿಯಲ್ಲಿ ಓದಲಾಗುತ್ತದೆ.','Dates written as numbers'=>'ಸಂಖ್ಯೆಗಳಾಗಿ ಬರೆದ ದಿನಾಂಕಗಳು','Day %d'=>'ದಿನ %d','Day first: 03/04/2027 is April 3'=>'ದಿನ ಮೊದಲು: 03/04/2027 ಎಂದರೆ April 3','Days of week'=>'ವಾರದ ದಿನಗಳು','Dear #_BOOKINGNAME, <br/>You have requested #_BOOKINGSPACES space/spaces for #_EVENTNAME.<br/>When : #_EVENTDATES @ #_EVENTTIMES<br/>Where : #_LOCATIONNAME - #_LOCATIONFULLLINE<br/>Your booking is currently pending approval by our administrators. Once approved you will receive an automatic confirmation.<br/>Yours faithfully,<br/>#_CONTACTNAME'=>'ಪ್ರಿಯ #_BOOKINGNAME, <br/>ನೀವು #_EVENTNAME ಗಾಗಿ #_BOOKINGSPACES ಸ್ಥಾನ/ಸ್ಥಾನಗಳನ್ನು ವಿನಂತಿಸಿದ್ದೀರಿ.<br/>ಯಾವಾಗ : #_EVENTDATES @ #_EVENTTIMES<br/>ಎಲ್ಲಿ : #_LOCATIONNAME - #_LOCATIONFULLLINE<br/>ನಿಮ್ಮ ಬುಕಿಂಗ್ ಪ್ರಸ್ತುತ ನಮ್ಮ ನಿರ್ವಾಹಕರ ಅನುಮೋದನೆಗಾಗಿ ಬಾಕಿಯಿದೆ. ಅನುಮೋದನೆಯಾದ ನಂತರ ನಿಮಗೆ ಸ್ವಯಂಚಾಲಿತ ದೃಢೀಕರಣ ಬರುತ್ತದೆ.<br/>ತಮ್ಮ ವಿಶ್ವಾಸಿ,<br/>#_CONTACTNAME','Dear #_BOOKINGNAME, <br/>You have successfully reserved #_BOOKINGSPACES space/spaces for #_EVENTNAME.<br/>When : #_EVENTDATES @ #_EVENTTIMES<br/>Where : #_LOCATIONNAME - #_LOCATIONFULLLINE<br/>Yours faithfully,<br/>#_CONTACTNAME'=>'ಪ್ರಿಯ #_BOOKINGNAME, <br/>ನೀವು #_EVENTNAME ಗಾಗಿ #_BOOKINGSPACES ಸ್ಥಾನ/ಸ್ಥಾನಗಳನ್ನು ಯಶಸ್ವಿಯಾಗಿ ಕಾಯ್ದಿರಿಸಿದ್ದೀರಿ.<br/>ಯಾವಾಗ : #_EVENTDATES @ #_EVENTTIMES<br/>ಎಲ್ಲಿ : #_LOCATIONNAME - #_LOCATIONFULLLINE<br/>ತಮ್ಮ ವಿಶ್ವಾಸಿ,<br/>#_CONTACTNAME','Dear #_BOOKINGNAME, <br/>Your requested booking for #_BOOKINGSPACES spaces at #_EVENTNAME on #_EVENTDATES has been cancelled.<br/>Yours faithfully,<br/>#_CONTACTNAME'=>'ಪ್ರಿಯ #_BOOKINGNAME, <br/>#_EVENTDATES ರಂದು #_EVENTNAME ನಲ್ಲಿ #_BOOKINGSPACES ಸ್ಥಾನಗಳಿಗಾಗಿ ನೀವು ವಿನಂತಿಸಿದ ಬುಕಿಂಗ್ ಅನ್ನು ರದ್ದುಗೊಳಿಸಲಾಗಿದೆ.<br/>ತಮ್ಮ ವಿಶ್ವಾಸಿ,<br/>#_CONTACTNAME','Dear #_BOOKINGNAME, <br/>Your requested booking for #_BOOKINGSPACES spaces at #_EVENTNAME on #_EVENTDATES has been rejected.<br/>Yours faithfully,<br/>#_CONTACTNAME'=>'ಪ್ರಿಯ #_BOOKINGNAME, <br/>#_EVENTDATES ರಂದು #_EVENTNAME ನಲ್ಲಿ #_BOOKINGSPACES ಸ್ಥಾನಗಳಿಗಾಗಿ ನೀವು ವಿನಂತಿಸಿದ ಬುಕಿಂಗ್ ಅನ್ನು ತಿರಸ್ಕರಿಸಲಾಗಿದೆ.<br/>ತಮ್ಮ ವಿಶ್ವಾಸಿ,<br/>#_CONTACTNAME','Dear %s'=>'ಪ್ರಿಯ %s','Dear Guest, <br/>We regret to inform you that #_EVENTNAME on #_EVENTDATES has been cancelled.<br/>Yours faithfully,<br/>#_CONTACTNAME'=>'ಪ್ರಿಯ ಅತಿಥಿ, <br/>#_EVENTDATES ರಂದು ನಡೆಯಬೇಕಿದ್ದ #_EVENTNAME ಅನ್ನು ರದ್ದುಗೊಳಿಸಲಾಗಿದೆ ಎಂದು ವಿಷಾದದಿಂದ ತಿಳಿಸುತ್ತೇವೆ.<br/>ತಮ್ಮ ವಿಶ್ವಾಸಿ,<br/>#_CONTACTNAME','Decimal Point'=>'ದಶಮಾಂಶ ಬಿಂದು','Decode shortcode content?'=>'ಶಾರ್ಟ್‌ಕೋಡ್ ವಿಷಯವನ್ನು ಡಿಕೋಡ್ ಮಾಡಬೇಕೇ?','Decode shortcode format parameters?'=>'ಶಾರ್ಟ್‌ಕೋಡ್ ಫಾರ್ಮ್ಯಾಟ್ ಪ್ಯಾರಾಮೀಟರ್‌ಗಳನ್ನು ಡಿಕೋಡ್ ಮಾಡಬೇಕೇ?','Default'=>'ಡೀಫಾಲ್ಟ್','Default %s color'=>'ಡೀಫಾಲ್ಟ್ %s ಬಣ್ಣ','Default %s list format'=>'ಡೀಫಾಲ್ಟ್ %s ಪಟ್ಟಿ ನಮೂನೆ','Default %s list options'=>'ಡೀಫಾಲ್ಟ್ %s ಪಟ್ಟಿ ಆಯ್ಕೆಗಳು','Default (site setting)'=>'ಡೀಫಾಲ್ಟ್ (ತಾಣ ಸೆಟ್ಟಿಂಗ್)','Default Category'=>'ಡೀಫಾಲ್ಟ್ ವರ್ಗ','Default Country'=>'ಡೀಫಾಲ್ಟ್ ರಾಷ್ಟ್ರ','Default List Scope'=>'ಡೀಫಾಲ್ಟ್ ಪಟ್ಟಿ ವ್ಯಾಪ್ತಿ','Default Location'=>'ಡೀಫಾಲ್ಟ್ ಸ್ಥಳ','Default Location Country'=>'ಡೀಫಾಲ್ಟ್ ಸ್ಥಳದ ರಾಷ್ಟ್ರ','Default Timezone'=>'ಡೀಫಾಲ್ಟ್ ಸಮಯವಲಯ','Default View'=>'ಡೀಫಾಲ್ಟ್ ನೋಟ','Default archive ordering'=>'ಡೀಫಾಲ್ಟ್ ಆರ್ಕೈವ್ ಜೋಡಣೆ','Default calendar size'=>'ಡೀಫಾಲ್ಟ್ ದಿನಸೂಚಿ ಗಾತ್ರ','Default distance'=>'ಡೀಫಾಲ್ಟ್ ದೂರ','Default distance unit'=>'ಡೀಫಾಲ್ಟ್ ದೂರದ ಏಕಮಾನ','Default event archive ordering'=>'ಡೀಫಾಲ್ಟ್ ಈವೆಂಟ್ ಆರ್ಕೈವ್ ಜೋಡಣೆ','Default event list format'=>'ಡೀಫಾಲ್ಟ್ ಈವೆಂಟ್ ಪಟ್ಟಿ ಸ್ವರೂಪ','Default event list format footer'=>'ಡೀಫಾಲ್ಟ್ ಈವೆಂಟ್ ಪಟ್ಟಿ ಸ್ವರೂಪದ ಅಡಿಟಿಪ್ಪಣಿ','Default event list format header'=>'ಡೀಫಾಲ್ಟ್ ಈವೆಂಟ್ ಪಟ್ಟಿ ಸ್ವರೂಪದ ಶೀರ್ಷಿಕೆ','Default event list ordering'=>'ಡೀಫಾಲ್ಟ್ ಈವೆಂಟ್ ಪಟ್ಟಿ ಕ್ರಮ','Default event style'=>'ಡೀಫಾಲ್ಟ್ ಈವೆಂಟ್ ಶೈಲಿ','Default font family'=>'ಡೀಫಾಲ್ಟ್ ಫಾಂಟ್ ಕುಟುಂಬ','Default list ordering'=>'ಡೀಫಾಲ್ಟ್ ಪಟ್ಟಿ ಜೋಡಣೆ','Default map height'=>'ಡೀಫಾಲ್ಟ್ ನಕ್ಷೆಯ ಎತ್ತರ','Default map width'=>'ಡೀಫಾಲ್ಟ್ ನಕ್ಷೆಯ ಅಗಲ','Default plugin setting'=>'ಪ್ಲಗಿನ್‌ನ ಡೀಫಾಲ್ಟ್ ಸೆಟ್ಟಿಂಗ್','Default scope to show your events in shortcodes, widgets and any other displays where scope is not defined. Events page and archive scopes can be defined in the %s settings section.'=>'ಶಾರ್ಟ್‌ಕೋಡ್‌ಗಳು, ವಿಜೆಟ್‌ಗಳು ಮತ್ತು ವ್ಯಾಪ್ತಿಯನ್ನು ಸೂಚಿಸದ ಇತರ ಪ್ರದರ್ಶನಗಳಲ್ಲಿ ನಿಮ್ಮ ಈವೆಂಟ್‌ಗಳನ್ನು ತೋರಿಸಲು ಡೀಫಾಲ್ಟ್ ವ್ಯಾಪ್ತಿ. ಈವೆಂಟ್‌ಗಳ ಪುಟ ಮತ್ತು ಆರ್ಕೈವ್ ವ್ಯಾಪ್ತಿಗಳನ್ನು %s ಸೆಟ್ಟಿಂಗ್‌ಗಳ ವಿಭಾಗದಲ್ಲಿ ನಿರ್ದಿಷ್ಟಪಡಿಸಬಹುದು.','Default: %s'=>'ಡೀಫಾಲ್ಟ್: %s','Delete'=>'ಅಳಿಸು','Delete %s'=>'%s ಅಳಿಸಿ','Delete User'=>'ಬಳಕೆದಾರರನ್ನು ಅಳಿಸಿ','Delete booking'=>'ಬುಕಿಂಗ್ ಅಳಿಸಿ','Delete event'=>'ಈವೆಂಟ್ ಅಳಿಸಿ','Delete everything migrated from %s (events, locations, tickets, bookings, terms) and restore converted content? The original data is not affected.'=>'%s ನಿಂದ ವರ್ಗಾಯಿಸಿದ ಎಲ್ಲವನ್ನೂ (ಈವೆಂಟ್‌ಗಳು, ಸ್ಥಳಗಳು, ಟಿಕೆಟ್‌ಗಳು, ಬುಕಿಂಗ್‌ಗಳು, ಟರ್ಮ್‌ಗಳು) ಅಳಿಸಿ ಪರಿವರ್ತಿಸಿದ ವಿಷಯವನ್ನು ಮರುಸ್ಥಾಪಿಸುವುದೇ? ಮೂಲ ಡೇಟಾಗೆ ಪರಿಣಾಮವಾಗುವುದಿಲ್ಲ.','Delete everything the import of %s created (events, locations, organizers, categories, tags and downloaded images)? Items that were already on the site are not affected.'=>'%s ಆಮದು ರಚಿಸಿದ ಎಲ್ಲವನ್ನೂ (ಈವೆಂಟ್‌ಗಳು, ಸ್ಥಳಗಳು, ಆಯೋಜಕರು, ವರ್ಗಗಳು, ಟ್ಯಾಗ್‌ಗಳು ಮತ್ತು ಡೌನ್‌ಲೋಡ್ ಮಾಡಿದ ಚಿತ್ರಗಳು) ಅಳಿಸಬೇಕೇ? ಈಗಾಗಲೇ ಸೈಟ್‌ನಲ್ಲಿದ್ದ ಐಟಂಗಳ ಮೇಲೆ ಪರಿಣಾಮ ಬೀರುವುದಿಲ್ಲ.','Delete location'=>'ಸ್ಥಳ ಅಳಿಸಿ','Delete selected'=>'ಆಯ್ಕೆಮಾಡಿದ್ದನ್ನು ಅಳಿಸಿ','Delete ticket'=>'ಟಿಕೆಟ್ ಅಳಿಸಿ','Deleted'=>'ಅಳಿಸಲಾಗಿದೆ','Deletes an Events Manager %s.'=>'ಒಂದು Events Manager %s ಅನ್ನು ಅಳಿಸುತ್ತದೆ.','Deletes an Events Manager ticket if it has no bookings.'=>'ಒಂದು Events Manager ಟಿಕೆಟ್‌ಗೆ ಬುಕಿಂಗ್‌ಗಳಿಲ್ಲದಿದ್ದರೆ ಅದನ್ನು ಅಳಿಸುತ್ತದೆ.','Deletes or trashes an Events Manager event.'=>'ಒಂದು Events Manager ಈವೆಂಟ್ ಅನ್ನು ಅಳಿಸುತ್ತದೆ ಅಥವಾ ಕಸದಬುಟ್ಟಿಗೆ ಹಾಕುತ್ತದೆ.','Deletes or trashes an Events Manager location.'=>'ಒಂದು Events Manager ಸ್ಥಳವನ್ನು ಅಳಿಸುತ್ತದೆ ಅಥವಾ ಕಸದಬುಟ್ಟಿಗೆ ಹಾಕುತ್ತದೆ.','Depending on server settings, some sending methods may ignore this settings.'=>'ಸರ್ವರ್ ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಅವಲಂಬಿಸಿ, ಕೆಲವು ಕಳುಹಿಸುವ ವಿಧಾನಗಳು ಈ ಸೆಟ್ಟಿಂಗ್ ಅನ್ನು ನಿರ್ಲಕ್ಷಿಸಬಹುದು.','Depending on the nature of your site, you will be subject to one or more national and international privacy/data protection laws such as the %s. Below are some options that you can use to tailor how Events Manager interacts with WordPress privacy tools.'=>'ನಿಮ್ಮ ಸೈಟ್‌ನ ಸ್ವರೂಪವನ್ನು ಅವಲಂಬಿಸಿ, %s ನಂತಹ ಒಂದು ಅಥವಾ ಹೆಚ್ಚು ರಾಷ್ಟ್ರೀಯ ಮತ್ತು ಅಂತರರಾಷ್ಟ್ರೀಯ ಗೌಪ್ಯತೆ/ಡೇಟಾ ಸಂರಕ್ಷಣಾ ಕಾನೂನುಗಳು ನಿಮಗೆ ಅನ್ವಯಿಸುತ್ತವೆ. Events Manager WordPress ಗೌಪ್ಯತಾ ಉಪಕರಣಗಳೊಂದಿಗೆ ಹೇಗೆ ಸಂವಹನ ನಡೆಸುತ್ತದೆ ಎಂಬುದನ್ನು ಹೊಂದಿಸಲು ನೀವು ಬಳಸಬಹುದಾದ ಕೆಲವು ಆಯ್ಕೆಗಳು ಕೆಳಗಿವೆ.','Descending'=>'ಅವರೋಹಣ','Description'=>'ವಿವರಣೆ','Detach'=>'ಬೇರ್ಪಡಿಸು','Details'=>'ವಿವರಗಳು','Details about the event.'=>'ಈವೆಂಟ್ ಬಗ್ಗೆ ವಿವರಗಳು.','Details about the location.'=>'ಸ್ಥಳದ ಬಗ್ಗೆ ವಿವರಗಳು.','Detect User Country'=>'ಬಳಕೆದಾರರ ರಾಷ್ಟ್ರವನ್ನು ಪತ್ತೆಹಚ್ಚಿ','Dev Mode active: Just a friendly reminder that you are updating to development versions. Only admins see this message, and it will go away when you disable this <a href="#pro-api">here</a> in your settings.'=>'ಡೆವ್ ಮೋಡ್ ಸಕ್ರಿಯವಾಗಿದೆ: ನೀವು ಅಭಿವೃದ್ಧಿ ಆವೃತ್ತಿಗಳಿಗೆ ಉನ್ನತೀಕರಿಸುತ್ತಿದ್ದೀರಿ ಎಂಬ ಸ್ನೇಹಪೂರ್ವಕ ಜ್ಞಾಪನೆ. ಈ ಸಂದೇಶವನ್ನು ನಿರ್ವಾಹಕರಿಗೆ ಮಾತ್ರ ಕಾಣಿಸುತ್ತದೆ, ಮತ್ತು ನಿಮ್ಮ ಸೆಟ್ಟಿಂಗ್‌ಗಳಲ್ಲಿ <a href="#pro-api">ಇಲ್ಲಿ</a> ಇದನ್ನು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಿದಾಗ ಇದು ಮಾಯವಾಗುತ್ತದೆ.','Development Versions &amp; Updates'=>'ಅಭಿವೃದ್ಧಿ ಆವೃತ್ತಿಗಳು &amp; ಅಪ್‌ಡೇಟ್‌ಗಳು','Difference from the price paid at the time of sale'=>'ಮಾರಾಟದ ಸಮಯದಲ್ಲಿ ಪಾವತಿಸಿದ ಬೆಲೆಯಿಂದ ವ್ಯತ್ಯಾಸ','Direct Link'=>'ನೇರ ಲಿಂಕ್','Disable'=>'ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಿ','Disable  WordPress Thumbnails?'=>'WordPress ಕಿರುಚಿತ್ರಗಳನ್ನು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸುವುದೇ?','Disable %s'=>'%s ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಿ','Disable new registration email?'=>'ಹೊಸ ನೋಂದಣಿ ಇಮೇಲ್ ಅನ್ನು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಬೇಕೇ?','Disable thumbnails?'=>'ಕಿರುಚಿತ್ರಗಳನ್ನು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸುವುದೇ?','Disable title rewriting?'=>'ಶೀರ್ಷಿಕೆ ಪುನರ್‌ಬರಹವನ್ನು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸುವುದೇ?','Disabled'=>'ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಲಾಗಿದೆ','Disconnect'=>'ಸಂಪರ್ಕ ಕಡಿತಗೊಳಿಸಿ','Disconnect All'=>'ಎಲ್ಲವನ್ನೂ ಸಂಪರ್ಕ ಕಡಿತಗೊಳಿಸಿ','Discounts (After Taxes)'=>'ರಿಯಾಯಿತಿಗಳು (ತೆರಿಗೆಯ ನಂತರ)','Discounts Before Taxes'=>'ತೆರಿಗೆಗೆ ಮೊದಲಿನ ರಿಯಾಯಿತಿಗಳು','Dismiss'=>'ವಜಾಮಾಡಿ','Dismiss Message'=>'ಸಂದೇಶವನ್ನು ವಜಾಮಾಡಿ','Disonnect'=>'ಸಂಪರ್ಕ ಕಡಿತಗೊಳಿಸಿ','Display %s as'=>'%s ಅನ್ನು ಹೀಗೆ ಪ್ರದರ್ಶಿಸಿ','Display %s on your blog.'=>'ನಿಮ್ಮ ಬ್ಲಾಗ್‌ನಲ್ಲಿ %s ಅನ್ನು ಪ್ರದರ್ಶಿಸಿ.','Display Settings'=>'ಸಿದ್ಧತೆಗಳನ್ನು ಪ್ರದರ್ಶಿಸಿ','Display Status'=>'ಸ್ಥಿತಿಯನ್ನು ಪ್ರದರ್ಶಿಸಿ','Display a geolocation search textbox which syncs with the main search geolocation box (if enabled).'=>'ಮುಖ್ಯ ಭೌಗೋಳಿಕ ಸ್ಥಾನ ಹುಡುಕಾಟ ಪೆಟ್ಟಿಗೆಯೊಂದಿಗೆ (ಸಕ್ರಿಯಗೊಳಿಸಿದ್ದರೆ) ಸಿಂಕ್ ಆಗುವ ಭೌಗೋಳಿಕ ಸ್ಥಾನ ಹುಡುಕಾಟ ಪಠ್ಯ ಪೆಟ್ಟಿಗೆಯನ್ನು ತೋರಿಸಿ.','Display a list of event locations on Events Manager.'=>'Events Manager ನಲ್ಲಿ ಈವೆಂಟ್ ಸ್ಥಳಗಳ ಪಟ್ಟಿಯನ್ನು ಪ್ರದರ್ಶಿಸಿ.','Display a list of events on Events Manager.'=>'Events Manager ನಲ್ಲಿ ಈವೆಂಟ್‌ಗಳ ಪಟ್ಟಿಯನ್ನು ಪ್ರದರ್ಶಿಸಿ.','Display a prominent "Withdraw from contract" link in the site footer, since the law expects the function to be continuously and easily reachable.'=>'ಕಾನೂನು ಈ ಕಾರ್ಯವು ನಿರಂತರವಾಗಿ ಮತ್ತು ಸುಲಭವಾಗಿ ತಲುಪುವಂತಿರಬೇಕೆಂದು ನಿರೀಕ್ಷಿಸುವುದರಿಂದ, ತಾಣದ ಅಡಿಟಿಪ್ಪಣಿಯಲ್ಲಿ ಎದ್ದು ಕಾಣುವ "ಒಪ್ಪಂದದಿಂದ ಹಿಂಪಡೆಯಿರಿ" ಲಿಂಕ್ ಅನ್ನು ಪ್ರದರ್ಶಿಸಿ.','Display booking summary?'=>'ಬುಕಿಂಗ್ ಸಾರಾಂಶ ಪ್ರದರ್ಶಿಸಬೇಕೇ?','Display calendar in events page?'=>'ಈವೆಂಟ್‌ಗಳ ಪುಟದಲ್ಲಿ ಕ್ಯಾಲೆಂಡರ್ ಪ್ರದರ್ಶಿಸುವುದೇ?','Display events on your blog.'=>'ನಿಮ್ಮ ಬ್ಲಾಗ್‌ನಲ್ಲಿ ಈವೆಂಟ್‌ಗಳನ್ನು ಪ್ರದರ್ಶಿಸಿ.','Display free booking summary?'=>'ಉಚಿತ ಬುಕಿಂಗ್ ಸಾರಾಂಶ ಪ್ರದರ್ಶಿಸಬೇಕೇ?','Display global %s on main blog?'=>'ಮುಖ್ಯ ಬ್ಲಾಗ್‌ನಲ್ಲಿ ಗ್ಲೋಬಲ್ %s ಅನ್ನು ಪ್ರದರ್ಶಿಸುವುದೇ?','Display global events on main blog?'=>'ಮುಖ್ಯ ಬ್ಲಾಗ್‌ನಲ್ಲಿ ಗ್ಲೋಬಲ್ ಈವೆಂಟ್‌ಗಳನ್ನು ಪ್ರದರ್ಶಿಸುವುದೇ?','Display locations on your blog.'=>'ನಿಮ್ಮ ಬ್ಲಾಗ್‌ನಲ್ಲಿ ಸ್ಥಳಗಳನ್ನು ಪ್ರದರ್ಶಿಸಿ.','Display login form?'=>'ಲಾಗಿನ್ ಫಾರ್ಮ್ ಪ್ರದರ್ಶಿಸಬೇಕೇ?','Display on Frontend'=>'ಮುಂಭಾಗದಲ್ಲಿ ಪ್ರದರ್ಶಿಸಿ','Display on WP Dashboard'=>'WP ಡ್ಯಾಶ್‌ಬೋರ್ಡ್‌ನಲ್ಲಿ ಪ್ರದರ್ಶಿಸಿ','Display on bookings dashboard'=>'ಬುಕಿಂಗ್‌ಗಳ ಡ್ಯಾಶ್‌ಬೋರ್ಡ್‌ನಲ್ಲಿ ಪ್ರದರ್ಶಿಸಿ','Display on event bookings admin'=>'ಈವೆಂಟ್ ಬುಕಿಂಗ್‌ಗಳ ನಿರ್ವಹಣೆಯಲ್ಲಿ ಪ್ರದರ್ಶಿಸಿ','Display only locations with upcoming events.'=>'ಮುಂಬರುವ ಈವೆಂಟ್‌ಗಳಿರುವ ಸ್ಥಳಗಳನ್ನು ಮಾತ್ರ ಪ್ರದರ್ಶಿಸಿ.','Display subsection titles above groups of line items, such as taxes, discounts and surcharges.'=>'ತೆರಿಗೆಗಳು, ರಿಯಾಯಿತಿಗಳು ಮತ್ತು ಹೆಚ್ಚುವರಿ ಶುಲ್ಕಗಳಂತಹ ಲೈನ್ ಐಟಂ ಗುಂಪುಗಳ ಮೇಲೆ ಉಪವಿಭಾಗದ ಶೀರ್ಷಿಕೆಗಳನ್ನು ಪ್ರದರ್ಶಿಸಿ.','Display subsection titles?'=>'ಉಪವಿಭಾಗದ ಶೀರ್ಷಿಕೆಗಳನ್ನು ಪ್ರದರ್ಶಿಸಬೇಕೇ?','Display taxes separately?'=>'ತೆರಿಗೆಗಳನ್ನು ಪ್ರತ್ಯೇಕವಾಗಿ ಪ್ರದರ್ಶಿಸಬೇಕೇ?','Display the booking summary if the event is free. If there are any available tickets worth more than 0 then the event is not considered free.'=>'ಈವೆಂಟ್ ಉಚಿತವಾಗಿದ್ದರೆ ಬುಕಿಂಗ್ ಸಾರಾಂಶವನ್ನು ಪ್ರದರ್ಶಿಸಿ. 0 ಕ್ಕಿಂತ ಹೆಚ್ಚು ಮೌಲ್ಯದ ಯಾವುದೇ ಟಿಕೆಟ್‌ಗಳು ಲಭ್ಯವಿದ್ದರೆ ಈವೆಂಟ್ ಅನ್ನು ಉಚಿತವೆಂದು ಪರಿಗಣಿಸಲಾಗುವುದಿಲ್ಲ.','Display the number of available spaces (or booking status if full/closed/cancelled) in each timeslot button or dropdown option.'=>'ಪ್ರತಿ ಸಮಯ ಸ್ಲಾಟ್ ಗುಂಡಿ ಅಥವಾ ಡ್ರಾಪ್‌ಡೌನ್ ಆಯ್ಕೆಯಲ್ಲಿ ಲಭ್ಯವಿರುವ ಸ್ಥಾನಗಳ ಸಂಖ್ಯೆಯನ್ನು (ಅಥವಾ ತುಂಬಿದ್ದರೆ/ಮುಚ್ಚಿದ್ದರೆ/ರದ್ದಾಗಿದ್ದರೆ ಬುಕಿಂಗ್ ಸ್ಥಿತಿಯನ್ನು) ಪ್ರದರ್ಶಿಸಿ.','Display the timeslot date as well as the time when viewing a specific calendar day.'=>'ನಿರ್ದಿಷ್ಟ ದಿನಸೂಚಿ ದಿನವನ್ನು ವೀಕ್ಷಿಸುವಾಗ ಸಮಯದ ಜೊತೆಗೆ ಸಮಯ ಸ್ಲಾಟ್‌ನ ದಿನಾಂಕವನ್ನೂ ಪ್ರದರ್ಶಿಸಿ.','Display ticket prices without tax and calculate the tax total separately.'=>'ಟಿಕೆಟ್ ಬೆಲೆಗಳನ್ನು ತೆರಿಗೆ ಇಲ್ಲದೆ ಪ್ರದರ್ಶಿಸಿ ಮತ್ತು ತೆರಿಗೆ ಒಟ್ಟು ಮೊತ್ತವನ್ನು ಪ್ರತ್ಯೇಕವಾಗಿ ಲೆಕ್ಕಹಾಕಿ.','Display your events in a calendar widget.'=>'ನಿಮ್ಮ ಈವೆಂಟ್‌ಗಳನ್ನು ಕ್ಯಾಲೆಂಡರ್ ವಿಜೆಟ್‌ನಲ್ಲಿ ಪ್ರದರ್ಶಿಸಿ.','Displaying %1$s&#8211;%2$s of %3$s'=>'%3$s ರಲ್ಲಿ %1$s&#8211;%2$s ಪ್ರದರ್ಶಿಸಲಾಗುತ್ತಿದೆ','Displays %s from all sites on the network by default. You can still restrict %s by blog using shortcodes and template tags coupled with the <code>blog</code> attribute. Requires global tables to be turned on.'=>'ಡೀಫಾಲ್ಟ್ ಆಗಿ ನೆಟ್‌ವರ್ಕ್‌ನ ಎಲ್ಲಾ ಸೈಟ್‌ಗಳ %s ಅನ್ನು ಪ್ರದರ್ಶಿಸುತ್ತದೆ. <code>blog</code> ಗುಣಲಕ್ಷಣದೊಂದಿಗೆ ಶಾರ್ಟ್‌ಕೋಡ್‌ಗಳು ಮತ್ತು ಟೆಂಪ್ಲೇಟ್ ಟ್ಯಾಗ್‌ಗಳನ್ನು ಬಳಸಿ ನೀವು ಬ್ಲಾಗ್ ಮೂಲಕ %s ಅನ್ನು ಇನ್ನೂ ನಿರ್ಬಂಧಿಸಬಹುದು. ಗ್ಲೋಬಲ್ ಕೋಷ್ಟಕಗಳು ಆನ್ ಆಗಿರಬೇಕು.','Displays a booking summary including itemized subtotals, taxes, discounts, surcharges and totals where applicable.'=>'ಅನ್ವಯಿಸುವಲ್ಲಿ ವಿವರವಾದ ಉಪಮೊತ್ತಗಳು, ತೆರಿಗೆಗಳು, ರಿಯಾಯಿತಿಗಳು, ಹೆಚ್ಚುವರಿ ಶುಲ್ಕಗಳು ಮತ್ತು ಒಟ್ಟು ಮೊತ್ತಗಳನ್ನು ಒಳಗೊಂಡ ಬುಕಿಂಗ್ ಸಾರಾಂಶವನ್ನು ಪ್ರದರ್ಶಿಸುತ್ತದೆ.','Distance Values'=>'ದೂರದ ಮೌಲ್ಯಗಳು','Do not import'=>'ಆಮದು ಮಾಡಬೇಡಿ','Do not include'=>'ಸೇರಿಸಬೇಡಿ','Do you already have an account with us? %s'=>'ನಿಮಗೆ ಈಗಾಗಲೇ ನಮ್ಮೊಂದಿಗೆ ಖಾತೆ ಇದೆಯೇ? %s','Document'=>'ದಾಖಲೆ','Documentation'=>'ದಾಖಲೆ','Don\'t have it? Leave this blank and we\'ll email you a secure link to choose your booking.'=>'ಇಲ್ಲವೇ? ಇದನ್ನು ಖಾಲಿ ಬಿಡಿ, ನಿಮ್ಮ ಬುಕಿಂಗ್ ಆಯ್ಕೆಮಾಡಲು ನಾವು ಸುರಕ್ಷಿತ ಲಿಂಕ್ ಅನ್ನು ಇಮೇಲ್ ಮಾಡುತ್ತೇವೆ.','Download %s'=>'%s ಡೌನ್ಲೋಡ್ ಮಾಡಿ','Download featured images given as web addresses'=>'ವೆಬ್ ವಿಳಾಸಗಳಾಗಿ ನೀಡಿದ ವಿಶೇಷ ಚಿತ್ರಗಳನ್ನು ಡೌನ್‌ಲೋಡ್ ಮಾಡಿ','Draft'=>'ಕರಡು','Drafts'=>'ಕರಡುಗಳು','Dropdown Selection'=>'ಡ್ರಾಪ್‌ಡೌನ್ ಆಯ್ಕೆ','Due to how we change how this custom taxonomy is displayed when overriding with formats it is strongly advised that you assign a %s page below, which increases compatibility with various plugins and themes.'=>'ಸ್ವರೂಪಗಳೊಂದಿಗೆ ಮೀರಿಸುವಾಗ ಈ ಕಸ್ಟಮ್ ಟ್ಯಾಕ್ಸಾನಮಿಯನ್ನು ತೋರಿಸುವ ವಿಧಾನವನ್ನು ನಾವು ಬದಲಾಯಿಸುವುದರಿಂದ, ವಿವಿಧ ಪ್ಲಗಿನ್‌ಗಳು ಮತ್ತು ಥೀಮ್‌ಗಳೊಂದಿಗೆ ಹೊಂದಾಣಿಕೆಯನ್ನು ಹೆಚ್ಚಿಸುವ ಕೆಳಗಿನ %s ಪುಟವನ್ನು ನಿಯೋಜಿಸಲು ಬಲವಾಗಿ ಸಲಹೆ ನೀಡಲಾಗುತ್ತದೆ.','Duplicate'=>'ನಕಲು','Duplicate %s'=>'%s ನಕಲು ಮಾಡಿ','Duplicate this event'=>'ಈ ಈವೆಂಟ್ ಅನ್ನು ನಕಲು ಮಾಡಿ','Duplicating Events and Locations has been disabled by Events Manager, to avoid breaking data. You can use our Events Manager duplication features instead.'=>'ಡೇಟಾ ಹಾಳಾಗುವುದನ್ನು ತಪ್ಪಿಸಲು Events Manager ಈವೆಂಟ್‌ಗಳು ಮತ್ತು ಸ್ಥಳಗಳ ನಕಲು ಮಾಡುವಿಕೆಯನ್ನು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಿದೆ. ಬದಲಿಗೆ ನೀವು ನಮ್ಮ Events Manager ನಕಲು ವೈಶಿಷ್ಟ್ಯಗಳನ್ನು ಬಳಸಬಹುದು.','Duration'=>'ಅವಧಿ','During'=>'ಅವಧಿಯಲ್ಲಿ','E-mail'=>'ಇ-ಮೇಲ್','E-mail: %s'=>'ಇ-ಮೇಲ್: %s','ERROR : Email Not Sent.'=>'ದೋಷ: ಇಮೇಲ್ ಕಳುಹಿಸಲಾಗಿಲ್ಲ.','Each event can have its own timezone if enabled. If set to no, then all newly created events will have the blog timezone, which currently is set to %s'=>'ಸಕ್ರಿಯಗೊಳಿಸಿದರೆ ಪ್ರತಿ ಈವೆಂಟ್ ತನ್ನದೇ ಆದ ಸಮಯವಲಯವನ್ನು ಹೊಂದಬಹುದು. ಇಲ್ಲ ಎಂದು ಹೊಂದಿಸಿದರೆ, ಹೊಸದಾಗಿ ರಚಿಸಲಾದ ಎಲ್ಲಾ ಈವೆಂಟ್‌ಗಳು ಬ್ಲಾಗ್‌ನ ಸಮಯವಲಯವನ್ನು ಹೊಂದಿರುತ್ತವೆ, ಅದು ಪ್ರಸ್ತುತ %s ಎಂದು ಹೊಂದಿಸಲಾಗಿದೆ','Earlier Dates'=>'ಹಿಂದಿನ ದಿನಾಂಕಗಳು','Edit'=>'ಸಂಪಾದಿಸಿ','Edit %s'=>'%s ಸಂಪಾದಿಸಿ','Edit Booking'=>'ಬುಕಿಂಗ್ ಸಂಪಾದಿಸಿ','Edit Details'=>'ವಿವರಗಳನ್ನು ಸಂಪಾದಿಸಿ','Edit Event'=>'ಈವೆಂಟ್ ಸಂಪಾದಿಸಿ','Edit Event Category'=>'ಈವೆಂಟ್ ವರ್ಗ ಸಂಪಾದಿಸಿ','Edit Event Tag'=>'ಈವೆಂಟ್ ಟ್ಯಾಗ್ ಸಂಪಾದಿಸಿ','Edit Location'=>'ಸ್ಥಳ ಸಂಪಾದಿಸಿ','Edit Recurring Event'=>'ಮರುಕಳಿಸುವ ಈವೆಂಟ್ ಸಂಪಾದಿಸಿ','Edit Repeating Event'=>'ಪುನರಾವರ್ತಿತ ಈವೆಂಟ್ ಸಂಪಾದಿಸಿ','Edit User'=>'ಬಳಕೆದಾರರನ್ನು ಸಂಪಾದಿಸಿ','Edit events'=>'ಈವೆಂಟ್‌ಗಳನ್ನು ಸಂಪಾದಿಸಿ','Edit location'=>'ಸ್ಥಳ ಸಂಪಾದಿಸಿ','Edit locations'=>'ಸ್ಥಳಗಳನ್ನು ಸಂಪಾದಿಸಿ','Edit/View'=>'ಸಂಪಾದಿಸಿ/ವೀಕ್ಷಿಸಿ','Editor'=>'ಸಂಪಾದಕ','Email'=>'ಮಿಂಚೆ','Email Address'=>'ಇಮೇಲ್ ವಿಳಾಸ','Email Exists'=>'ಇಮೇಲ್ ಅಸ್ತಿತ್ವದಲ್ಲಿದೆ','Email Message'=>'ಇಮೇಲ್ ಸಂದೇಶ','Email Sent.'=>'ಇಮೇಲ್ ಕಳುಹಿಸಲಾಗಿದೆ.','Email Settings'=>'ಇಮೇಲ್ ಸೆಟ್ಟಿಂಗ್‌ಗಳು','Email Subject'=>'ಇಮೇಲ್ ವಿಷಯ','Email address'=>'ಇಮೇಲ್ ವಿಳಾಸ','Email event owner?'=>'ಈವೆಂಟ್ ಮಾಲೀಕರಿಗೆ ಇಮೇಲ್ ಕಳುಹಿಸಬೇಕೇ?','Email events admin?'=>'ಈವೆಂಟ್ ನಿರ್ವಾಹಕರಿಗೆ ಇಮೇಲ್ ಕಳುಹಿಸಬೇಕೇ?','Email not sent.'=>'ಇಮೇಲ್ ಕಳುಹಿಸಲಾಗಿಲ್ಲ.','Email sent successfully to %s'=>'%s ಗೆ ಇಮೇಲ್ ಯಶಸ್ವಿಯಾಗಿ ಕಳುಹಿಸಲಾಗಿದೆ','Email: %s'=>'ಇಮೇಲ್: %s','Emails'=>'ಇಮೇಲ್‌ಗಳು','Embed Display Type'=>'ಹುದುಗಿಸಿದ ಪ್ರದರ್ಶನದ ಬಗೆ','Enable'=>'ಸಕ್ರಿಯಗೊಳಿಸಿ','Enable %s'=>'%s ಸಕ್ರಿಯಗೊಳಿಸಿ','Enable %s attributes?'=>'%s ಗುಣಲಕ್ಷಣಗಳನ್ನು ಸಕ್ರಿಯಗೊಳಿಸುವುದೇ?','Enable %s custom fields?'=>'%s ಕಸ್ಟಮ್ ಕ್ಷೇತ್ರಗಳನ್ನು ಸಕ್ರಿಯಗೊಳಿಸುವುದೇ?','Enable All Styling?'=>'ಎಲ್ಲಾ ಶೈಲಿಯನ್ನು ಸಕ್ರಿಯಗೊಳಿಸುವುದೇ?','Enable Archives?'=>'ಆರ್ಕೈವ್‌ಗಳನ್ನು ಸಕ್ರಿಯಗೊಳಿಸುವುದೇ?','Enable Code Editor for Formats'=>'ಸ್ವರೂಪಗಳಿಗೆ ಕೋಡ್ ಎಡಿಟರ್ ಸಕ್ರಿಯಗೊಳಿಸಿ','Enable Comments?'=>'ಕಾಮೆಂಟ್‌ಗಳನ್ನು ಸಕ್ರಿಯಗೊಳಿಸುವುದೇ?','Enable Dev Updates?'=>'ಡೆವ್ ಅಪ್‌ಡೇಟ್‌ಗಳನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಬೇಕೇ?','Enable Event Dynamic Timeslots?'=>'ಈವೆಂಟ್ ಡೈನಾಮಿಕ್ ಟೈಮ್‌ಸ್ಲಾಟ್‌ಗಳನ್ನು ಸಕ್ರಿಯಗೊಳಿಸುವುದೇ?','Enable Event Status?'=>'ಈವೆಂಟ್ ಸ್ಥಿತಿಯನ್ನು ಸಕ್ರಿಯಗೊಳಿಸುವುದೇ?','Enable Event Timeslots?'=>'ಈವೆಂಟ್ ಟೈಮ್‌ಸ್ಲಾಟ್‌ಗಳನ್ನು ಸಕ್ರಿಯಗೊಳಿಸುವುದೇ?','Enable Google Maps integration?'=>'Google ನಕ್ಷೆಗಳ ಏಕೀಕರಣವನ್ನು ಸಕ್ರಿಯಗೊಳಿಸುವುದೇ?','Enable No-User Booking Mode?'=>'ಬಳಕೆದಾರರಿಲ್ಲದ ಬುಕಿಂಗ್ ಮೋಡ್ ಅನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಬೇಕೇ?','Enable Theme Styling?'=>'ಥೀಮ್ ಶೈಲಿಯನ್ನು ಸಕ್ರಿಯಗೊಳಿಸುವುದೇ?','Enable Timezone Support?'=>'ಸಮಯವಲಯ ಬೆಂಬಲವನ್ನು ಸಕ್ರಿಯಗೊಳಿಸುವುದೇ?','Enable Visual Uploader'=>'ದೃಶ್ಯ ಅಪ್‌ಲೋಡರ್ ಸಕ್ರಿಯಗೊಳಿಸಿ','Enable a code/syntax highlighter when clicking on the larger formatting textbox options below, for easier editing of larger HTML parts.'=>'ದೊಡ್ಡ HTML ಭಾಗಗಳನ್ನು ಸುಲಭವಾಗಿ ಸಂಪಾದಿಸಲು, ಕೆಳಗಿನ ದೊಡ್ಡ ಫಾರ್ಮ್ಯಾಟಿಂಗ್ ಪಠ್ಯ ಪೆಟ್ಟಿಗೆಗಳ ಆಯ್ಕೆಗಳನ್ನು ಕ್ಲಿಕ್ ಮಾಡಿದಾಗ ಕೋಡ್/ಸಿಂಟ್ಯಾಕ್ಸ್ ಹೈಲೈಟರ್ ಅನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ.','Enable a modern visual uploader UI.'=>'ಆಧುನಿಕ ದೃಶ್ಯ ಅಪ್‌ಲೋಡರ್ UI ಅನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ.','Enable advanced fields?'=>'ಸುಧಾರಿತ ಕ್ಷೇತ್ರಗಳನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಬೇಕೇ?','Enable bookings?'=>'ಬುಕಿಂಗ್‌ಗಳನ್ನು ಸಕ್ರಿಯಗೊಳಿಸುವುದೇ?','Enable categories?'=>'ವರ್ಗಗಳನ್ನು ಸಕ್ರಿಯಗೊಳಿಸುವುದೇ?','Enable custom event archetypes?'=>'ಕಸ್ಟಮ್ ಈವೆಂಟ್ ಆರ್ಕಿಟೈಪ್‌ಗಳನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಬೇಕೇ?','Enable custom ticket ordering?'=>'ಕಸ್ಟಮ್ ಟಿಕೆಟ್ ಕ್ರಮವನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಬೇಕೇ?','Enable global tables mode?'=>'ಗ್ಲೋಬಲ್ ಟೇಬಲ್ಸ್ ಮೋಡ್ ಸಕ್ರಿಯಗೊಳಿಸುವುದೇ?','Enable locations?'=>'ಸ್ಥಳಗಳನ್ನು ಸಕ್ರಿಯಗೊಳಿಸುವುದೇ?','Enable multiple file uploads by default.'=>'ಡೀಫಾಲ್ಟ್ ಆಗಿ ಬಹು ಕಡತ ಅಪ್‌ಲೋಡ್‌ಗಳನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ.','Enable or disable each notification type. The event/item owner and managers can further control their own preferences from the mobile app.'=>'ಪ್ರತಿ ಅಧಿಸೂಚನೆಯ ಬಗೆಯನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ ಅಥವಾ ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಿ. ಈವೆಂಟ್/ಐಟಂ ಮಾಲೀಕರು ಮತ್ತು ನಿರ್ವಾಹಕರು ಮೊಬೈಲ್ ಆ್ಯಪ್‌ನಿಂದ ತಮ್ಮ ಆದ್ಯತೆಗಳನ್ನು ಇನ್ನಷ್ಟು ನಿಯಂತ್ರಿಸಬಹುದು.','Enable organizers?'=>'ಆಯೋಜಕರನ್ನು ಸಕ್ರಿಯಗೊಳಿಸುವುದೇ?','Enable push notifications?'=>'ಪುಶ್ ಅಧಿಸೂಚನೆಗಳನ್ನು ಸಕ್ರಿಯಗೊಳಿಸುವುದೇ?','Enable recurrence?'=>'ಪುನರಾವರ್ತನೆಯನ್ನು ಸಕ್ರಿಯಗೊಳಿಸುವುದೇ?','Enable registration for this event'=>'ಈ ಈವೆಂಟ್‌ಗೆ ನೋಂದಣಿಯನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ','Enable repeated events?'=>'ಮರುಕಳಿಸುವ ಈವೆಂಟ್‌ಗಳನ್ನು ಸಕ್ರಿಯಗೊಳಿಸುವುದೇ?','Enable right-of-withdrawal button?'=>'ಹಿಂಪಡೆಯುವ ಹಕ್ಕಿನ ಗುಂಡಿಯನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಬೇಕೇ?','Enable tags?'=>'ಟ್ಯಾಗ್‌ಗಳನ್ನು ಸಕ್ರಿಯಗೊಳಿಸುವುದೇ?','Enabled'=>'ಸಕ್ರಿಯಗೊಳಿಸಲಾಗಿದೆ','Enabled (off by default)'=>'ಸಕ್ರಿಯಗೊಳಿಸಲಾಗಿದೆ (ಡೀಫಾಲ್ಟ್ ಆಗಿ ಆಫ್)','Enabled (on by default)'=>'ಸಕ್ರಿಯಗೊಳಿಸಲಾಗಿದೆ (ಡೀಫಾಲ್ಟ್ ಆಗಿ ಆನ್)','Enables additional advanced search fields such as dates, country, etc.'=>'ದಿನಾಂಕಗಳು, ರಾಷ್ಟ್ರ ಮುಂತಾದ ಹೆಚ್ಚುವರಿ ಸುಧಾರಿತ ಹುಡುಕಾಟ ಕ್ಷೇತ್ರಗಳನ್ನು ಸಕ್ರಿಯಗೊಳಿಸುತ್ತದೆ.','Enabling this will prevent us from loading our CSS file on every page, and will only load on specific pages generated by Events Manager.'=>'ಇದನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿದರೆ ನಮ್ಮ CSS ಫೈಲ್ ಪ್ರತಿ ಪುಟದಲ್ಲಿ ಲೋಡ್ ಆಗುವುದನ್ನು ತಡೆಯುತ್ತದೆ, ಮತ್ತು Events Manager ರಚಿಸುವ ನಿರ್ದಿಷ್ಟ ಪುಟಗಳಲ್ಲಿ ಮಾತ್ರ ಲೋಡ್ ಆಗುತ್ತದೆ.','Encryption is always recommended if your SMTP server supports it. If your server supports TLS, this is also the most recommended method.'=>'ನಿಮ್ಮ SMTP ಸರ್ವರ್ ಬೆಂಬಲಿಸಿದರೆ ಎನ್‌ಕ್ರಿಪ್ಶನ್ ಅನ್ನು ಯಾವಾಗಲೂ ಶಿಫಾರಸು ಮಾಡಲಾಗುತ್ತದೆ. ನಿಮ್ಮ ಸರ್ವರ್ TLS ಬೆಂಬಲಿಸಿದರೆ, ಇದೇ ಅತ್ಯಂತ ಶಿಫಾರಸು ಮಾಡಲಾದ ವಿಧಾನ.','End'=>'ಅಂತ್ಯ','End Date'=>'ಅಂತಿಮ ದಿನಾಂಕ','End Time'=>'ಅಂತಿಮ ಸಮಯ','End date'=>'ಅಂತಿಮ ದಿನಾಂಕ','End time'=>'ಅಂತಿಮ ಸಮಯ','End time is required.'=>'ಅಂತ್ಯ ಸಮಯ ಅಗತ್ಯವಿದೆ.','Ends in %s'=>'%s ನಲ್ಲಿ ಕೊನೆಗೊಳ್ಳುತ್ತದೆ','Enjoying Events Manager? Help Us Improve!'=>'Events Manager ಇಷ್ಟವಾಗುತ್ತಿದೆಯೇ? ಸುಧಾರಿಸಲು ನಮಗೆ ಸಹಾಯ ಮಾಡಿ!','Enter a maximum number of spaces (required).'=>'ಗರಿಷ್ಠ ಸ್ಥಾನಗಳ ಸಂಖ್ಯೆಯನ್ನು ನಮೂದಿಸಿ (ಅಗತ್ಯವಿದೆ).','Enter a number.'=>'ಒಂದು ಸಂಖ್ಯೆಯನ್ನು ನಮೂದಿಸಿ.','Enter a ticket name.'=>'ಟಿಕೆಟ್ ಹೆಸರನ್ನು ನಮೂದಿಸಿ.','Enter the number of hours before an event starts for when users can cancel a booking. Leave blank for the start time of the event.'=>'ಬಳಕೆದಾರರು ಬುಕಿಂಗ್ ಅನ್ನು ರದ್ದುಗೊಳಿಸಬಹುದಾದ, ಈವೆಂಟ್ ಪ್ರಾರಂಭವಾಗುವ ಮೊದಲಿನ ಗಂಟೆಗಳ ಸಂಖ್ಯೆಯನ್ನು ನಮೂದಿಸಿ. ಈವೆಂಟ್‌ನ ಪ್ರಾರಂಭ ಸಮಯಕ್ಕಾಗಿ ಖಾಲಿ ಬಿಡಿ.','Enter your booking reference and email to withdraw. No account or login is required.'=>'ಹಿಂತೆಗೆದುಕೊಳ್ಳಲು ನಿಮ್ಮ ಬುಕಿಂಗ್ ಉಲ್ಲೇಖ ಮತ್ತು ಇಮೇಲ್ ನಮೂದಿಸಿ. ಖಾತೆ ಅಥವಾ ಲಾಗಿನ್ ಅಗತ್ಯವಿಲ್ಲ.','Error mailing user'=>'ಬಳಕೆದಾರರಿಗೆ ಇಮೇಲ್ ಕಳುಹಿಸುವಲ್ಲಿ ದೋಷ','Error uploading file, please try again!'=>'ಫೈಲ್ ಅಪ್‌ಲೋಡ್ ಮಾಡುವಾಗ ದೋಷ ಉಂಟಾಗಿದೆ, ದಯವಿಟ್ಟು ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ!','Errors'=>'ದೋಷಗಳು','Event'=>'ಈವೆಂಟ್','Event Admin Emails'=>'ಈವೆಂಟ್ ನಿರ್ವಾಹಕರ ಇಮೇಲ್‌ಗಳು','Event Admin/Owner Emails'=>'ಈವೆಂಟ್ ನಿರ್ವಾಹಕ/ಮಾಲೀಕರ ಇಮೇಲ್‌ಗಳು','Event Approved'=>'ಈವೆಂಟ್ ಅನುಮೋದಿಸಲಾಗಿದೆ','Event Bookings Dashboard'=>'ಈವೆಂಟ್ ಬುಕಿಂಗ್‌ಗಳ ಡ್ಯಾಶ್‌ಬೋರ್ಡ್','Event Cancellation'=>'ಈವೆಂಟ್ ರದ್ದತಿ','Event Categories'=>'ಈವೆಂಟ್ ವರ್ಗಗಳು','Event Category'=>'ಈವೆಂಟ್ ವರ್ಗ','Event Date(s)'=>'ಈವೆಂಟ್ ದಿನಾಂಕ(ಗಳು)','Event Dates'=>'ಈವೆಂಟ್ ದಿನಾಂಕಗಳು','Event Dates '=>'ಈವೆಂಟ್ ದಿನಾಂಕಗಳು ','Event Details'=>'ಈವೆಂಟ್ ವಿವರಗಳು','Event Edit and Submission Forms'=>'ಈವೆಂಟ್ ಸಂಪಾದನೆ ಮತ್ತು ಸಲ್ಲಿಕೆ ಫಾರ್ಮ್‌ಗಳು','Event ID or event ID with timeslot suffix.'=>'ಈವೆಂಟ್ ID ಅಥವಾ ಟೈಮ್‌ಸ್ಲಾಟ್ ಪ್ರತ್ಯಯವಿರುವ ಈವೆಂಟ್ ID.','Event ID.'=>'ಈವೆಂಟ್ ID.','Event Image'=>'ಈವೆಂಟ್ ಚಿತ್ರ','Event List Limits'=>'ಈವೆಂಟ್ ಪಟ್ಟಿಯ ಮಿತಿಗಳು','Event Location Placeholders'=>'ಈವೆಂಟ್ ಸ್ಥಳ ಪ್ಲೇಸ್‌ಹೋಲ್ಡರ್‌ಗಳು','Event Locations'=>'ಈವೆಂಟ್ ಸ್ಥಳಗಳು','Event Manager Options'=>'Event Manager ಆಯ್ಕೆಗಳು','Event Manager titles'=>'Events Manager ಶೀರ್ಷಿಕೆಗಳು','Event Name'=>'ಈವೆಂಟ್ ಹೆಸರು','Event Options'=>'ಈವೆಂಟ್ ಆಯ್ಕೆಗಳು','Event Preview Mode'=>'ಈವೆಂಟ್ ಮುನ್ನೋಟ ಮೋಡ್','Event Published'=>'ಈವೆಂಟ್ ಪ್ರಕಟವಾಗಿದೆ','Event Re-Submitted'=>'ಈವೆಂಟ್ ಮರುಸಲ್ಲಿಸಲಾಗಿದೆ','Event Reapproved'=>'ಈವೆಂಟ್ ಮರು-ಅನುಮೋದಿಸಲಾಗಿದೆ','Event Related Placeholders'=>'ಈವೆಂಟ್ ಸಂಬಂಧಿತ ಪ್ಲೇಸ್‌ಹೋಲ್ಡರ್‌ಗಳು','Event Status'=>'ಈವೆಂಟ್ ಸ್ಥಿತಿ','Event Style'=>'ಈವೆಂಟ್ ಶೈಲಿ','Event Submission Forms'=>'ಈವೆಂಟ್ ಸಲ್ಲಿಕೆ ಫಾರ್ಮ್‌ಗಳು','Event Submission Templates'=>'ಈವೆಂಟ್ ಸಲ್ಲಿಕೆ ಟೆಂಪ್ಲೇಟ್‌ಗಳು','Event Submitted'=>'ಈವೆಂಟ್ ಸಲ್ಲಿಸಲಾಗಿದೆ','Event Submitter Emails'=>'ಈವೆಂಟ್ ಸಲ್ಲಿಸಿದವರ ಇಮೇಲ್‌ಗಳು','Event Summary'=>'ಈವೆಂಟ್ ಸಾರಾಂಶ','Event Tag'=>'ಈವೆಂಟ್ ಟ್ಯಾಗ್','Event Tags'=>'ಈವೆಂಟ್ ಟ್ಯಾಗ್‌ಗಳು','Event Tickets Plus sells tickets as WooCommerce products. Linking keeps each booking attached to its original WooCommerce order.'=>'Event Tickets Plus ಟಿಕೆಟ್‌ಗಳನ್ನು WooCommerce ಉತ್ಪನ್ನಗಳಾಗಿ ಮಾರಾಟ ಮಾಡುತ್ತದೆ. ಲಿಂಕ್ ಮಾಡುವುದರಿಂದ ಪ್ರತಿ ಬುಕಿಂಗ್ ಅದರ ಮೂಲ WooCommerce ಆರ್ಡರ್‌ಗೆ ಜೋಡಿಸಲ್ಪಟ್ಟಿರುತ್ತದೆ.','Event Time(s)'=>'ಈವೆಂಟ್ ಸಮಯ(ಗಳು)','Event Type'=>'ಈವೆಂಟ್ ಪ್ರಕಾರ','Event and venue descriptions'=>'ಈವೆಂಟ್ ಮತ್ತು ಸ್ಥಳದ ವಿವರಣೆಗಳು','Event approved email'=>'ಈವೆಂಟ್ ಅನುಮೋದನೆ ಇಮೇಲ್','Event approved subject'=>'ಈವೆಂಟ್ ಅನುಮೋದನೆಯ ವಿಷಯ','Event archives scope'=>'ಈವೆಂಟ್ ಆರ್ಕೈವ್‌ಗಳ ವ್ಯಾಪ್ತಿ','Event attached to %s.'=>'ಈವೆಂಟ್ ಅನ್ನು %s ಗೆ ಜೋಡಿಸಲಾಗಿದೆ.','Event booking forms'=>'ಈವೆಂಟ್ ಬುಕಿಂಗ್ ಫಾರ್ಮ್‌ಗಳು','Event cancelled'=>'ಈವೆಂಟ್ ರದ್ದುಗೊಳಿಸಲಾಗಿದೆ','Event cancelled '=>'ಈವೆಂಟ್ ರದ್ದುಗೊಳಿಸಲಾಗಿದೆ ','Event categories'=>'ಈವೆಂಟ್ ವರ್ಗಗಳು','Event could not be attached.'=>'ಈವೆಂಟ್ ಅನ್ನು ಜೋಡಿಸಲಾಗಲಿಲ್ಲ.','Event could not be deleted.'=>'ಈವೆಂಟ್ ಅನ್ನು ಅಳಿಸಲಾಗಲಿಲ್ಲ.','Event could not be detached.'=>'ಈವೆಂಟ್ ಅನ್ನು ಬೇರ್ಪಡಿಸಲಾಗಲಿಲ್ಲ.','Event could not be saved.'=>'ಈವೆಂಟ್ ಅನ್ನು ಉಳಿಸಲಾಗಲಿಲ್ಲ.','Event data is invalid.'=>'ಈವೆಂಟ್ ಡೇಟಾ ಅಮಾನ್ಯವಾಗಿದೆ.','Event detached.'=>'ಈವೆಂಟ್ ಬೇರ್ಪಡಿಸಲಾಗಿದೆ.','Event format'=>'ಈವೆಂಟ್ ನಮೂನೆ','Event fully booked'=>'ಈವೆಂಟ್ ಸಂಪೂರ್ಣ ಬುಕ್ ಆಗಿದೆ','Event is fully booked.'=>'ಈವೆಂಟ್ ಸಂಪೂರ್ಣವಾಗಿ ಬುಕ್ ಆಗಿದೆ.','Event list scope'=>'ಈವೆಂಟ್ ಪಟ್ಟಿಯ ವ್ಯಾಪ್ತಿ','Event modal preview format'=>'ಈವೆಂಟ್ ಮೋಡಲ್ ಮುನ್ನೋಟದ ಸ್ವರೂಪ','Event name'=>'ಈವೆಂಟ್ ಹೆಸರು','Event not found, so the uploaded image was not set as its featured image.'=>'ಈವೆಂಟ್ ಕಂಡುಬಂದಿಲ್ಲ, ಆದ್ದರಿಂದ ಅಪ್‌ಲೋಡ್ ಮಾಡಿದ ಚಿತ್ರವನ್ನು ಅದರ ವೈಶಿಷ್ಟ್ಯಗೊಳಿಸಿದ ಚಿತ್ರವಾಗಿ ಹೊಂದಿಸಲಾಗಿಲ್ಲ.','Event not found.'=>'ಈವೆಂಟ್ ಕಂಡುಬಂದಿಲ್ಲ.','Event pages'=>'ಈವೆಂಟ್ ಪುಟಗಳು','Event published email'=>'ಈವೆಂಟ್ ಪ್ರಕಟಣೆ ಇಮೇಲ್','Event published subject'=>'ಈವೆಂಟ್ ಪ್ರಕಟಣೆಯ ವಿಷಯ','Event re-attached to %s.'=>'ಈವೆಂಟ್ ಅನ್ನು %s ಗೆ ಮರುಜೋಡಿಸಲಾಗಿದೆ.','Event reapproved email'=>'ಈವೆಂಟ್ ಮರು-ಅನುಮೋದನೆ ಇಮೇಲ್','Event reapproved subject'=>'ಈವೆಂಟ್ ಮರು-ಅನುಮೋದನೆಯ ವಿಷಯ','Event registration and booking management for WordPress. Recurring events, locations, webinars, google maps, rss, ical, booking registration and more!'=>'WordPress ಗಾಗಿ ಈವೆಂಟ್ ನೋಂದಣಿ ಮತ್ತು ಬುಕಿಂಗ್ ನಿರ್ವಹಣೆ. ಪುನರಾವರ್ತಿತ ಈವೆಂಟ್‌ಗಳು, ಸ್ಥಳಗಳು, ವೆಬಿನಾರ್‌ಗಳು, Google ನಕ್ಷೆಗಳು, RSS, iCal, ಬುಕಿಂಗ್ ನೋಂದಣಿ ಮತ್ತು ಇನ್ನಷ್ಟು!','Event resubmitted email'=>'ಈವೆಂಟ್ ಮರುಸಲ್ಲಿಕೆ ಇಮೇಲ್','Event resubmitted subject'=>'ಈವೆಂಟ್ ಮರುಸಲ್ಲಿಕೆಯ ವಿಷಯ','Event start date/time, location name'=>'ಈವೆಂಟ್ ಪ್ರಾರಂಭ ದಿನಾಂಕ/ಸಮಯ, ಸ್ಥಳದ ಹೆಸರು','Event style'=>'ಈವೆಂಟ್ ಶೈಲಿ','Event submission notifications will be sent to emails added here.'=>'ಈವೆಂಟ್ ಸಲ್ಲಿಕೆ ಅಧಿಸೂಚನೆಗಳನ್ನು ಇಲ್ಲಿ ಸೇರಿಸಿದ ಇಮೇಲ್‌ಗಳಿಗೆ ಕಳುಹಿಸಲಾಗುತ್ತದೆ.','Event submitted email'=>'ಈವೆಂಟ್ ಸಲ್ಲಿಕೆ ಇಮೇಲ್','Event submitted subject'=>'ಈವೆಂಟ್ ಸಲ್ಲಿಕೆಯ ವಿಷಯ','Event timezones for blog %s have been reset to %s.'=>'ಬ್ಲಾಗ್ %s ನ ಈವೆಂಟ್ ಸಮಯವಲಯಗಳನ್ನು %s ಗೆ ಮರುಹೊಂದಿಸಲಾಗಿದೆ.','Event timezones have been reset to %s.'=>'ಈವೆಂಟ್ ಸಮಯವಲಯಗಳನ್ನು %s ಗೆ ಮರುಹೊಂದಿಸಲಾಗಿದೆ.','Event timezones on all blogs have been reset to %s.'=>'ಎಲ್ಲಾ ಬ್ಲಾಗ್‌ಗಳ ಈವೆಂಟ್ ಸಮಯವಲಯಗಳನ್ನು %s ಗೆ ಮರುಹೊಂದಿಸಲಾಗಿದೆ.','Event title format'=>'ಈವೆಂಟ್ ಶೀರ್ಷಿಕೆ ಸ್ವರೂಪ','Event tooltip preview format'=>'ಈವೆಂಟ್ ಟೂಲ್‌ಟಿಪ್ ಮುನ್ನೋಟದ ಸ್ವರೂಪ','Event tooltips format'=>'ಈವೆಂಟ್ ಟೂಲ್‌ಟಿಪ್ ಸ್ವರೂಪ','Event website'=>'ಈವೆಂಟ್ ವೆಬ್‌ಸೈಟ್','Event.'=>'ಈವೆಂಟ್.','Event/Location admin pages'=>'ಈವೆಂಟ್/ಸ್ಥಳ ನಿರ್ವಾಹಕ ಪುಟಗಳು','Eventful Locations?'=>'ಈವೆಂಟ್‌ಗಳಿರುವ ಸ್ಥಳಗಳು?','Events'=>'ಈವೆಂಟ್‌ಗಳು','Events Calendar'=>'ಈವೆಂಟ್‌ಗಳ ಕ್ಯಾಲೆಂಡರ್','Events Duration'=>'ಈವೆಂಟ್‌ಗಳ ಅವಧಿ','Events I\'m Attending'=>'ನಾನು ಹಾಜರಾಗುತ್ತಿರುವ ಈವೆಂಟ್‌ಗಳು','Events Manager'=>'Events Manager','Events Manager - %s'=>'Events Manager - %s','Events Manager 5.9 introduced timezone functionality, which does not require certain fields in your database. To maintain backwards compatibility with earlier versions, these fields will still be created.'=>'Events Manager 5.9 ಸಮಯವಲಯ ಕಾರ್ಯವನ್ನು ಪರಿಚಯಿಸಿತು, ಇದಕ್ಕೆ ನಿಮ್ಮ ಡೇಟಾಬೇಸ್‌ನ ಕೆಲವು ಕ್ಷೇತ್ರಗಳು ಅಗತ್ಯವಿಲ್ಲ. ಹಿಂದಿನ ಆವೃತ್ತಿಗಳೊಂದಿಗೆ ಹಿಮ್ಮುಖ ಹೊಂದಾಣಿಕೆಯನ್ನು ಕಾಪಾಡಲು, ಈ ಕ್ಷೇತ್ರಗಳನ್ನು ಇನ್ನೂ ರಚಿಸಲಾಗುತ್ತದೆ.','Events Manager 6 onwards has optional styling that maximizes consistency accross different themes. If you\'d like your theme to take over in some or all aspects of our plugin, you can disable our styling here.'=>'Events Manager 6 ರಿಂದ ಮುಂದೆ, ವಿಭಿನ್ನ ಥೀಮ್‌ಗಳಲ್ಲಿ ಗರಿಷ್ಠ ಸ್ಥಿರತೆ ನೀಡುವ ಐಚ್ಛಿಕ ಶೈಲಿ ಇದೆ. ನಮ್ಮ ಪ್ಲಗಿನ್‌ನ ಕೆಲವು ಅಥವಾ ಎಲ್ಲಾ ಅಂಶಗಳಲ್ಲಿ ನಿಮ್ಮ ಥೀಮ್ ನಿಯಂತ್ರಣ ಪಡೆಯಬೇಕೆಂದು ಬಯಸಿದರೆ, ನೀವು ಇಲ್ಲಿ ನಮ್ಮ ಶೈಲಿಯನ್ನು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಬಹುದು.','Events Manager Add-ons'=>'Events Manager ಆಡ್-ಆನ್‌ಗಳು','Events Manager Bookings'=>'Events Manager ಬುಕಿಂಗ್‌ಗಳು','Events Manager Data'=>'Events Manager ಡೇಟಾ','Events Manager Management'=>'Events Manager ನಿರ್ವಹಣೆ','Events Manager Pro'=>'Events Manager Pro','Events Manager Pro %s has received a major security update. Please <a href="%s">read our announcement</a> and log into your account for upgrade options.'=>'Events Manager Pro %s ಪ್ರಮುಖ ಭದ್ರತಾ ಅಪ್‌ಡೇಟ್ ಪಡೆದಿದೆ. ದಯವಿಟ್ಟು <a href="%s">ನಮ್ಮ ಪ್ರಕಟಣೆಯನ್ನು ಓದಿ</a> ಮತ್ತು ಅಪ್‌ಗ್ರೇಡ್ ಆಯ್ಕೆಗಳಿಗಾಗಿ ನಿಮ್ಮ ಖಾತೆಗೆ ಲಾಗ್ ಇನ್ ಮಾಡಿ.','Events Manager Settings'=>'Events Manager ಸೆಟ್ಟಿಂಗ್ ಗಳು','Events Manager Test Email'=>'Events Manager ಪರೀಕ್ಷಾ ಇಮೇಲ್','Events Manager app'=>'Events Manager ಆ್ಯಪ್','Events Manager bookings'=>'Events Manager ಬುಕಿಂಗ್‌ಗಳು','Events Manager bookings linked to their WooCommerce orders (Events Manager for WooCommerce)'=>'ತಮ್ಮ WooCommerce ಆರ್ಡರ್‌ಗಳಿಗೆ ಲಿಂಕ್ ಮಾಡಲಾದ Events Manager ಬುಕಿಂಗ್‌ಗಳು (Events Manager for WooCommerce)','Events Manager can copy your events, venues, organizers, tickets and attendees from %1$s. Nothing in %1$s is changed, so you can check the result before switching it off.'=>'Events Manager ನಿಮ್ಮ ಈವೆಂಟ್‌ಗಳು, ಸ್ಥಳಗಳು, ಆಯೋಜಕರು, ಟಿಕೆಟ್‌ಗಳು ಮತ್ತು ಹಾಜರಾತಿದಾರರನ್ನು %1$s ನಿಂದ ನಕಲಿಸಬಹುದು. %1$s ನಲ್ಲಿ ಯಾವುದನ್ನೂ ಬದಲಾಯಿಸಲಾಗುವುದಿಲ್ಲ, ಆದ್ದರಿಂದ ಅದನ್ನು ಆಫ್ ಮಾಡುವ ಮೊದಲು ನೀವು ಫಲಿತಾಂಶವನ್ನು ಪರಿಶೀಲಿಸಬಹುದು.','Events Manager can now show you the latest stable release as soon as it is published, we <b>strongly</b> recommend you do this. Enable this under %1$s. %2$s'=>'Events Manager ಈಗ ಇತ್ತೀಚಿನ ಸ್ಥಿರ ಬಿಡುಗಡೆಯನ್ನು ಪ್ರಕಟವಾದ ತಕ್ಷಣ ನಿಮಗೆ ತೋರಿಸಬಲ್ಲದು, ಇದನ್ನು ಮಾಡಲು ನಾವು <b>ಬಲವಾಗಿ</b> ಶಿಫಾರಸು ಮಾಡುತ್ತೇವೆ. ಇದನ್ನು %1$s ಅಡಿಯಲ್ಲಿ ಸಕ್ರಿಯಗೊಳಿಸಿ. %2$s','Events Manager cannot be uninstalled from this site.'=>'ಈ ಸೈಟ್‌ನಿಂದ Events Manager ಅನ್ನು ಅನ್‌ಇನ್‌ಸ್ಟಾಲ್ ಮಾಡಲು ಸಾಧ್ಯವಿಲ್ಲ.','Events Manager for WooCommerce'=>'WooCommerce ಗಾಗಿ Events Manager','Events Manager found events from %s on this site and can copy them, with their venues, organizers, tickets and attendees.'=>'Events Manager ಈ ಸೈಟ್‌ನಲ್ಲಿ %s ನಿಂದ ಈವೆಂಟ್‌ಗಳನ್ನು ಕಂಡುಕೊಂಡಿದೆ ಮತ್ತು ಅವುಗಳ ಸ್ಥಳಗಳು, ಆಯೋಜಕರು, ಟಿಕೆಟ್‌ಗಳು ಮತ್ತು ಹಾಜರಾತಿದಾರರೊಂದಿಗೆ ನಕಲಿಸಬಹುದು.','Events Manager has been maintained, developed and supported for free since it was released in 2008, positive reviews are one that help us keep going.'=>'Events Manager ಅನ್ನು 2008 ರಲ್ಲಿ ಬಿಡುಗಡೆ ಮಾಡಿದಾಗಿನಿಂದ ಉಚಿತವಾಗಿ ನಿರ್ವಹಿಸಲಾಗುತ್ತಿದೆ, ಅಭಿವೃದ್ಧಿಪಡಿಸಲಾಗುತ್ತಿದೆ ಮತ್ತು ಬೆಂಬಲಿಸಲಾಗುತ್ತಿದೆ, ಒಳ್ಳೆಯ ವಿಮರ್ಶೆಗಳು ನಾವು ಮುಂದುವರಿಯಲು ಸಹಾಯ ಮಾಡುತ್ತವೆ.','Events Manager has implemented multiple ways to help prevent or reduce these costs drastically, please check our %s page for more information.'=>'ಈ ವೆಚ್ಚಗಳನ್ನು ತಡೆಯಲು ಅಥವಾ ಗಣನೀಯವಾಗಿ ಕಡಿಮೆ ಮಾಡಲು Events Manager ಹಲವು ಮಾರ್ಗಗಳನ್ನು ಅಳವಡಿಸಿದೆ, ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ದಯವಿಟ್ಟು ನಮ್ಮ %s ಪುಟವನ್ನು ನೋಡಿ.','Events Manager has introduced location types, which can include online locations such as a URL or integrations with webinar platforms such as Zoom! Enable different location types in your settings page, for more information see our %s.'=>'Events Manager ಸ್ಥಳ ಪ್ರಕಾರಗಳನ್ನು ಪರಿಚಯಿಸಿದೆ, ಇದರಲ್ಲಿ URL ನಂತಹ ಆನ್‌ಲೈನ್ ಸ್ಥಳಗಳು ಅಥವಾ Zoom ನಂತಹ ವೆಬಿನಾರ್ ವೇದಿಕೆಗಳೊಂದಿಗಿನ ಏಕೀಕರಣಗಳು ಸೇರಿವೆ! ನಿಮ್ಮ ಸೆಟ್ಟಿಂಗ್ ಗಳ ಪುಟದಲ್ಲಿ ವಿಭಿನ್ನ ಸ್ಥಳ ಪ್ರಕಾರಗಳನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ, ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ನಮ್ಮ %s ನೋಡಿ.','Events Manager has introduced new privacy tools to help you comply with international laws such as the GDPR, <a href="%s">see our documentation</a> for more information.'=>'GDPR ನಂತಹ ಅಂತರರಾಷ್ಟ್ರೀಯ ಕಾನೂನುಗಳನ್ನು ಪಾಲಿಸಲು ಸಹಾಯ ಮಾಡುವ ಹೊಸ ಗೌಪ್ಯತೆ ಸಾಧನಗಳನ್ನು Events Manager ಪರಿಚಯಿಸಿದೆ, ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ <a href="%s">ನಮ್ಮ ದಾಖಲೆಯನ್ನು ನೋಡಿ</a>.','Events Manager has no rule for %1$s, so this was imported as %2$d date.'=>'%1$s ಗಾಗಿ Events Manager ನಲ್ಲಿ ನಿಯಮವಿಲ್ಲ, ಆದ್ದರಿಂದ ಇದನ್ನು %2$d ದಿನಾಂಕವಾಗಿ ಆಮದು ಮಾಡಲಾಗಿದೆ.' . "\0" . '%1$s ಗಾಗಿ Events Manager ನಲ್ಲಿ ನಿಯಮವಿಲ್ಲ, ಆದ್ದರಿಂದ ಇದನ್ನು %2$d ದಿನಾಂಕಗಳ ಪಟ್ಟಿಯಾಗಿ ಆಮದು ಮಾಡಲಾಗಿದೆ.','Events Manager has no rule for %s.'=>'%s ಗಾಗಿ Events Manager ನಲ್ಲಿ ನಿಯಮವಿಲ್ಲ.','Events Manager has no rule for these yet. Such rows are imported as a list of dates, or skipped if you choose that, and the result report names each one.'=>'ಇವುಗಳಿಗೆ Events Manager ನಲ್ಲಿ ಇನ್ನೂ ನಿಯಮವಿಲ್ಲ. ಅಂತಹ ಸಾಲುಗಳನ್ನು ದಿನಾಂಕಗಳ ಪಟ್ಟಿಯಾಗಿ ಆಮದು ಮಾಡಲಾಗುತ್ತದೆ, ಅಥವಾ ನೀವು ಆಯ್ಕೆಮಾಡಿದರೆ ಬಿಟ್ಟುಬಿಡಲಾಗುತ್ತದೆ, ಮತ್ತು ಫಲಿತಾಂಶ ವರದಿಯು ಪ್ರತಿಯೊಂದನ್ನೂ ಹೆಸರಿಸುತ್ತದೆ.','Events Manager now has a <a href="">mobile app</a> 🥳 🎉, download it now!'=>'Events Manager ಈಗ <a href="">ಮೊಬೈಲ್ ಆ್ಯಪ್</a> ಹೊಂದಿದೆ 🥳 🎉, ಈಗಲೇ ಡೌನ್‌ಲೋಡ್ ಮಾಡಿ!','Events Manager now supports multiple timezones for your events! Your events will initially match your blog timezone.'=>'Events Manager ಈಗ ನಿಮ್ಮ ಈವೆಂಟ್‌ಗಳಿಗೆ ಬಹು ಸಮಯವಲಯಗಳನ್ನು ಬೆಂಬಲಿಸುತ್ತದೆ! ನಿಮ್ಮ ಈವೆಂಟ್‌ಗಳು ಆರಂಭದಲ್ಲಿ ನಿಮ್ಮ ಬ್ಲಾಗ್ ಸಮಯವಲಯಕ್ಕೆ ಹೊಂದಿಕೆಯಾಗುತ್ತವೆ.','Events Manager repeats daily, weekly, monthly on a weekday such as the second Tuesday, and yearly, up to an end date. It has no rule for a day of the month or for ending after a number of times. Either way the result report names each row.'=>'Events Manager ದೈನಂದಿನ, ಸಾಪ್ತಾಹಿಕ, ಎರಡನೇ ಮಂಗಳವಾರದಂತಹ ವಾರದ ದಿನದಂದು ಮಾಸಿಕ, ಮತ್ತು ವಾರ್ಷಿಕವಾಗಿ ಅಂತಿಮ ದಿನಾಂಕದವರೆಗೆ ಪುನರಾವರ್ತಿಸುತ್ತದೆ. ತಿಂಗಳ ದಿನ ಅಥವಾ ಹಲವು ಬಾರಿಯ ನಂತರ ಕೊನೆಗೊಳ್ಳಲು ಅದರಲ್ಲಿ ನಿಯಮವಿಲ್ಲ. ಹೇಗಿದ್ದರೂ ಫಲಿತಾಂಶ ವರದಿಯು ಪ್ರತಿ ಸಾಲನ್ನು ಹೆಸರಿಸುತ್ತದೆ.','Events Manager tools — create and manage events, bookings, locations, tickets and media — for MCP-compatible AI clients.'=>'MCP-ಹೊಂದಾಣಿಕೆಯ AI ಕ್ಲೈಂಟ್‌ಗಳಿಗಾಗಿ Events Manager ಉಪಕರಣಗಳು: ಈವೆಂಟ್‌ಗಳು, ಬುಕಿಂಗ್‌ಗಳು, ಸ್ಥಳಗಳು, ಟಿಕೆಟ್‌ಗಳು ಮತ್ತು ಮಾಧ್ಯಮವನ್ನು ರಚಿಸಿ ಮತ್ತು ನಿರ್ವಹಿಸಿ.','Events Manager validation errors from the last save, if any.'=>'ಕೊನೆಯ ಉಳಿಸುವಿಕೆಯ Events Manager ಮೌಲ್ಯೀಕರಣ ದೋಷಗಳು, ಇದ್ದರೆ.','Events Manager was not uninstalled. This network shares one set of event and booking tables, so uninstalling from this site would permanently delete the events and bookings of every site on the network. Uninstall from the %s instead.'=>'Events Manager ಅನ್ನು ಅನ್‌ಇನ್‌ಸ್ಟಾಲ್ ಮಾಡಲಾಗಿಲ್ಲ. ಈ ನೆಟ್‌ವರ್ಕ್ ಒಂದೇ ಈವೆಂಟ್ ಮತ್ತು ಬುಕಿಂಗ್ ಕೋಷ್ಟಕಗಳ ಗುಂಪನ್ನು ಹಂಚಿಕೊಳ್ಳುತ್ತದೆ, ಆದ್ದರಿಂದ ಈ ಸೈಟ್‌ನಿಂದ ಅನ್‌ಇನ್‌ಸ್ಟಾಲ್ ಮಾಡಿದರೆ ನೆಟ್‌ವರ್ಕ್‌ನ ಪ್ರತಿ ಸೈಟ್‌ನ ಈವೆಂಟ್‌ಗಳು ಮತ್ತು ಬುಕಿಂಗ್‌ಗಳು ಶಾಶ್ವತವಾಗಿ ಅಳಿಸಲ್ಪಡುತ್ತವೆ. ಬದಲಿಗೆ %s ನಿಂದ ಅನ್‌ಇನ್‌ಸ್ಟಾಲ್ ಮಾಡಿ.','Events Manager\'s permalink settings are changed to match, so links to your events keep working without redirects.'=>'Events Manager ನ ಪರ್ಮಾಲಿಂಕ್ ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಹೊಂದಿಕೆಯಾಗುವಂತೆ ಬದಲಾಯಿಸಲಾಗುತ್ತದೆ, ಆದ್ದರಿಂದ ನಿಮ್ಮ ಈವೆಂಟ್‌ಗಳ ಲಿಂಕ್‌ಗಳು ಮರುನಿರ್ದೇಶನಗಳಿಲ್ಲದೆ ಕೆಲಸ ಮಾಡುತ್ತಲೇ ಇರುತ್ತವೆ.','Events Types (Archetypes)'=>'ಈವೆಂಟ್ ಬಗೆಗಳು (ಆರ್ಕಿಟೈಪ್‌ಗಳು)','Events With Bookings Enabled'=>'ಬುಕಿಂಗ್ ಸಕ್ರಿಯಗೊಳಿಸಿದ ಈವೆಂಟ್‌ಗಳು','Events can choose their own?'=>'ಈವೆಂಟ್‌ಗಳು ತಮ್ಮದನ್ನು ಆಯ್ಕೆಮಾಡಬಹುದೇ?','Events can have a status associated with them, such as a cancelled event, which can then be filtered out of search listings. By default, or if disabled, events have an %s status.'=>'ಈವೆಂಟ್‌ಗಳಿಗೆ ರದ್ದುಗೊಂಡ ಈವೆಂಟ್‌ನಂತಹ ಸ್ಥಿತಿ ಇರಬಹುದು, ಅದನ್ನು ಹುಡುಕಾಟ ಪಟ್ಟಿಗಳಿಂದ ಹೊರಗಿಡಬಹುದು. ಡೀಫಾಲ್ಟ್ ಆಗಿ, ಅಥವಾ ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಿದ್ದರೆ, ಈವೆಂಟ್‌ಗಳು %s ಸ್ಥಿತಿಯನ್ನು ಹೊಂದಿರುತ್ತವೆ.','Events can have multiple times per day, the timeslots can be selected from booking forms, timeslots do not have their own event page and are housed under the same event.'=>'ಈವೆಂಟ್‌ಗಳು ದಿನಕ್ಕೆ ಹಲವು ಸಮಯಗಳನ್ನು ಹೊಂದಬಹುದು, ಟೈಮ್‌ಸ್ಲಾಟ್‌ಗಳನ್ನು ಬುಕಿಂಗ್ ಫಾರ್ಮ್‌ಗಳಿಂದ ಆರಿಸಬಹುದು, ಟೈಮ್‌ಸ್ಲಾಟ್‌ಗಳಿಗೆ ಪ್ರತ್ಯೇಕ ಈವೆಂಟ್ ಪುಟವಿರುವುದಿಲ್ಲ ಮತ್ತು ಅವು ಅದೇ ಈವೆಂಟ್‌ನ ಅಡಿಯಲ್ಲಿರುತ್ತವೆ.','Events cannot start after they end.'=>'ಈವೆಂಟ್‌ಗಳು ಮುಗಿದ ನಂತರ ಪ್ರಾರಂಭವಾಗಲು ಸಾಧ್ಯವಿಲ್ಲ.','Events current and next month'=>'ಪ್ರಸ್ತುತ ಮತ್ತು ಮುಂದಿನ ತಿಂಗಳ ಈವೆಂಟ್‌ಗಳು','Events date modal preview format'=>'ಈವೆಂಟ್‌ಗಳ ದಿನಾಂಕ ಮೋಡಲ್ ಮುನ್ನೋಟದ ಸ್ವರೂಪ','Events imported from CSV files'=>'CSV ಫೈಲ್‌ಗಳಿಂದ ಆಮದು ಮಾಡಿದ ಈವೆಂಟ್‌ಗಳು','Events list page'=>'ಈವೆಂಟ್‌ಗಳ ಪಟ್ಟಿ ಪುಟ','Events list settings'=>'ಈವೆಂಟ್‌ಗಳ ಪಟ್ಟಿ ಸೆಟ್ಟಿಂಗ್‌ಗಳು','Events next month'=>'ಮುಂದಿನ ತಿಂಗಳ ಈವೆಂಟ್‌ಗಳು','Events on %s'=>'%s ರಂದು ಈವೆಂಟ್‌ಗಳು','Events page'=>'ಈವೆಂಟ್‌ಗಳ ಪುಟ','Events per day'=>'ದಿನಕ್ಕೆ ಈವೆಂಟ್‌ಗಳು','Events require a user to own them. In order to allow events to be submitted anonymously you need to assign that event a specific user. We recommend you create a "Anonymous" subscriber with a very good password and use that. Guests will have the same event permissions as this user when submitting.'=>'ಈವೆಂಟ್‌ಗಳಿಗೆ ಮಾಲೀಕರಾಗಿ ಒಬ್ಬ ಬಳಕೆದಾರ ಅಗತ್ಯ. ಈವೆಂಟ್‌ಗಳನ್ನು ಅನಾಮಿಕವಾಗಿ ಸಲ್ಲಿಸಲು ಅನುಮತಿಸಲು, ಆ ಈವೆಂಟ್‌ಗೆ ನಿರ್ದಿಷ್ಟ ಬಳಕೆದಾರರನ್ನು ನಿಗದಿಪಡಿಸಬೇಕು. ತುಂಬಾ ಉತ್ತಮ ಪಾಸ್‌ವರ್ಡ್ ಇರುವ "Anonymous" ಚಂದಾದಾರರನ್ನು ರಚಿಸಿ ಅದನ್ನು ಬಳಸಲು ನಾವು ಶಿಫಾರಸು ಮಾಡುತ್ತೇವೆ. ಅತಿಥಿಗಳು ಸಲ್ಲಿಸುವಾಗ ಈ ಬಳಕೆದಾರರಂತೆಯೇ ಈವೆಂಟ್ ಅನುಮತಿಗಳನ್ನು ಹೊಂದಿರುತ್ತಾರೆ.','Events this month'=>'ಈ ತಿಂಗಳ ಈವೆಂಟ್‌ಗಳು','Events this month (today onwards)'=>'ಈ ತಿಂಗಳ ಈವೆಂಟ್‌ಗಳು (ಇಂದಿನಿಂದ ಮುಂದೆ)','Events this week (today to %s)'=>'ಈ ವಾರದ ಈವೆಂಟ್‌ಗಳು (ಇಂದಿನಿಂದ %s ವರೆಗೆ)','Events this whole week (%s to %s)'=>'ಈ ಇಡೀ ವಾರದ ಈವೆಂಟ್‌ಗಳು (%s ರಿಂದ %s)','Events with multiple dates will appear on each of those dates in the calendar.'=>'ಹಲವು ದಿನಾಂಕಗಳಿರುವ ಈವೆಂಟ್‌ಗಳು ದಿನಸೂಚಿಯಲ್ಲಿ ಆ ಪ್ರತಿ ದಿನಾಂಕದಂದೂ ಕಾಣಿಸುತ್ತವೆ.','Events with timeslots can further break up timeslots dynamically by adding timeslot durations, buffers and frequencies to create multiple timeslots from one time range. For example, in the mornings, you can have a timeslot every 45 minutes at the start of each hour.'=>'ಟೈಮ್‌ಸ್ಲಾಟ್‌ಗಳಿರುವ ಈವೆಂಟ್‌ಗಳು, ಟೈಮ್‌ಸ್ಲಾಟ್ ಅವಧಿಗಳು, ಬಫರ್‌ಗಳು ಮತ್ತು ಆವರ್ತನಗಳನ್ನು ಸೇರಿಸುವ ಮೂಲಕ ಒಂದು ಸಮಯದ ವ್ಯಾಪ್ತಿಯಿಂದ ಹಲವು ಟೈಮ್‌ಸ್ಲಾಟ್‌ಗಳನ್ನು ರಚಿಸಿ ಅವುಗಳನ್ನು ಡೈನಾಮಿಕ್ ಆಗಿ ಇನ್ನಷ್ಟು ವಿಭಜಿಸಬಹುದು. ಉದಾಹರಣೆಗೆ, ಬೆಳಗ್ಗೆ ಪ್ರತಿ ಗಂಟೆಯ ಆರಂಭದಲ್ಲಿ ಪ್ರತಿ 45 ನಿಮಿಷಕ್ಕೆ ಒಂದು ಟೈಮ್‌ಸ್ಲಾಟ್ ಇರಿಸಬಹುದು.','Events within 12 months'=>'12 ತಿಂಗಳೊಳಗಿನ ಈವೆಂಟ್‌ಗಳು','Events within 2 months'=>'2 ತಿಂಗಳೊಳಗಿನ ಈವೆಂಟ್‌ಗಳು','Events within 3 months'=>'3 ತಿಂಗಳೊಳಗಿನ ಈವೆಂಟ್‌ಗಳು','Events within 6 months'=>'6 ತಿಂಗಳೊಳಗಿನ ಈವೆಂಟ್‌ಗಳು','Events won\'t recurr on the following dates:'=>'ಈ ಕೆಳಗಿನ ದಿನಾಂಕಗಳಲ್ಲಿ ಈವೆಂಟ್‌ಗಳು ಪುನರಾವರ್ತನೆಯಾಗುವುದಿಲ್ಲ:','Every Minute'=>'ಪ್ರತಿ ನಿಮಿಷ','Everyone'=>'ಎಲ್ಲರೂ','Everyone else sees the link text without the link. Attendees whose booking includes virtual access get their own join link once the booking is approved. Without bookings, the link is always shown.'=>'ಉಳಿದ ಎಲ್ಲರಿಗೂ ಲಿಂಕ್ ಇಲ್ಲದೆ ಲಿಂಕ್ ಪಠ್ಯ ಕಾಣಿಸುತ್ತದೆ. ಬುಕಿಂಗ್ ವರ್ಚುವಲ್ ಪ್ರವೇಶವನ್ನು ಒಳಗೊಂಡಿರುವ ಹಾಜರಾತಿದಾರರು ಬುಕಿಂಗ್ ಅನುಮೋದಿಸಿದ ನಂತರ ತಮ್ಮದೇ ಸೇರುವ ಲಿಂಕ್ ಪಡೆಯುತ್ತಾರೆ. ಬುಕಿಂಗ್‌ಗಳಿಲ್ಲದಿದ್ದರೆ, ಲಿಂಕ್ ಯಾವಾಗಲೂ ತೋರಿಸಲಾಗುತ್ತದೆ.','Everything in Pro'=>'Pro ನಲ್ಲಿರುವ ಎಲ್ಲವೂ','Everything in Pro, plus every add-on listed here, on a single license.'=>'Pro ನಲ್ಲಿರುವ ಎಲ್ಲವೂ, ಜೊತೆಗೆ ಇಲ್ಲಿ ಪಟ್ಟಿ ಮಾಡಿದ ಪ್ರತಿ ಆಡ್-ಆನ್, ಒಂದೇ ಪರವಾನಗಿಯಲ್ಲಿ.','Everything on %s is public, so the link appears on the event page and in calendar feeds.'=>'%s ನಲ್ಲಿರುವ ಎಲ್ಲವೂ ಸಾರ್ವಜನಿಕವಾಗಿದೆ, ಆದ್ದರಿಂದ ಲಿಂಕ್ ಈವೆಂಟ್ ಪುಟದಲ್ಲಿ ಮತ್ತು ಕ್ಯಾಲೆಂಡರ್ ಫೀಡ್‌ಗಳಲ್ಲಿ ಕಾಣಿಸುತ್ತದೆ.','Example Input'=>'ಉದಾಹರಣೆ ಇನ್‌ಪುಟ್','Example:'=>'ಉದಾಹರಣೆ:','Excerpt'=>'ಸಾರಾಂಶ','Exclude %s'=>'%s ಹೊರತುಪಡಿಸಿ','Exclude Countries'=>'ರಾಷ್ಟ್ರಗಳನ್ನು ಹೊರಗಿಡಿ','Exclude on'=>'ಇವುಗಳಲ್ಲಿ ಹೊರಗಿಡಿ','Exclude taxes from subtotal?'=>'ಉಪಮೊತ್ತದಿಂದ ತೆರಿಗೆಗಳನ್ನು ಹೊರಗಿಡಬೇಕೇ?','Expand All'=>'ಎಲ್ಲವನ್ನೂ ವಿಸ್ತರಿಸಿ','Export'=>'ರಫ್ತು','Export Bookings'=>'ಬುಕಿಂಗ್‌ಗಳನ್ನು ರಫ್ತು ಮಾಡಿ','Export CSV'=>'CSV ರಫ್ತು ಮಾಡಿ','Export Settings'=>'ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ರಫ್ತು ಮಾಡಿ','Export these bookings.'=>'ಈ ಬುಕಿಂಗ್‌ಗಳನ್ನು ರಫ್ತು ಮಾಡಿ.','Export your Events Manager settings and restore them here or on another website running this plugin.'=>'ನಿಮ್ಮ Events Manager ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ರಫ್ತು ಮಾಡಿ ಮತ್ತು ಅವುಗಳನ್ನು ಇಲ್ಲಿ ಅಥವಾ ಈ ಪ್ಲಗಿನ್ ಚಾಲನೆಯಲ್ಲಿರುವ ಬೇರೆ ಜಾಲತಾಣದಲ್ಲಿ ಮರುಸ್ಥಾಪಿಸಿ.','Exported on %s'=>'%s ರಂದು ರಫ್ತು ಮಾಡಲಾಗಿದೆ','Exporter'=>'ರಫ್ತುಕಾರಕ','Failed to write upload to temporary file.'=>'ಅಪ್‌ಲೋಡ್ ಅನ್ನು ತಾತ್ಕಾಲಿಕ ಫೈಲ್‌ಗೆ ಬರೆಯಲು ವಿಫಲವಾಗಿದೆ.','Fallback panels'=>'ಪರ್ಯಾಯ ಪ್ಯಾನೆಲ್‌ಗಳು','Featured'=>'ವಿಶೇಷ','Featured (yes or no)'=>'ವಿಶೇಷ (yes ಅಥವಾ no)','Featured image (web address or media ID)'=>'ವಿಶೇಷ ಚಿತ್ರ (ವೆಬ್ ವಿಳಾಸ ಅಥವಾ ಮೀಡಿಯಾ ID)','Fields marked * are needed. A field can be given to one column only.'=>'* ಗುರುತಿಸಿದ ಕ್ಷೇತ್ರಗಳು ಅಗತ್ಯವಿದೆ. ಒಂದು ಕ್ಷೇತ್ರವನ್ನು ಒಂದು ಕಾಲಮ್‌ಗೆ ಮಾತ್ರ ನೀಡಬಹುದು.','File'=>'ಫೈಲ್','File Type'=>'ಕಡತದ ಬಗೆ','File upload is required'=>'ಫೈಲ್ ಅಪ್‌ಲೋಡ್ ಅಗತ್ಯವಿದೆ','File upload is required.'=>'ಫೈಲ್ ಅಪ್‌ಲೋಡ್ ಅಗತ್ಯವಿದೆ.','Finalize Timezones Upgrade'=>'ಸಮಯವಲಯ ಅಪ್‌ಗ್ರೇಡ್ ಅನ್ನು ಅಂತಿಮಗೊಳಿಸಿ','Find more dates from the calendar.'=>'ದಿನಸೂಚಿಯಿಂದ ಹೆಚ್ಚಿನ ದಿನಾಂಕಗಳನ್ನು ಹುಡುಕಿ.','Finished'=>'ಮುಗಿದಿದೆ','Finishing'=>'ಮುಗಿಸಲಾಗುತ್ತಿದೆ','First Name'=>'ಮೊದಲ ಹೆಸರು','First page'=>'ಮೊದಲ ಪುಟ','First row'=>'ಮೊದಲ ಸಾಲು','For monthly: first, second, third, fourth or last.'=>'monthly ಗಾಗಿ: first, second, third, fourth ಅಥವಾ last.','For more information see our %s.'=>'ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ನಮ್ಮ %s ನೋಡಿ.','For more information see our <a href="%s">data privacy documentation</a>.'=>'ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ನಮ್ಮ <a href="%s">ಡೇಟಾ ಗೌಪ್ಯತೆ ದಾಖಲೆಯನ್ನು</a> ನೋಡಿ.','For multiple emails, separate by commas (e.g. email1@test.com,email2@test.com,etc.)'=>'ಹಲವು ಇಮೇಲ್‌ಗಳಿಗೆ ಅಲ್ಪವಿರಾಮದಿಂದ ಬೇರ್ಪಡಿಸಿ (ಉದಾ. email1@test.com,email2@test.com,etc.)','For use with the %s placeholder'=>'%s ಪ್ಲೇಸ್‌ಹೋಲ್ಡರ್‌ನೊಂದಿಗೆ ಬಳಸಲು','For weekly: one or more, such as Mon, Wed. For monthly: one, used with the week of the month.'=>'weekly ಗಾಗಿ: Mon, Wed ನಂತಹ ಒಂದು ಅಥವಾ ಹೆಚ್ಚು. monthly ಗಾಗಿ: ತಿಂಗಳ ವಾರದೊಂದಿಗೆ ಬಳಸುವ ಒಂದು.','For when start/end %s are present, this will separate the two (include spaces here if necessary).'=>'ಪ್ರಾರಂಭ/ಅಂತ್ಯ %s ಇದ್ದಾಗ, ಇದು ಆ ಎರಡನ್ನು ಬೇರ್ಪಡಿಸುತ್ತದೆ (ಅಗತ್ಯವಿದ್ದರೆ ಇಲ್ಲಿ ಖಾಲಿ ಜಾಗಗಳನ್ನು ಸೇರಿಸಿ).','Force network-defined list (no subsite choice)'=>'ನೆಟ್‌ವರ್ಕ್ ವ್ಯಾಖ್ಯಾನಿತ ಪಟ್ಟಿಯನ್ನೇ ಒತ್ತಾಯಿಸಿ (ಸಬ್‌ಸೈಟ್‌ಗೆ ಆಯ್ಕೆ ಇಲ್ಲ)','Formatting'=>'ಫಾರ್ಮ್ಯಾಟಿಂಗ್','Found %d orphaned events, deleted %d successfully'=>'%d ಅನಾಥ ಈವೆಂಟ್‌ಗಳು ಕಂಡುಬಂದವು, %d ಯಶಸ್ವಿಯಾಗಿ ಅಳಿಸಲಾಗಿದೆ','Found in %s'=>'%s ನಲ್ಲಿ ಕಂಡುಬಂದಿದೆ','Free'=>'ಉಚಿತ','Free companion plugins'=>'ಉಚಿತ ಸಹವರ್ತಿ ಪ್ಲಗಿನ್‌ಗಳು','Free plugins from the Events Manager team, available on WordPress.org.'=>'Events Manager ತಂಡದ ಉಚಿತ ಪ್ಲಗಿನ್‌ಗಳು, WordPress.org ನಲ್ಲಿ ಲಭ್ಯವಿದೆ.','Frequency'=>'ಆವರ್ತನ','From '=>'ಇಂದ ','From %1$s to %2$s'=>'%1$s ಇಂದ %2$s ತನಕ','From %s a year'=>'ವರ್ಷಕ್ಕೆ %s ರಿಂದ','Front-end management pages'=>'ಫ್ರಂಟ್-ಎಂಡ್ ನಿರ್ವಹಣಾ ಪುಟಗಳು','Full Calendar Options'=>'ಫುಲ್ ಕ್ಯಾಲೆಂಡರ್ ಆಯ್ಕೆಗಳು','Full-Size Calendar'=>'ಪೂರ್ಣ ಗಾತ್ರದ ದಿನಸೂಚಿ','Fully Booked'=>'ಸಂಪೂರ್ಣ ಬುಕ್ ಆಗಿದೆ','Fully booked'=>'ಸಂಪೂರ್ಣ ಬುಕ್ ಆಗಿದೆ','Further Information'=>'ಹೆಚ್ಚಿನ ಮಾಹಿತಿ','Future'=>'ಭವಿಷ್ಯ','Future Events Only?'=>'ಭವಿಷ್ಯದ ಈವೆಂಟ್‌ಗಳು ಮಾತ್ರವೇ?','Future events'=>'ಮುಂಬರುವ ಈವೆಂಟ್‌ಗಳು','Future events only'=>'ಭವಿಷ್ಯದ ಈವೆಂಟ್‌ಗಳು ಮಾತ್ರ','Gather panels that can\'t run in the canvas into a tabbed "Event Details" box'=>'ಕ್ಯಾನ್ವಾಸ್‌ನಲ್ಲಿ ಚಲಿಸಲು ಸಾಧ್ಯವಿಲ್ಲದ ಪ್ಯಾನೆಲ್‌ಗಳನ್ನು ಟ್ಯಾಬ್ ಇರುವ "ಈವೆಂಟ್ ವಿವರಗಳು" ಬಾಕ್ಸ್‌ಗೆ ಸಂಗ್ರಹಿಸಿ','General'=>'ಸಾಮಾನ್ಯ','General JS'=>'ಸಾಮಾನ್ಯ JS','General Options'=>'ಸಾಮಾನ್ಯ ಆಯ್ಕೆಗಳು','General settings'=>'ಸಾಮಾನ್ಯ ಸೆಟ್ಟಿಂಗ್‌ಗಳು','Geolocation Search'=>'ಭೌಗೋಳಿಕ ಸ್ಥಾನ ಹುಡುಕಾಟ','Get %s'=>'%s ಪಡೆಯಿರಿ','Get booking'=>'ಬುಕಿಂಗ್ ಪಡೆಯಿರಿ','Get booking requirements'=>'ಬುಕಿಂಗ್ ಅವಶ್ಯಕತೆಗಳನ್ನು ಪಡೆಯಿರಿ','Get event'=>'ಈವೆಂಟ್ ಪಡೆಯಿರಿ','Get event availability'=>'ಈವೆಂಟ್ ಲಭ್ಯತೆಯನ್ನು ಪಡೆಯಿರಿ','Get location'=>'ಸ್ಥಳ ಪಡೆಯಿರಿ','Get ticket'=>'ಟಿಕೆಟ್ ಪಡೆಯಿರಿ','Getting Help for Events Manager'=>'Events Manager ಗಾಗಿ ಸಹಾಯ ಪಡೆಯುವುದು','Give each date of a recurring event its own meeting link'=>'ಪುನರಾವರ್ತಿತ ಈವೆಂಟ್‌ನ ಪ್ರತಿ ದಿನಾಂಕಕ್ಕೂ ತನ್ನದೇ ಮೀಟಿಂಗ್ ಲಿಂಕ್ ನೀಡಿ','Give the file to import with --file=<path>.'=>'ಆಮದು ಮಾಡಬೇಕಾದ ಫೈಲ್ ಅನ್ನು --file=<path> ನೊಂದಿಗೆ ನೀಡಿ.','Global %s slug'=>'ಗ್ಲೋಬಲ್ %s ಸ್ಲಗ್','Global Map Format'=>'ಜಾಗತಿಕ ನಕ್ಷೆ ನಮೂನೆ','Google Calendar'=>'Google ದಿನಸೂಚಿ','Google Map Type'=>'Google ನಕ್ಷೆಯ ಬಗೆ','Google Maps API Browser Key'=>'Google Maps API ಬ್ರೌಸರ್ ಕೀ','Google Maps API provides you with ways to display maps of your locations and help site visitors find events near their desired locations.'=>'Google Maps API ನಿಮ್ಮ ಸ್ಥಳಗಳ ನಕ್ಷೆಗಳನ್ನು ಪ್ರದರ್ಶಿಸಲು ಮತ್ತು ಸೈಟ್ ಸಂದರ್ಶಕರಿಗೆ ಅವರು ಬಯಸಿದ ಸ್ಥಳಗಳ ಬಳಿಯ ಈವೆಂಟ್‌ಗಳನ್ನು ಹುಡುಕಲು ಸಹಾಯ ಮಾಡಲು ದಾರಿಗಳನ್ನು ಒದಗಿಸುತ್ತದೆ.','Google Maps Style'=>'Google ನಕ್ಷೆಗಳ ಶೈಲಿ','Google Maps Styling Wizard'=>'Google ನಕ್ಷೆಗಳ ಶೈಲಿ ವಿಝಾರ್ಡ್','Google Maps and Location Services'=>'Google ನಕ್ಷೆಗಳು ಮತ್ತು ಸ್ಥಳ ಸೇವೆಗಳು','Google Maps require an API key, please see our %s page for instructions on obtaining one.'=>'Google ನಕ್ಷೆಗಳಿಗೆ API ಕೀ ಅಗತ್ಯವಿದೆ, ಅದನ್ನು ಪಡೆಯುವ ಸೂಚನೆಗಳಿಗಾಗಿ ದಯವಿಟ್ಟು ನಮ್ಮ %s ಪುಟ ನೋಡಿ.','Google has introduced new pricing for displaying maps on your site. If you have moderate traffic levels, this may likely affect you with surprise and unexpected costs!'=>'ನಿಮ್ಮ ಜಾಲತಾಣದಲ್ಲಿ ನಕ್ಷೆಗಳನ್ನು ಪ್ರದರ್ಶಿಸಲು Google ಹೊಸ ಬೆಲೆ ನಿಗದಿಯನ್ನು ಪರಿಚಯಿಸಿದೆ. ನಿಮಗೆ ಮಧ್ಯಮ ಮಟ್ಟದ ಟ್ರಾಫಿಕ್ ಇದ್ದರೆ, ಇದು ನಿಮಗೆ ಅನಿರೀಕ್ಷಿತ ವೆಚ್ಚಗಳನ್ನು ಉಂಟುಮಾಡಬಹುದು!','Google may charge you for usage, depending on how much traffic your site receives. For more information about how and where Events Manager uses the Google Maps API, and how to manage costs, please see our %s page.'=>'ನಿಮ್ಮ ಸೈಟ್‌ಗೆ ಬರುವ ಟ್ರಾಫಿಕ್ ಅನ್ನು ಅವಲಂಬಿಸಿ Google ಬಳಕೆಗೆ ಶುಲ್ಕ ವಿಧಿಸಬಹುದು. Events Manager Google Maps API ಅನ್ನು ಹೇಗೆ ಮತ್ತು ಎಲ್ಲಿ ಬಳಸುತ್ತದೆ ಮತ್ತು ವೆಚ್ಚಗಳನ್ನು ಹೇಗೆ ನಿರ್ವಹಿಸಬೇಕು ಎಂಬ ಕುರಿತು ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ನಮ್ಮ %s ಪುಟ ನೋಡಿ.','Google offers different map displays, each with varying prices and free usage allowance. See our %s page for more information on these display options.'=>'Google ವಿಭಿನ್ನ ನಕ್ಷೆ ಪ್ರದರ್ಶನಗಳನ್ನು ನೀಡುತ್ತದೆ, ಪ್ರತಿಯೊಂದಕ್ಕೂ ಬೇರೆ ಬೇರೆ ಬೆಲೆ ಮತ್ತು ಉಚಿತ ಬಳಕೆಯ ಅನುಮತಿ ಇದೆ. ಈ ಪ್ರದರ್ಶನ ಆಯ್ಕೆಗಳ ಕುರಿತು ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ನಮ್ಮ %s ಪುಟ ನೋಡಿ.','Grid'=>'ಗ್ರಿಡ್','Group By'=>'ಇದರ ಪ್ರಕಾರ ಗುಂಪು ಮಾಡಿ','Group Events'=>'ಗುಂಪಿನ ಈವೆಂಟ್‌ಗಳು','Group Ownership'=>'ಗುಂಪಿನ ಮಾಲೀಕತ್ವ','Grouped Lists'=>'ಗುಂಪು ಮಾಡಿದ ಪಟ್ಟಿಗಳು','Grouped Lists View'=>'ಗುಂಪು ಮಾಡಿದ ಪಟ್ಟಿಗಳ ನೋಟ','Grouped list default'=>'ಗುಂಪು ಮಾಡಿದ ಪಟ್ಟಿಯ ಡೀಫಾಲ್ಟ್','Grouped list format'=>'ಗುಂಪು ಮಾಡಿದ ಪಟ್ಟಿಯ ಸ್ವರೂಪ','Grouped list header'=>'ಗುಂಪು ಮಾಡಿದ ಪಟ್ಟಿಯ ಶಿರೋನಾಮೆ','Guest Default User'=>'ಅತಿಥಿಯ ಡೀಫಾಲ್ಟ್ ಬಳಕೆದಾರ','Guest User'=>'ಅತಿಥಿ ಬಳಕೆದಾರ','Guest Users'=>'ಅತಿಥಿ ಬಳಕೆದಾರರು','HTML Allowed.'=>'HTML ಅನುಮತಿಸಲಾಗಿದೆ.','HTML allowed.'=>'HTML ಅನುಮತಿಸಲಾಗಿದೆ.','HTML entity-decoded shortcode content will be sanitized after being decoded, we STRONGLY recommend leaving this enabled.'=>'HTML ಎಂಟಿಟಿ-ಡಿಕೋಡ್ ಮಾಡಿದ ಶಾರ್ಟ್‌ಕೋಡ್ ವಿಷಯವನ್ನು ಡಿಕೋಡ್ ಮಾಡಿದ ನಂತರ ಸ್ಯಾನಿಟೈಸ್ ಮಾಡಲಾಗುತ್ತದೆ. ಇದನ್ನು ಸಕ್ರಿಯವಾಗಿಯೇ ಇಡಲು ನಾವು ಬಲವಾಗಿ ಶಿಫಾರಸು ಮಾಡುತ್ತೇವೆ.','HTML is not accepted.'=>'HTML ಅನ್ನು ಸ್ವೀಕರಿಸಲಾಗುವುದಿಲ್ಲ.','Headings'=>'ಶಿರೋನಾಮೆಗಳು','Help'=>'ಸಹಾಯ','Here you can disable individual item styling eompletely or just allow basic styling. Basic styling will try to impose general structuring (such as calendar structures) but won\'t use our Strict styling rules.'=>'ಇಲ್ಲಿ ನೀವು ಪ್ರತ್ಯೇಕ ಐಟಂ ಶೈಲಿಯನ್ನು ಸಂಪೂರ್ಣವಾಗಿ ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಬಹುದು ಅಥವಾ ಮೂಲ ಶೈಲಿಯನ್ನು ಮಾತ್ರ ಅನುಮತಿಸಬಹುದು. ಮೂಲ ಶೈಲಿಯು ಸಾಮಾನ್ಯ ರಚನೆಯನ್ನು (ಕ್ಯಾಲೆಂಡರ್ ರಚನೆಗಳಂತೆ) ವಿಧಿಸಲು ಪ್ರಯತ್ನಿಸುತ್ತದೆ ಆದರೆ ನಮ್ಮ ಕಟ್ಟುನಿಟ್ಟಾದ ಶೈಲಿ ನಿಯಮಗಳನ್ನು ಬಳಸುವುದಿಲ್ಲ.','Hidden Links'=>'ಮರೆಮಾಡಿದ ಲಿಂಕ್‌ಗಳು','Hidden by default?'=>'ಡೀಫಾಲ್ಟ್ ಆಗಿ ಮರೆಮಾಡಬೇಕೇ?','Hidden from listings (yes or no)'=>'ಪಟ್ಟಿಗಳಿಂದ ಮರೆಮಾಡಲಾಗಿದೆ (yes ಅಥವಾ no)','Hidden from upcoming'=>'ಮುಂಬರುವವುಗಳಿಂದ ಮರೆಮಾಡಲಾಗಿದೆ','Hidden link text'=>'ಮರೆಮಾಡಿದ ಲಿಂಕ್ ಪಠ್ಯ','Hidden links'=>'ಮರೆಮಾಡಿದ ಲಿಂಕ್‌ಗಳು','Hide'=>'ಮರೆಮಾಡಿ','Hide Advanced Options'=>'ಹೆಚ್ಚುವರಿ ಆಯ್ಕೆಗಳನ್ನು ಮರೆಮಾಡಿ','Hide Advanced Search'=>'ಸುಧಾರಿತ ಹುಡುಕಾಟವನ್ನು ಮರೆಮಾಡಿ','Hide Search'=>'ಹುಡುಕಾಟ ಮರೆಮಾಡಿ','Hide form until tickets selected?'=>'ಟಿಕೆಟ್‌ಗಳನ್ನು ಆರಿಸುವವರೆಗೆ ಫಾರ್ಮ್ ಅನ್ನು ಮರೆಮಾಡಬೇಕೇ?','Hide label'=>'ಲೇಬಲ್ ಮರೆಮಾಡಿ','Hide link until %s minutes before the event starts'=>'ಈವೆಂಟ್ ಪ್ರಾರಂಭವಾಗುವ %s ನಿಮಿಷಗಳ ಮೊದಲವರೆಗೆ ಲಿಂಕ್ ಅನ್ನು ಮರೆಮಾಡಿ','Hide on %s screen size?'=>'%s ಪರದೆ ಗಾತ್ರದಲ್ಲಿ ಮರೆಮಾಡಬೇಕೇ?','Hold spaces while booking?'=>'ಬುಕಿಂಗ್ ಮಾಡುವಾಗ ಸ್ಥಾನಗಳನ್ನು ಹಿಡಿದಿಡಬೇಕೇ?','Hold time'=>'ಹಿಡಿತದ ಸಮಯ','Holds'=>'ಹೋಲ್ಡ್‌ಗಳು','Host account'=>'ಹೋಸ್ಟ್ ಖಾತೆ','Hosted by %s'=>'%s ಆಯೋಜಿಸಿದ್ದಾರೆ','Hours'=>'ಗಂಟೆಗಳು','How events appear on each calendar day: a labelled pill per event, a single dot, one dot per event (up to the day limit), or a coloured ring around the date. Override per calendar with the %s parameter.'=>'ಪ್ರತಿ ದಿನಸೂಚಿ ದಿನದಲ್ಲಿ ಈವೆಂಟ್‌ಗಳು ಹೇಗೆ ಕಾಣಿಸುತ್ತವೆ: ಪ್ರತಿ ಈವೆಂಟ್‌ಗೆ ಲೇಬಲ್ ಇರುವ ಮಾತ್ರೆ, ಒಂದೇ ಚುಕ್ಕೆ, ಪ್ರತಿ ಈವೆಂಟ್‌ಗೆ ಒಂದು ಚುಕ್ಕೆ (ದಿನದ ಮಿತಿಯವರೆಗೆ), ಅಥವಾ ದಿನಾಂಕದ ಸುತ್ತ ಬಣ್ಣದ ಉಂಗುರ. %s ಪ್ಯಾರಾಮೀಟರ್‌ನೊಂದಿಗೆ ಪ್ರತಿ ದಿನಸೂಚಿಗೆ ಅತಿಕ್ರಮಿಸಿ.','How long before an event can users cancel?'=>'ಈವೆಂಟ್‌ಗೆ ಎಷ್ಟು ಮೊದಲು ಬಳಕೆದಾರರು ರದ್ದುಗೊಳಿಸಬಹುದು?','How many minutes before an event starts its link is shown, when the event has no time of its own.'=>'ಈವೆಂಟ್‌ಗೆ ತನ್ನದೇ ಸಮಯವಿಲ್ಲದಿದ್ದಾಗ, ಈವೆಂಟ್ ಪ್ರಾರಂಭವಾಗುವ ಎಷ್ಟು ನಿಮಿಷಗಳ ಮೊದಲು ಅದರ ಲಿಂಕ್ ತೋರಿಸಲಾಗುತ್ತದೆ.','How many minutes the picked spaces are held for a visitor who has not submitted their booking yet.'=>'ಇನ್ನೂ ತಮ್ಮ ಬುಕಿಂಗ್ ಸಲ್ಲಿಸದ ಸಂದರ್ಶಕರಿಗಾಗಿ ಆರಿಸಿದ ಸ್ಥಾನಗಳನ್ನು ಎಷ್ಟು ನಿಮಿಷಗಳವರೆಗೆ ಹಿಡಿದಿಡಲಾಗುತ್ತದೆ.','How the first rows will import with the columns and options as last previewed. Nothing has been saved yet.'=>'ಕೊನೆಯ ಬಾರಿ ಪೂರ್ವವೀಕ್ಷಿಸಿದ ಕಾಲಮ್‌ಗಳು ಮತ್ತು ಆಯ್ಕೆಗಳೊಂದಿಗೆ ಮೊದಲ ಸಾಲುಗಳು ಹೇಗೆ ಆಮದಾಗುತ್ತವೆ. ಇನ್ನೂ ಏನನ್ನೂ ಉಳಿಸಲಾಗಿಲ್ಲ.','However, there were some problems whilst sending confirmation emails to you and/or the event contact person. You may want to contact them directly and letting them know of this error.'=>'ಆದರೆ, ನಿಮಗೆ ಮತ್ತು/ಅಥವಾ ಈವೆಂಟ್ ಸಂಪರ್ಕ ವ್ಯಕ್ತಿಗೆ ದೃಢೀಕರಣ ಇಮೇಲ್‌ಗಳನ್ನು ಕಳುಹಿಸುವಾಗ ಕೆಲವು ಸಮಸ್ಯೆಗಳು ಉಂಟಾಗಿವೆ. ನೀವು ಅವರನ್ನು ನೇರವಾಗಿ ಸಂಪರ್ಕಿಸಿ ಈ ದೋಷದ ಬಗ್ಗೆ ತಿಳಿಸಬಹುದು.','Hundreds of free hours have gone into making this free plugin, show your support and add a small link to the plugin website at the bottom of your event pages.'=>'ಈ ಉಚಿತ ಪ್ಲಗಿನ್ ಅನ್ನು ರೂಪಿಸಲು ನೂರಾರು ಉಚಿತ ಗಂಟೆಗಳನ್ನು ವಿನಿಯೋಗಿಸಲಾಗಿದೆ, ನಿಮ್ಮ ಬೆಂಬಲ ತೋರಿಸಲು ನಿಮ್ಮ ಈವೆಂಟ್ ಪುಟಗಳ ಕೆಳಭಾಗದಲ್ಲಿ ಪ್ಲಗಿನ್ ಜಾಲತಾಣಕ್ಕೆ ಒಂದು ಸಣ್ಣ ಲಿಂಕ್ ಸೇರಿಸಿ.','Hybrid'=>'ಹೈಬ್ರಿಡ್','Hybrid (Physical/Virtual)'=>'ಹೈಬ್ರಿಡ್ (ಭೌತಿಕ/ವರ್ಚುವಲ್)','Hybrid Venue (Physical/Virtual)'=>'ಹೈಬ್ರಿಡ್ ಸ್ಥಳ (ಭೌತಿಕ/ವರ್ಚುವಲ್)','I consent to my submitted data being collected and stored as outlined by the site %s.'=>'ನಾನು ಸಲ್ಲಿಸಿದ ಡೇಟಾವನ್ನು %s ಜಾಲತಾಣವು ವಿವರಿಸಿದಂತೆ ಸಂಗ್ರಹಿಸಿ ಉಳಿಸಲು ಒಪ್ಪುತ್ತೇನೆ.','I consent to the use of my provided contact information for communication purposes.'=>'ಸಂವಹನ ಉದ್ದೇಶಗಳಿಗಾಗಿ ನಾನು ನೀಡಿದ ಸಂಪರ್ಕ ಮಾಹಿತಿಯ ಬಳಕೆಗೆ ಒಪ್ಪುತ್ತೇನೆ.','I hereby withdraw from the contract for the following booking: %1$s (#%2$d).'=>'ನಾನು ಈ ಕೆಳಗಿನ ಬುಕಿಂಗ್‌ಗಾಗಿ ಒಪ್ಪಂದದಿಂದ ಹಿಂಪಡೆಯುತ್ತಿದ್ದೇನೆ: %1$s (#%2$d).','ID'=>'ID','IP: %s'=>'IP: %s','Icon to appear in dashboard admin menu for this Archetype. Accepts URLs to PNG/SVG images, %s or leave blank for default.'=>'ಈ ಆರ್ಕಿಟೈಪ್‌ಗಾಗಿ ಡ್ಯಾಶ್‌ಬೋರ್ಡ್ ನಿರ್ವಹಣಾ ಮೆನುವಿನಲ್ಲಿ ಕಾಣಿಸಲಿರುವ ಐಕಾನ್. PNG/SVG ಚಿತ್ರಗಳ URL ಗಳನ್ನು, %s ಅನ್ನು ಸ್ವೀಕರಿಸುತ್ತದೆ, ಅಥವಾ ಡೀಫಾಲ್ಟ್‌ಗಾಗಿ ಖಾಲಿ ಬಿಡಿ.','If File Type is also set, only these extensions within the permitted File Type will be permitted.'=>'ಕಡತ ಬಗೆಯನ್ನೂ ಹೊಂದಿಸಿದ್ದರೆ, ಅನುಮತಿಸಿದ ಕಡತ ಬಗೆಯೊಳಗಿನ ಈ ವಿಸ್ತರಣೆಗಳನ್ನು ಮಾತ್ರ ಅನುಮತಿಸಲಾಗುತ್ತದೆ.','If HTML emails are enabled, br tags will automatically be added for new lines.'=>'HTML ಇಮೇಲ್‌ಗಳನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿದ್ದರೆ, ಹೊಸ ಸಾಲುಗಳಿಗೆ br ಟ್ಯಾಗ್‌ಗಳನ್ನು ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಸೇರಿಸಲಾಗುತ್ತದೆ.','If a booking exists for that email address, we have sent a link to manage your withdrawal. Please check your inbox.'=>'ಆ ಇಮೇಲ್ ವಿಳಾಸಕ್ಕೆ ಬುಕಿಂಗ್ ಇದ್ದರೆ, ನಿಮ್ಮ ಹಿಂತೆಗೆದುಕೊಳ್ಳುವಿಕೆಯನ್ನು ನಿರ್ವಹಿಸಲು ನಾವು ಲಿಂಕ್ ಕಳುಹಿಸಿದ್ದೇವೆ. ದಯವಿಟ್ಟು ನಿಮ್ಮ ಇನ್‌ಬಾಕ್ಸ್ ಪರಿಶೀಲಿಸಿ.','If a booking is made and an email cannot be sent, this is added to the success message.'=>'ಬುಕಿಂಗ್ ಮಾಡಿದ ನಂತರ ಇಮೇಲ್ ಕಳುಹಿಸಲಾಗದಿದ್ದರೆ, ಇದನ್ನು ಯಶಸ್ಸಿನ ಸಂದೇಶಕ್ಕೆ ಸೇರಿಸಲಾಗುತ್ತದೆ.','If a calendar day has only one event, you can force a direct link to the event (recommended to avoid duplicate content).'=>'ದಿನಸೂಚಿಯ ದಿನದಲ್ಲಿ ಒಂದೇ ಈವೆಂಟ್ ಇದ್ದರೆ, ಈವೆಂಟ್‌ಗೆ ನೇರ ಲಿಂಕ್ ಅನ್ನು ಒತ್ತಾಯಿಸಬಹುದು (ನಕಲು ವಿಷಯವನ್ನು ತಪ್ಪಿಸಲು ಶಿಫಾರಸು ಮಾಡಲಾಗಿದೆ).','If a user has not previously given or revoked consent for a specific submitted data type (such as bookings), do we assume user has given consent by default?'=>'ಬಳಕೆದಾರರು ನಿರ್ದಿಷ್ಟ ಸಲ್ಲಿಸಿದ ಡೇಟಾ ಪ್ರಕಾರಕ್ಕೆ (ಉದಾ. ಬುಕಿಂಗ್‌ಗಳು) ಈ ಹಿಂದೆ ಒಪ್ಪಿಗೆ ನೀಡಿಲ್ಲ ಅಥವಾ ಹಿಂಪಡೆದಿಲ್ಲದಿದ್ದರೆ, ಬಳಕೆದಾರರು ಡೀಫಾಲ್ಟ್ ಆಗಿ ಒಪ್ಪಿಗೆ ನೀಡಿದ್ದಾರೆ ಎಂದು ನಾವು ಭಾವಿಸಬೇಕೇ?','If already attending and double bookings are disabled, this message will be displayed, followed by a link to the users booking page.'=>'ಈಗಾಗಲೇ ಹಾಜರಾಗುತ್ತಿದ್ದರೆ ಮತ್ತು ದ್ವಿಗುಣ ಬುಕಿಂಗ್‌ಗಳು ನಿಷ್ಕ್ರಿಯಗೊಂಡಿದ್ದರೆ, ಈ ಸಂದೇಶವನ್ನು ಪ್ರದರ್ಶಿಸಲಾಗುತ್ತದೆ, ಅದರ ನಂತರ ಬಳಕೆದಾರರ ಬುಕಿಂಗ್ ಪುಟಕ್ಕೆ ಲಿಂಕ್ ಇರುತ್ತದೆ.','If an event does not have a category assigned when editing, this one will be assigned automatically.'=>'ಸಂಪಾದಿಸುವಾಗ ಈವೆಂಟ್‌ಗೆ ವರ್ಗವನ್ನು ನಿಗದಿಪಡಿಸಿಲ್ಲದಿದ್ದರೆ, ಇದನ್ನು ಸ್ವಯಂಚಾಲಿತವಾಗಿ ನಿಗದಿಪಡಿಸಲಾಗುತ್ತದೆ.','If an event is cancelled, the following actions can be taken upon cancellation.'=>'ಈವೆಂಟ್ ರದ್ದಾದರೆ, ರದ್ದತಿಯ ಸಮಯದಲ್ಲಿ ಕೆಳಗಿನ ಕ್ರಿಯೆಗಳನ್ನು ಕೈಗೊಳ್ಳಬಹುದು.','If an event is cancelled, you can exclude them from event lists. You can display cancelled events in shortcode using the %s parameter.'=>'ಈವೆಂಟ್ ರದ್ದಾದರೆ, ಅವುಗಳನ್ನು ಈವೆಂಟ್ ಪಟ್ಟಿಗಳಿಂದ ಹೊರಗಿಡಬಹುದು. ನೀವು %s ಪ್ಯಾರಾಮೀಟರ್ ಬಳಸಿ ಶಾರ್ಟ್‌ಕೋಡ್‌ನಲ್ಲಿ ರದ್ದಾದ ಈವೆಂಟ್‌ಗಳನ್ನು ಪ್ರದರ್ಶಿಸಬಹುದು.','If an event lasts all day, this text will show if using the %s placeholder'=>'ಈವೆಂಟ್ ಇಡೀ ದಿನ ನಡೆದರೆ, %s ಪ್ಲೇಸ್‌ಹೋಲ್ಡರ್ ಬಳಸಿದಾಗ ಈ ಪಠ್ಯ ತೋರಿಸುತ್ತದೆ','If checked every booking must select one or the minimum number of this ticket.'=>'ಗುರುತು ಮಾಡಿದರೆ, ಪ್ರತಿ ಬುಕಿಂಗ್‌ನಲ್ಲಿ ಈ ಟಿಕೆಟ್‌ನ ಒಂದು ಅಥವಾ ಕನಿಷ್ಠ ಸಂಖ್ಯೆಯನ್ನು ಆಯ್ಕೆ ಮಾಡಬೇಕು.','If enabled replies to these automated emails will be sent to the person who made the booking. This takes precedence over the event owner Reply-To.'=>'ಸಕ್ರಿಯಗೊಳಿಸಿದರೆ, ಈ ಸ್ವಯಂಚಾಲಿತ ಇಮೇಲ್‌ಗಳಿಗೆ ಉತ್ತರಗಳನ್ನು ಬುಕಿಂಗ್ ಮಾಡಿದ ವ್ಯಕ್ತಿಗೆ ಕಳುಹಿಸಲಾಗುತ್ತದೆ. ಇದು ಈವೆಂಟ್ ಮಾಲೀಕರ Reply-To ಗಿಂತ ಆದ್ಯತೆ ಪಡೆಯುತ್ತದೆ.','If enabled replies to these automated emails will, by default, be sent to the email of the event owner.'=>'ಸಕ್ರಿಯಗೊಳಿಸಿದರೆ, ಈ ಸ್ವಯಂಚಾಲಿತ ಇಮೇಲ್‌ಗಳಿಗೆ ಉತ್ತರಗಳನ್ನು ಪೂರ್ವನಿಯೋಜಿತವಾಗಿ ಈವೆಂಟ್ ಮಾಲೀಕರ ಇಮೇಲ್‌ಗೆ ಕಳುಹಿಸಲಾಗುತ್ತದೆ.','If enabled, Events Manager checks WordPress.org directly for the latest stable release rather than waiting for the staggered update rollout, which can take up to 24 hours. Releases found this way are shown for a manual update only and are never auto-installed, unless you define the %1$s constant. %2$s'=>'ಸಕ್ರಿಯಗೊಳಿಸಿದರೆ, ಹಂತಹಂತದ ಅಪ್‌ಡೇಟ್ ಬಿಡುಗಡೆಗಾಗಿ (ಇದಕ್ಕೆ 24 ಗಂಟೆಗಳವರೆಗೆ ಬೇಕಾಗಬಹುದು) ಕಾಯದೆ, Events Manager ಇತ್ತೀಚಿನ ಸ್ಥಿರ ಬಿಡುಗಡೆಗಾಗಿ WordPress.org ಅನ್ನು ನೇರವಾಗಿ ಪರಿಶೀಲಿಸುತ್ತದೆ. ಈ ರೀತಿ ಕಂಡುಬಂದ ಬಿಡುಗಡೆಗಳನ್ನು ಕೈಯಾರೆ ಅಪ್‌ಡೇಟ್ ಮಾಡಲು ಮಾತ್ರ ತೋರಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ನೀವು %1$s ಕಾನ್ಸ್ಟಂಟ್ ಅನ್ನು ವ್ಯಾಖ್ಯಾನಿಸದ ಹೊರತು ಅವು ತಾನಾಗಿ ಸ್ಥಾಪನೆಯಾಗುವುದಿಲ್ಲ. %2$s','If enabled, fully booked timeslots remain visible but cannot be selected.'=>'ಸಕ್ರಿಯಗೊಳಿಸಿದರೆ, ಸಂಪೂರ್ಣ ಬುಕ್ ಆದ ಸಮಯ ಸ್ಲಾಟ್‌ಗಳು ಗೋಚರಿಸುತ್ತವೆ ಆದರೆ ಆರಿಸಲಾಗುವುದಿಲ್ಲ.','If enabled, guest visitors can supply an email address and a user account will automatically be created for them along with their booking. They will be also be able to log back in with that newly created account.'=>'ಸಕ್ರಿಯಗೊಳಿಸಿದರೆ, ಅತಿಥಿ ಸಂದರ್ಶಕರು ಇಮೇಲ್ ವಿಳಾಸವನ್ನು ನೀಡಬಹುದು ಮತ್ತು ಅವರ ಬುಕಿಂಗ್‌ನೊಂದಿಗೆ ಅವರಿಗಾಗಿ ಬಳಕೆದಾರ ಖಾತೆ ತಾನಾಗಿ ರಚಿಸಲ್ಪಡುತ್ತದೆ. ಹೊಸದಾಗಿ ರಚಿಸಿದ ಆ ಖಾತೆಯೊಂದಿಗೆ ಅವರು ಮತ್ತೆ ಲಾಗ್ ಇನ್ ಆಗಲೂ ಸಾಧ್ಯವಾಗುತ್ತದೆ.','If enabled, the entire booking form will show once a space is selected, or if an ticket is already pre-selected with minimum spaces.'=>'ಸಕ್ರಿಯಗೊಳಿಸಿದರೆ, ಒಂದು ಸ್ಥಾನವನ್ನು ಆರಿಸಿದಾಗ, ಅಥವಾ ಕನಿಷ್ಠ ಸ್ಥಾನಗಳೊಂದಿಗೆ ಟಿಕೆಟ್ ಈಗಾಗಲೇ ಮೊದಲೇ ಆರಿಸಲ್ಪಟ್ಟಿದ್ದರೆ, ಇಡೀ ಬುಕಿಂಗ್ ಫಾರ್ಮ್ ಕಾಣಿಸುತ್ತದೆ.','If enabled, the latest dev version will always be checked instead of the latest stable version of the plugin.'=>'ಸಕ್ರಿಯಗೊಳಿಸಿದರೆ, ಪ್ಲಗಿನ್‌ನ ಇತ್ತೀಚಿನ ಸ್ಥಿರ ಆವೃತ್ತಿಯ ಬದಲು ಯಾವಾಗಲೂ ಇತ್ತೀಚಿನ ಡೆವ್ ಆವೃತ್ತಿಯನ್ನು ಪರಿಶೀಲಿಸಲಾಗುತ್ತದೆ.','If enabled, the spaces a visitor picks on the booking form are held for them while they fill in the rest of the form, so nobody else can take them before they submit. Held spaces count as taken for everyone else until the booking is submitted or the hold runs out. A hold can be no larger than one booking, so set a maximum number of spaces per booking on your events or tickets to limit how much of an event one visitor can hold.'=>'ಸಕ್ರಿಯಗೊಳಿಸಿದರೆ, ಸಂದರ್ಶಕರು ಬುಕಿಂಗ್ ಫಾರ್ಮ್‌ನಲ್ಲಿ ಆರಿಸಿದ ಸ್ಥಾನಗಳನ್ನು ಅವರು ಉಳಿದ ಫಾರ್ಮ್ ಅನ್ನು ಭರ್ತಿ ಮಾಡುವಾಗ ಅವರಿಗಾಗಿ ಹಿಡಿದಿಡಲಾಗುತ್ತದೆ, ಹೀಗಾಗಿ ಅವರು ಸಲ್ಲಿಸುವ ಮೊದಲು ಬೇರೆ ಯಾರೂ ಅವುಗಳನ್ನು ತೆಗೆದುಕೊಳ್ಳಲು ಸಾಧ್ಯವಿಲ್ಲ. ಬುಕಿಂಗ್ ಸಲ್ಲಿಸುವವರೆಗೆ ಅಥವಾ ಹಿಡಿತದ ಸಮಯ ಮುಗಿಯುವವರೆಗೆ, ಹಿಡಿದಿಟ್ಟ ಸ್ಥಾನಗಳನ್ನು ಇತರರಿಗೆ ತೆಗೆದುಕೊಂಡಂತೆ ಎಣಿಸಲಾಗುತ್ತದೆ. ಒಂದು ಹೋಲ್ಡ್ ಒಂದು ಬುಕಿಂಗ್‌ಗಿಂತ ದೊಡ್ಡದಾಗಿರಲು ಸಾಧ್ಯವಿಲ್ಲ, ಆದ್ದರಿಂದ ಒಬ್ಬ ಸಂದರ್ಶಕರು ಈವೆಂಟ್‌ನ ಎಷ್ಟು ಭಾಗವನ್ನು ಹಿಡಿದಿಡಬಹುದು ಎಂಬುದನ್ನು ಮಿತಿಗೊಳಿಸಲು ನಿಮ್ಮ ಈವೆಂಟ್‌ಗಳು ಅಥವಾ ಟಿಕೆಟ್‌ಗಳಲ್ಲಿ ಪ್ರತಿ ಬುಕಿಂಗ್‌ಗೆ ಗರಿಷ್ಠ ಸ್ಥಾನಗಳ ಸಂಖ್ಯೆಯನ್ನು ಹೊಂದಿಸಿ.','If enabled, users can book an event more than once.'=>'ಸಕ್ರಿಯಗೊಳಿಸಿದರೆ, ಬಳಕೆದಾರರು ಒಂದು ಈವೆಂಟ್ ಅನ್ನು ಒಂದಕ್ಕಿಂತ ಹೆಚ್ಚು ಬಾರಿ ಬುಕ್ ಮಾಡಬಹುದು.','If enabled, users can cancel their bookings themselves from their bookings page.'=>'ಸಕ್ರಿಯಗೊಳಿಸಿದರೆ, ಬಳಕೆದಾರರು ತಮ್ಮ ಬುಕಿಂಗ್‌ಗಳ ಪುಟದಿಂದ ತಾವೇ ತಮ್ಮ ಬುಕಿಂಗ್‌ಗಳನ್ನು ರದ್ದುಗೊಳಿಸಬಹುದು.','If guests cannot make bookings, they will be asked to register in order to book. However, enabling this will still show available tickets.'=>'ಅತಿಥಿಗಳು ಬುಕಿಂಗ್ ಮಾಡಲಾಗದಿದ್ದರೆ, ಬುಕ್ ಮಾಡಲು ಅವರನ್ನು ನೋಂದಾಯಿಸಿಕೊಳ್ಳುವಂತೆ ಕೇಳಲಾಗುತ್ತದೆ. ಆದರೆ ಇದನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿದರೆ ಲಭ್ಯವಿರುವ ಟಿಕೆಟ್‌ಗಳನ್ನು ಇನ್ನೂ ತೋರಿಸಲಾಗುತ್ತದೆ.','If inclusion rules are entered above, this setting is ignored.'=>'ಮೇಲೆ ಸೇರ್ಪಡೆ ನಿಯಮಗಳನ್ನು ನಮೂದಿಸಿದ್ದರೆ, ಈ ಸೆಟ್ಟಿಂಗ್ ಅನ್ನು ನಿರ್ಲಕ್ಷಿಸಲಾಗುತ್ತದೆ.','If left blank, no emails will be sent. Separate emails with commas for more than one email.'=>'ಖಾಲಿ ಬಿಟ್ಟರೆ ಯಾವುದೇ ಇಮೇಲ್ ಕಳುಹಿಸಲಾಗುವುದಿಲ್ಲ. ಒಂದಕ್ಕಿಂತ ಹೆಚ್ಚು ಇಮೇಲ್‌ಗಳಿದ್ದರೆ ಅಲ್ಪವಿರಾಮದಿಂದ ಬೇರ್ಪಡಿಸಿ.','If left blank, the default value will be used.'=>'ಖಾಲಿ ಬಿಟ್ಟರೆ, ಡೀಫಾಲ್ಟ್ ಮೌಲ್ಯವನ್ನು ಬಳಸಲಾಗುತ್ತದೆ.','If left blank, this email will not be sent.'=>'ಖಾಲಿ ಬಿಟ್ಟರೆ ಈ ಇಮೇಲ್ ಕಳುಹಿಸಲಾಗುವುದಿಲ್ಲ.','If set to yes the capabilities will be applied all your network blogs and you will not be able to set custom capabilities each blog. You can select no later and visit specific blog settings pages to add/remove capabilities.'=>'ಹೌದು ಎಂದು ಹೊಂದಿಸಿದರೆ ಅರ್ಹತೆಗಳು ನಿಮ್ಮ ನೆಟ್‌ವರ್ಕ್‌ನ ಎಲ್ಲಾ ಬ್ಲಾಗ್‌ಗಳಿಗೆ ಅನ್ವಯವಾಗುತ್ತವೆ ಮತ್ತು ಪ್ರತಿ ಬ್ಲಾಗ್‌ಗೆ ಪ್ರತ್ಯೇಕ ಅರ್ಹತೆಗಳನ್ನು ಹೊಂದಿಸಲು ಸಾಧ್ಯವಾಗುವುದಿಲ್ಲ. ನೀವು ನಂತರ ಇಲ್ಲ ಎಂದು ಆರಿಸಿ, ನಿರ್ದಿಷ್ಟ ಬ್ಲಾಗ್‌ನ ಸೆಟ್ಟಿಂಗ್‌ಗಳ ಪುಟಗಳಿಗೆ ಭೇಟಿ ನೀಡಿ ಅರ್ಹತೆಗಳನ್ನು ಸೇರಿಸಬಹುದು/ತೆಗೆಯಬಹುದು.','If set to yes, a search form will appear just above your list of events.'=>'ಹೌದು ಎಂದು ಹೊಂದಿಸಿದರೆ, ನಿಮ್ಮ ಈವೆಂಟ್‌ಗಳ ಪಟ್ಟಿಯ ಮೇಲ್ಭಾಗದಲ್ಲಿ ಹುಡುಕಾಟ ಫಾರ್ಮ್ ಕಾಣಿಸುತ್ತದೆ.','If set to yes, a search form will appear just above your list of locations.'=>'ಹೌದು ಎಂದು ಹೊಂದಿಸಿದರೆ, ನಿಮ್ಮ ಸ್ಥಳಗಳ ಪಟ್ಟಿಯ ಮೇಲ್ಭಾಗದಲ್ಲಿ ಹುಡುಕಾಟ ಫಾರ್ಮ್ ಕಾಣಿಸುತ್ತದೆ.','If set to yes, advanced search fields can toggled by clicking the "Advanced Search" icon.'=>'ಹೌದು ಎಂದು ಹೊಂದಿಸಿದರೆ, "Advanced Search" ಐಕಾನ್ ಕ್ಲಿಕ್ ಮಾಡುವ ಮೂಲಕ ಸುಧಾರಿತ ಹುಡುಕಾಟ ಕ್ಷೇತ್ರಗಳನ್ನು ಟಾಗಲ್ ಮಾಡಬಹುದು.','If set to yes, advanced search fields will be hidden by default and can be revealed by clicking the "Advanced Search" icon.'=>'ಹೌದು ಎಂದು ಹೊಂದಿಸಿದರೆ, ಸುಧಾರಿತ ಹುಡುಕಾಟ ಕ್ಷೇತ್ರಗಳು ಡೀಫಾಲ್ಟ್ ಆಗಿ ಮರೆಯಾಗಿರುತ್ತವೆ ಮತ್ತು "Advanced Search" ಐಕಾನ್ ಕ್ಲಿಕ್ ಮಾಡುವ ಮೂಲಕ ತೋರಿಸಬಹುದು.','If set to yes, full sized images will be used and HTML width and height attributes will be used to determine the size.'=>'ಹೌದು ಎಂದು ಹೊಂದಿಸಿದರೆ, ಪೂರ್ಣ ಗಾತ್ರದ ಚಿತ್ರಗಳನ್ನು ಬಳಸಲಾಗುತ್ತದೆ ಮತ್ತು ಗಾತ್ರವನ್ನು ನಿರ್ಧರಿಸಲು HTML ಅಗಲ ಮತ್ತು ಎತ್ತರದ ಗುಣಲಕ್ಷಣಗಳನ್ನು ಬಳಸಲಾಗುತ್ತದೆ.','If set to yes, the FullCalendar will be used instead of the standard calendar on the events page.'=>'ಹೌದು ಎಂದು ಹೊಂದಿಸಿದರೆ, ಈವೆಂಟ್‌ಗಳ ಪುಟದಲ್ಲಿ ಪ್ರಮಾಣಿತ ಕ್ಯಾಲೆಂಡರ್ ಬದಲು FullCalendar ಬಳಸಲಾಗುತ್ತದೆ.','If set to yes, your emails will be sent in HTML format, otherwise plaintext.'=>'ಹೌದು ಎಂದು ಹೊಂದಿಸಿದರೆ, ನಿಮ್ಮ ಇಮೇಲ್‌ಗಳನ್ನು HTML ಸ್ವರೂಪದಲ್ಲಿ ಕಳುಹಿಸಲಾಗುತ್ತದೆ, ಇಲ್ಲದಿದ್ದರೆ ಸರಳ ಪಠ್ಯದಲ್ಲಿ.','If set, the total number of spaces for a single booking to this event cannot exceed this amount.'=>'ಹೊಂದಿಸಿದರೆ, ಈ ಈವೆಂಟ್‌ಗೆ ಒಂದು ಬುಕಿಂಗ್‌ನ ಒಟ್ಟು ಸ್ಥಾನಗಳ ಸಂಖ್ಯೆ ಈ ಮೊತ್ತವನ್ನು ಮೀರಬಾರದು.','If syncing is turned on for a booking status below, when a user RSVPs, the booking status will automatically be changed along with RSVP status.'=>'ಕೆಳಗಿನ ಬುಕಿಂಗ್ ಸ್ಥಿತಿಗೆ ಸಿಂಕ್ ಮಾಡುವಿಕೆಯನ್ನು ಆನ್ ಮಾಡಿದ್ದರೆ, ಬಳಕೆದಾರರು RSVP ಮಾಡಿದಾಗ, RSVP ಸ್ಥಿತಿಯೊಂದಿಗೆ ಬುಕಿಂಗ್ ಸ್ಥಿತಿಯೂ ತಾನಾಗಿ ಬದಲಾಗುತ್ತದೆ.','If the booking is free, this will be displayed instead of the %s heading.'=>'ಬುಕಿಂಗ್ ಉಚಿತವಾಗಿದ್ದರೆ, %s ಶಿರೋನಾಮೆಯ ಬದಲಿಗೆ ಇದನ್ನು ಪ್ರದರ್ಶಿಸಲಾಗುತ್ತದೆ.','If the consent checkbox is not checked during a booking, this error will be returned.'=>'ಬುಕಿಂಗ್ ಮಾಡುವಾಗ ಒಪ್ಪಿಗೆ ಚೆಕ್‌ಬಾಕ್ಸ್ ಅನ್ನು ಗುರುತಿಸದಿದ್ದರೆ, ಈ ದೋಷವನ್ನು ಹಿಂತಿರುಗಿಸಲಾಗುತ್ತದೆ.','If the consent checkbox is not checked when submitting information such as events or locations, this error will be returned.'=>'ಈವೆಂಟ್‌ಗಳು ಅಥವಾ ಸ್ಥಳಗಳಂತಹ ಮಾಹಿತಿಯನ್ನು ಸಲ್ಲಿಸುವಾಗ ಒಪ್ಪಿಗೆ ಚೆಕ್‌ಬಾಕ್ಸ್ ಅನ್ನು ಗುರುತಿಸದಿದ್ದರೆ, ಈ ದೋಷವನ್ನು ಹಿಂತಿರುಗಿಸಲಾಗುತ್ತದೆ.','If the user made a previous booking and cannot double-book.'=>'ಬಳಕೆದಾರರು ಈ ಹಿಂದೆ ಬುಕಿಂಗ್ ಮಾಡಿದ್ದು, ದ್ವಿಗುಣ ಬುಕ್ ಮಾಡಲಾಗದಿದ್ದರೆ.','If the user tries to make a booking with spaces that exceeds the maximum number of spaces per booking.'=>'ಬಳಕೆದಾರರು ಪ್ರತಿ ಬುಕಿಂಗ್‌ಗೆ ಗರಿಷ್ಠ ಸ್ಥಾನಗಳ ಸಂಖ್ಯೆಯನ್ನು ಮೀರುವ ಸ್ಥಾನಗಳೊಂದಿಗೆ ಬುಕಿಂಗ್ ಮಾಡಲು ಪ್ರಯತ್ನಿಸಿದರೆ.','If the user tries to make a booking without requesting any spaces.'=>'ಬಳಕೆದಾರರು ಯಾವುದೇ ಸ್ಥಾನಗಳನ್ನು ಕೋರದೆ ಬುಕಿಂಗ್ ಮಾಡಲು ಪ್ರಯತ್ನಿಸಿದರೆ.','If there are any new updates, you should now see them in your Plugins or Updates admin pages.'=>'ಯಾವುದೇ ಹೊಸ ಅಪ್‌ಡೇಟ್‌ಗಳಿದ್ದರೆ, ಅವುಗಳು ಈಗ ನಿಮ್ಮ ಪ್ಲಗಿನ್‌ಗಳು ಅಥವಾ ಅಪ್‌ಡೇಟ್‌ಗಳ ನಿರ್ವಾಹಕ ಪುಟಗಳಲ್ಲಿ ಕಾಣಿಸಬೇಕು.','If there are member-only tickets, you can choose whether or not to show these tickets to guests.'=>'ಸದಸ್ಯರಿಗೆ ಮಾತ್ರವಿರುವ ಟಿಕೆಟ್‌ಗಳಿದ್ದರೆ, ಈ ಟಿಕೆಟ್‌ಗಳನ್ನು ಅತಿಥಿಗಳಿಗೆ ತೋರಿಸಬೇಕೇ ಬೇಡವೇ ಎಂದು ನೀವು ಆರಿಸಬಹುದು.','If there\'s no fields to show in the main search section, this button will be used instead at the bottom of the advanced fields.'=>'ಮುಖ್ಯ ಹುಡುಕಾಟ ವಿಭಾಗದಲ್ಲಿ ತೋರಿಸಲು ಯಾವುದೇ ಕ್ಷೇತ್ರಗಳಿಲ್ಲದಿದ್ದರೆ, ಬದಲಿಗೆ ಈ ಗುಂಡಿಯನ್ನು ಸುಧಾರಿತ ಕ್ಷೇತ್ರಗಳ ಕೆಳಗೆ ಬಳಸಲಾಗುತ್ತದೆ.','If this is incorrect, click cancel and try a more specific address.'=>'ಇದು ತಪ್ಪಾಗಿದ್ದರೆ, ರದ್ದು ಕ್ಲಿಕ್ ಮಾಡಿ ಮತ್ತು ಹೆಚ್ಚು ನಿರ್ದಿಷ್ಟ ವಿಳಾಸವನ್ನು ಪ್ರಯತ್ನಿಸಿ.','If translations are left blank, the default value will be used.'=>'ಭಾಷಾಂತರಗಳನ್ನು ಖಾಲಿ ಬಿಟ್ಟರೆ, ಡೀಫಾಲ್ಟ್ ಮೌಲ್ಯವನ್ನು ಬಳಸಲಾಗುತ್ತದೆ.','If viewing a page for events on a specific date, this is the title that would show up. To insert date values, use <a href="http://www.php.net/manual/en/function.date.php">PHP time format characters</a>  with a <code>#</code> symbol before them, i.e. <code>#m</code>, <code>#M</code>, <code>#j</code>, etc.<br/>'=>'ನಿರ್ದಿಷ್ಟ ದಿನಾಂಕದ ಈವೆಂಟ್‌ಗಳ ಪುಟವನ್ನು ವೀಕ್ಷಿಸುವಾಗ ಕಾಣಿಸುವ ಶೀರ್ಷಿಕೆ ಇದು. ದಿನಾಂಕ ಮೌಲ್ಯಗಳನ್ನು ಸೇರಿಸಲು, ಮುಂದೆ <code>#</code> ಚಿಹ್ನೆಯೊಂದಿಗೆ <a href="http://www.php.net/manual/en/function.date.php">PHP ಸಮಯ ನಮೂನೆ ಅಕ್ಷರಗಳನ್ನು</a> ಬಳಸಿ, ಉದಾ. <code>#m</code>, <code>#M</code>, <code>#j</code>, ಇತ್ಯಾದಿ.<br/>','If you are experiencing errors when trying to use any of these accounts, try disconnecting and connecting again.'=>'ಈ ಯಾವುದೇ ಖಾತೆಗಳನ್ನು ಬಳಸಲು ಪ್ರಯತ್ನಿಸುವಾಗ ದೋಷಗಳು ಕಂಡುಬಂದರೆ, ಸಂಪರ್ಕ ಕಡಿತಗೊಳಿಸಿ ಮತ್ತೆ ಸಂಪರ್ಕಿಸಲು ಪ್ರಯತ್ನಿಸಿ.','If you change time patterns such as start times or durations, any previously created timeslots falling outside the new settings will be %s.'=>'ಪ್ರಾರಂಭ ಸಮಯ ಅಥವಾ ಅವಧಿಯಂತಹ ಸಮಯ ಮಾದರಿಗಳನ್ನು ನೀವು ಬದಲಿಸಿದರೆ, ಹೊಸ ಸೆಟ್ಟಿಂಗ್‌ಗಳ ಹೊರಗೆ ಬೀಳುವ ಹಿಂದೆ ರಚಿಸಿದ ಯಾವುದೇ ಸಮಯಾವಕಾಶಗಳನ್ನು %s.','If you choose \'Pages\' then %s will be shown using your theme default page template, alternatively choose from page templates that come with your specific theme.'=>'ನೀವು \'ಪುಟಗಳು\' ಆರಿಸಿದರೆ %s ಅನ್ನು ನಿಮ್ಮ ಥೀಮ್‌ನ ಡೀಫಾಲ್ಟ್ ಪುಟ ಟೆಂಪ್ಲೇಟ್ ಬಳಸಿ ತೋರಿಸಲಾಗುತ್ತದೆ, ಇಲ್ಲವಾದರೆ ನಿಮ್ಮ ನಿರ್ದಿಷ್ಟ ಥೀಮ್‌ನೊಂದಿಗೆ ಬರುವ ಪುಟ ಟೆಂಪ್ಲೇಟ್‌ಗಳಿಂದ ಆರಿಸಿ.','If you choose a group by mode, your events page will display events in groups of your chosen time range.'=>'ನೀವು ಗುಂಪು ಮಾಡುವ ಮೋಡ್ ಆರಿಸಿದರೆ, ನಿಮ್ಮ ಈವೆಂಟ್‌ಗಳ ಪುಟವು ನೀವು ಆರಿಸಿದ ಸಮಯದ ವ್ಯಾಪ್ತಿಯ ಗುಂಪುಗಳಲ್ಲಿ ಈವೆಂಟ್‌ಗಳನ್ನು ತೋರಿಸುತ್ತದೆ.','If you choose the Event post type whilst Events Manager is activated, you can also visit the <a href="%s">Events Manager settings page</a> for a few more options when displaying event information on your calendar.'=>'Events Manager ಸಕ್ರಿಯವಾಗಿರುವಾಗ ನೀವು ಈವೆಂಟ್ ಪೋಸ್ಟ್ ಪ್ರಕಾರವನ್ನು ಆರಿಸಿದರೆ, ನಿಮ್ಮ ಕ್ಯಾಲೆಂಡರ್‌ನಲ್ಲಿ ಈವೆಂಟ್ ಮಾಹಿತಿಯನ್ನು ತೋರಿಸುವಾಗ ಇನ್ನಷ್ಟು ಆಯ್ಕೆಗಳಿಗಾಗಿ <a href="%s">Events Manager ಸೆಟ್ಟಿಂಗ್‌ಗಳ ಪುಟಕ್ಕೂ</a> ಭೇಟಿ ನೀಡಬಹುದು.','If you choose to cancel your event, after you save this event, no further bookings will be possible for this event.'=>'ನಿಮ್ಮ ಈವೆಂಟ್ ಅನ್ನು ರದ್ದುಗೊಳಿಸಲು ನೀವು ಆಯ್ಕೆ ಮಾಡಿದರೆ, ಈ ಈವೆಂಟ್ ಅನ್ನು ಉಳಿಸಿದ ನಂತರ ಈ ಈವೆಂಟ್‌ಗೆ ಹೆಚ್ಚಿನ ಬುಕಿಂಗ್‌ಗಳು ಸಾಧ್ಯವಾಗುವುದಿಲ್ಲ.','If you collect personal data, you may want to request their consent. The options below will automatically add checkboxes requesting this consent.'=>'ನೀವು ವೈಯಕ್ತಿಕ ಡೇಟಾವನ್ನು ಸಂಗ್ರಹಿಸಿದರೆ, ಅವರ ಒಪ್ಪಿಗೆಯನ್ನು ಕೇಳಲು ನೀವು ಬಯಸಬಹುದು. ಕೆಳಗಿನ ಆಯ್ಕೆಗಳು ಈ ಒಪ್ಪಿಗೆಯನ್ನು ಕೇಳುವ ಚೆಕ್‌ಬಾಕ್ಸ್‌ಗಳನ್ನು ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಸೇರಿಸುತ್ತವೆ.','If you could spare a few minutes, we would appreciate it if you could please leave us a review.'=>'ನೀವು ಕೆಲವು ನಿಮಿಷಗಳನ್ನು ಮೀಸಲಿಡಬಹುದಾದರೆ, ದಯವಿಟ್ಟು ನಮಗೆ ವಿಮರ್ಶೆ ನೀಡಿದರೆ ನಾವು ಕೃತಜ್ಞರಾಗಿರುತ್ತೇವೆ.','If you disable locations, bear in mind that you should remove your location page, shortcodes and related placeholders from your <a href="#formats" class="nav-tab-link" rel="#em-menu-formats">formats</a>.'=>'ನೀವು ಸ್ಥಳಗಳನ್ನು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಿದರೆ, ನಿಮ್ಮ <a href="#formats" class="nav-tab-link" rel="#em-menu-formats">ಸ್ವರೂಪಗಳಿಂದ</a> ನಿಮ್ಮ ಸ್ಥಳ ಪುಟ, ಶಾರ್ಟ್‌ಕೋಡ್‌ಗಳು ಮತ್ತು ಸಂಬಂಧಿತ ಪ್ಲೇಸ್‌ಹೋಲ್ಡರ್‌ಗಳನ್ನು ತೆಗೆದುಹಾಕಬೇಕು ಎಂಬುದನ್ನು ನೆನಪಿಡಿ.','If you enable tips, this information will be shown, which can include HTML.'=>'ನೀವು ಟಿಪ್ಸ್ ಅನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿದರೆ, ಈ ಮಾಹಿತಿಯನ್ನು ತೋರಿಸಲಾಗುತ್ತದೆ, ಇದರಲ್ಲಿ HTML ಸೇರಿರಬಹುದು.','If you extend or add more dates, the new recurrences will be added to your recurrence set without affecting previously created ones.'=>'ನೀವು ವ್ಯಾಪ್ತಿಯನ್ನು ವಿಸ್ತರಿಸಿದರೆ ಅಥವಾ ಹೆಚ್ಚಿನ ದಿನಾಂಕಗಳನ್ನು ಸೇರಿಸಿದರೆ, ಹಿಂದೆ ರಚಿಸಿದವುಗಳ ಮೇಲೆ ಪರಿಣಾಮ ಬೀರದಂತೆ ಹೊಸ ಪುನರಾವರ್ತನೆಗಳು ನಿಮ್ಮ ಪುನರಾವರ್ತನೆ ಸೆಟ್‌ಗೆ ಸೇರಿಸಲ್ಪಡುತ್ತವೆ.','If you extend or add more times, this will not affect previous timeslots.'=>'ನೀವು ಸಮಯಗಳನ್ನು ವಿಸ್ತರಿಸಿದರೆ ಅಥವಾ ಹೆಚ್ಚು ಸೇರಿಸಿದರೆ, ಅದು ಹಿಂದಿನ ಸಮಯಾವಕಾಶಗಳ ಮೇಲೆ ಪರಿಣಾಮ ಬೀರುವುದಿಲ್ಲ.','If you get a lot of pending bookings and you decide to allow more bookings than spaces allow, setting this to yes will allow you to override the event space limit when manually approving.'=>'ನಿಮಗೆ ಬಹಳಷ್ಟು ಬಾಕಿಯಿರುವ ಬುಕಿಂಗ್‌ಗಳು ಬಂದು, ಸ್ಥಾನಗಳು ಅನುಮತಿಸುವುದಕ್ಕಿಂತ ಹೆಚ್ಚು ಬುಕಿಂಗ್‌ಗಳಿಗೆ ಅನುಮತಿಸಲು ನೀವು ನಿರ್ಧರಿಸಿದರೆ, ಇದನ್ನು ಹೌದು ಎಂದು ಹೊಂದಿಸುವುದರಿಂದ ಕೈಯಾರೆ ಅನುಮೋದಿಸುವಾಗ ಈವೆಂಟ್ ಸ್ಥಾನ ಮಿತಿಯನ್ನು ಮೀರಲು ಸಾಧ್ಯವಾಗುತ್ತದೆ.','If you hare happy with the migration, you can dismiss this message and your old formatting options (i.e. this undo option) will be deleted.'=>'ವಲಸೆಯಿಂದ ನಿಮಗೆ ಸಂತೋಷವಾಗಿದ್ದರೆ, ನೀವು ಈ ಸಂದೇಶವನ್ನು ವಜಾಮಾಡಬಹುದು, ಆಗ ನಿಮ್ಮ ಹಳೆಯ ಫಾರ್ಮ್ಯಾಟಿಂಗ್ ಆಯ್ಕೆಗಳು (ಅಂದರೆ ಈ ರದ್ದುಮಾಡುವ ಆಯ್ಕೆ) ಅಳಿಸಲ್ಪಡುತ್ತವೆ.','If you just want to deactivate the plugin, <a href="%s">go to your plugins page</a>.'=>'ನೀವು ಪ್ಲಗಿನ್ ಅನ್ನು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಲು ಮಾತ್ರ ಬಯಸಿದರೆ, <a href="%s">ನಿಮ್ಮ ಪ್ಲಗಿನ್‌ಗಳ ಪುಟಕ್ಕೆ ಹೋಗಿ</a>.','If you modify the dates where recurrences will not occur on, any recurrences falling within these dates will be %s. New recurrences will be created if you remove unavailable dates which previously blocked recurrnce dates.'=>'ಪುನರಾವರ್ತನೆಗಳು ನಡೆಯದ ದಿನಾಂಕಗಳನ್ನು ನೀವು ಮಾರ್ಪಡಿಸಿದರೆ, ಈ ದಿನಾಂಕಗಳೊಳಗೆ ಬರುವ ಯಾವುದೇ ಪುನರಾವರ್ತನೆಗಳನ್ನು %s. ಹಿಂದೆ ಪುನರಾವರ್ತನೆ ದಿನಾಂಕಗಳನ್ನು ತಡೆದಿದ್ದ ಲಭ್ಯವಿಲ್ಲದ ದಿನಾಂಕಗಳನ್ನು ನೀವು ತೆಗೆದರೆ ಹೊಸ ಪುನರಾವರ್ತನೆಗಳನ್ನು ರಚಿಸಲಾಗುತ್ತದೆ.','If you prefer a ticket table like with multiple tickets, even for single ticket events, enable this.'=>'ಏಕ ಟಿಕೆಟ್ ಈವೆಂಟ್‌ಗಳಿಗೂ ಬಹು ಟಿಕೆಟ್‌ಗಳಂತೆ ಟಿಕೆಟ್ ಕೋಷ್ಟಕ ಬೇಕಿದ್ದರೆ, ಇದನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ.','If you select a default country, that will be pre-selected when creating a new location.'=>'ನೀವು ಡೀಫಾಲ್ಟ್ ರಾಷ್ಟ್ರವನ್ನು ಆರಿಸಿದರೆ, ಹೊಸ ಸ್ಥಳವನ್ನು ರಚಿಸುವಾಗ ಅದು ಮೊದಲೇ ಆಯ್ಕೆಯಾಗಿರುತ್ತದೆ.','If you shorten the date range or limit your recurrence dates, any recurrences falling outside the new date range will be %s.'=>'ನೀವು ದಿನಾಂಕ ವ್ಯಾಪ್ತಿಯನ್ನು ಕಡಿಮೆ ಮಾಡಿದರೆ ಅಥವಾ ಪುನರಾವರ್ತನೆ ದಿನಾಂಕಗಳನ್ನು ಸೀಮಿತಗೊಳಿಸಿದರೆ, ಹೊಸ ದಿನಾಂಕ ವ್ಯಾಪ್ತಿಯ ಹೊರಗೆ ಬೀಳುವ ಯಾವುದೇ ಪುನರಾವರ್ತನೆಗಳನ್ನು %s.','If you update this event data and save, it could get overwritten if you edit the repeating event template. To make it an independent, <a href="%s">detach it</a>.'=>'ನೀವು ಈ ಈವೆಂಟ್ ಡೇಟಾವನ್ನು ಬದಲಾಯಿಸಿ ಉಳಿಸಿದರೆ, ಪುನರಾವರ್ತಿತ ಈವೆಂಟ್ ಟೆಂಪ್ಲೇಟ್ ಅನ್ನು ಸಂಪಾದಿಸಿದಾಗ ಅದು ಮೇಲ್ಬರಹವಾಗಬಹುದು. ಇದನ್ನು ಸ್ವತಂತ್ರವಾಗಿಸಲು, <a href="%s">ಬೇರ್ಪಡಿಸಿ</a>.','If you use the %s <a href="%s">shortcode</a>, you can display a map of all your locations and events, the settings below will be used.'=>'ನೀವು %s <a href="%s">ಶಾರ್ಟ್‌ಕೋಡ್</a> ಬಳಸಿದರೆ, ನಿಮ್ಮ ಎಲ್ಲಾ ಸ್ಥಳಗಳು ಮತ್ತು ಈವೆಂಟ್‌ಗಳ ನಕ್ಷೆಯನ್ನು ಪ್ರದರ್ಶಿಸಬಹುದು, ಕೆಳಗಿನ ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಬಳಸಲಾಗುತ್ತದೆ.','If you use the <code>#_LOCATIONMAP</code> <a href="%s">placeholder</a> when displaying individual event and location information, the settings below will be used.'=>'ಪ್ರತ್ಯೇಕ ಈವೆಂಟ್ ಮತ್ತು ಸ್ಥಳದ ಮಾಹಿತಿಯನ್ನು ಪ್ರದರ್ಶಿಸುವಾಗ ನೀವು <code>#_LOCATIONMAP</code> <a href="%s">ಪ್ಲೇಸ್‌ಹೋಲ್ಡರ್</a> ಬಳಸಿದರೆ, ಕೆಳಗಿನ ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಬಳಸಲಾಗುತ್ತದೆ.','If you want to edit general options for Events Manager, visit the main %s.'=>'Events Manager ನ ಸಾಮಾನ್ಯ ಆಯ್ಕೆಗಳನ್ನು ಸಂಪಾದಿಸಲು ಬಯಸಿದರೆ, ಮುಖ್ಯ %s ಗೆ ಭೇಟಿ ನೀಡಿ.','If you would like every event booking confirmation email sent to an administrator write their email here (leave blank to not send an email).'=>'ಪ್ರತಿ ಈವೆಂಟ್ ಬುಕಿಂಗ್ ದೃಢೀಕರಣ ಇಮೇಲ್ ಅನ್ನು ನಿರ್ವಾಹಕರಿಗೆ ಕಳುಹಿಸಬೇಕೆಂದಿದ್ದರೆ ಅವರ ಇಮೇಲ್ ಅನ್ನು ಇಲ್ಲಿ ಬರೆಯಿರಿ (ಇಮೇಲ್ ಕಳುಹಿಸಬಾರದೆಂದಿದ್ದರೆ ಖಾಲಿ ಬಿಡಿ).','If you would like to add extra classes to your body html tag when a single %s page is displayed, enter it here. May be useful or necessary if your theme requires special class names for specific templates.'=>'ಒಂದು %s ಪುಟವನ್ನು ಪ್ರದರ್ಶಿಸುವಾಗ ನಿಮ್ಮ body html ಟ್ಯಾಗ್‌ಗೆ ಹೆಚ್ಚುವರಿ ಕ್ಲಾಸ್‌ಗಳನ್ನು ಸೇರಿಸಲು ಬಯಸಿದರೆ, ಇಲ್ಲಿ ನಮೂದಿಸಿ. ನಿಮ್ಮ ಥೀಮ್‌ಗೆ ನಿರ್ದಿಷ್ಟ ಟೆಂಪ್ಲೇಟ್‌ಗಳಿಗಾಗಿ ವಿಶೇಷ ಕ್ಲಾಸ್ ಹೆಸರುಗಳು ಬೇಕಾದರೆ ಇದು ಉಪಯುಕ್ತ ಅಥವಾ ಅಗತ್ಯವಾಗಿರಬಹುದು.','If you would like to disable comments entirely, disable this, otherwise you can disable comments on each single %s. Note that %s with comments enabled will still be until you resave them.'=>'ನೀವು ಕಾಮೆಂಟ್‌ಗಳನ್ನು ಸಂಪೂರ್ಣವಾಗಿ ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಲು ಬಯಸಿದರೆ ಇದನ್ನು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಿ, ಇಲ್ಲವಾದರೆ ಪ್ರತಿ %s ನಲ್ಲಿ ಕಾಮೆಂಟ್‌ಗಳನ್ನು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಬಹುದು. ಕಾಮೆಂಟ್‌ಗಳು ಸಕ್ರಿಯವಾಗಿರುವ %s ಅನ್ನು ನೀವು ಮರುಉಳಿಸುವವರೆಗೆ ಹಾಗೆಯೇ ಇರುತ್ತವೆ ಎಂಬುದನ್ನು ಗಮನಿಸಿ.','If you would like to download a dev version, but just as a one-off, you can force a dev version check by clicking the button below. If there is one available, it should appear in your plugin updates page as a regular update.'=>'ನೀವು ಒಮ್ಮೆ ಮಾತ್ರ ಡೆವ್ ಆವೃತ್ತಿಯನ್ನು ಡೌನ್ಲೋಡ್ ಮಾಡಲು ಬಯಸಿದರೆ, ಕೆಳಗಿನ ಗುಂಡಿಯನ್ನು ಕ್ಲಿಕ್ ಮಾಡಿ ಡೆವ್ ಆವೃತ್ತಿಯ ಪರಿಶೀಲನೆಯನ್ನು ಒತ್ತಾಯಿಸಬಹುದು. ಒಂದು ಲಭ್ಯವಿದ್ದರೆ, ಅದು ನಿಮ್ಮ ಪ್ಲಗಿನ್ ಅಪ್‌ಡೇಟ್‌ಗಳ ಪುಟದಲ್ಲಿ ಸಾಮಾನ್ಯ ಅಪ್‌ಡೇಟ್‌ನಂತೆ ಕಾಣಿಸಬೇಕು.','If you would prefer all your locations to belong to your main blog, users in sub-sites will still be able to create locations, but the actual locations are created and reside in the main blog.'=>'ನಿಮ್ಮ ಎಲ್ಲಾ ಸ್ಥಳಗಳು ಮುಖ್ಯ ಬ್ಲಾಗ್‌ಗೆ ಸೇರಿರಬೇಕೆಂದು ಬಯಸಿದರೆ, ಉಪ-ಸೈಟ್‌ಗಳ ಬಳಕೆದಾರರು ಇನ್ನೂ ಸ್ಥಳಗಳನ್ನು ರಚಿಸಬಹುದು, ಆದರೆ ನಿಜವಾದ ಸ್ಥಳಗಳನ್ನು ಮುಖ್ಯ ಬ್ಲಾಗ್‌ನಲ್ಲಿ ರಚಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ಅಲ್ಲೇ ಇರುತ್ತವೆ.','If you would prefer to hide this page, add %s to your wp-config.php file.'=>'ನೀವು ಈ ಪುಟವನ್ನು ಮರೆಮಾಡಲು ಬಯಸಿದರೆ, ನಿಮ್ಮ wp-config.php ಫೈಲ್‌ಗೆ %s ಸೇರಿಸಿ.','If you\'re using the Google Maps, the more detail you provide, the more accurate Google can be at finding your location. If your address isn\'t being found, please <a href=\'http://maps.google.com\'>try it on maps.google.com</a> by adding all the fields below separated by commas.'=>'ನೀವು Google ನಕ್ಷೆಗಳನ್ನು ಬಳಸುತ್ತಿದ್ದರೆ, ನೀವು ಹೆಚ್ಚು ವಿವರ ನೀಡಿದಷ್ಟೂ Google ನಿಮ್ಮ ಸ್ಥಳವನ್ನು ಹೆಚ್ಚು ನಿಖರವಾಗಿ ಹುಡುಕಬಲ್ಲದು. ನಿಮ್ಮ ವಿಳಾಸ ಸಿಗದಿದ್ದರೆ, ದಯವಿಟ್ಟು ಕೆಳಗಿನ ಎಲ್ಲಾ ಕ್ಷೇತ್ರಗಳನ್ನು ಅಲ್ಪವಿರಾಮಗಳಿಂದ ಬೇರ್ಪಡಿಸಿ ಸೇರಿಸಿ <a href=\'http://maps.google.com\'>maps.google.com ನಲ್ಲಿ ಪ್ರಯತ್ನಿಸಿ</a>.','Image'=>'ಚಿತ್ರ','Image Dimensions'=>'ಚಿತ್ರದ ಅಳತೆಗಳು','Image input must be an attachment ID, URL, or object with source_url / content_base64 / file.'=>'ಚಿತ್ರದ ಇನ್‌ಪುಟ್ ಲಗತ್ತು ID, URL, ಅಥವಾ source_url / content_base64 / file ಇರುವ ಆಬ್ಜೆಕ್ಟ್ ಆಗಿರಬೇಕು.','Import'=>'ಆಮದು','Import %1$s, %2$s'=>'%1$s, %2$s ಆಮದು ಮಾಡಿ','Import Settings'=>'ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಆಮದು ಮಾಡಿ','Import a %s'=>'%s ಆಮದು ಮಾಡಿ','Import and Migrate'=>'ಆಮದು ಮತ್ತು ವರ್ಗಾವಣೆ','Import as'=>'ಹೀಗೆ ಆಮದು ಮಾಡಿ','Import as a list of dates'=>'ದಿನಾಂಕಗಳ ಪಟ್ಟಿಯಾಗಿ ಆಮದು ಮಾಡಿ','Import events, locations or organizers from a CSV file, or copy your events, venues, organizers, tickets and attendees from another events plugin. Either can be rolled back, and the original data is left untouched.'=>'CSV ಫೈಲ್‌ನಿಂದ ಈವೆಂಟ್‌ಗಳು, ಸ್ಥಳಗಳು ಅಥವಾ ಆಯೋಜಕರನ್ನು ಆಮದು ಮಾಡಿ, ಅಥವಾ ನಿಮ್ಮ ಈವೆಂಟ್‌ಗಳು, ಸ್ಥಳಗಳು, ಆಯೋಜಕರು, ಟಿಕೆಟ್‌ಗಳು ಮತ್ತು ಹಾಜರಾತಿದಾರರನ್ನು ಇನ್ನೊಂದು ಈವೆಂಟ್ಸ್ ಪ್ಲಗಿನ್‌ನಿಂದ ನಕಲಿಸಿ. ಎರಡನ್ನೂ ಹಿಂದಕ್ಕೆ ಸರಿಸಬಹುದು, ಮತ್ತು ಮೂಲ ಡೇಟಾವನ್ನು ಮುಟ್ಟಲಾಗುವುದಿಲ್ಲ.','Import into Events Manager'=>'Events Manager ಗೆ ಆಮದು ಮಾಡಿ','Import/Export Settings'=>'ಸೆಟ್ಟಿಂಗ್‌ಗಳ ಆಮದು/ರಫ್ತು','Imported, with a note'=>'ಆಮದು ಮಾಡಲಾಗಿದೆ, ಟಿಪ್ಪಣಿಯೊಂದಿಗೆ','Importing rows'=>'ಸಾಲುಗಳನ್ನು ಆಮದು ಮಾಡಲಾಗುತ್ತಿದೆ','Imports'=>'ಆಮದುಗಳು','Imports events, locations or organizers from a CSV file, one row for each. A repeating event is one row too. Run it, check the result, and roll the import back if it is not what you wanted.'=>'CSV ಫೈಲ್‌ನಿಂದ ಈವೆಂಟ್‌ಗಳು, ಸ್ಥಳಗಳು ಅಥವಾ ಆಯೋಜಕರನ್ನು ಆಮದು ಮಾಡುತ್ತದೆ, ಪ್ರತಿಯೊಂದಕ್ಕೂ ಒಂದು ಸಾಲು. ಪುನರಾವರ್ತಿತ ಈವೆಂಟ್ ಕೂಡ ಒಂದು ಸಾಲು. ಇದನ್ನು ಚಲಾಯಿಸಿ, ಫಲಿತಾಂಶವನ್ನು ಪರಿಶೀಲಿಸಿ, ನೀವು ಬಯಸಿದ್ದು ಅದಲ್ಲದಿದ್ದರೆ ಆಮದನ್ನು ಹಿಂದಕ್ಕೆ ಸರಿಸಿ.','In order to use attributes, you must define some in your templates, otherwise they\'ll never show. Go to Events > Settings > General to add attribute placeholders.'=>'ಗುಣಲಕ್ಷಣಗಳನ್ನು ಬಳಸಲು, ನಿಮ್ಮ ಟೆಂಪ್ಲೇಟ್‌ಗಳಲ್ಲಿ ಕೆಲವನ್ನು ನೀವು ವ್ಯಾಖ್ಯಾನಿಸಬೇಕು, ಇಲ್ಲದಿದ್ದರೆ ಅವು ಎಂದಿಗೂ ತೋರಿಸುವುದಿಲ್ಲ. ಗುಣಲಕ್ಷಣ ಪ್ಲೇಸ್‌ಹೋಲ್ಡರ್‌ಗಳನ್ನು ಸೇರಿಸಲು Events > Settings > General ಗೆ ಹೋಗಿ.','In single ticket mode, users can only create one ticket per event (and will not see options to add more tickets).'=>'ಏಕ ಟಿಕೆಟ್ ಮೋಡ್‌ನಲ್ಲಿ, ಬಳಕೆದಾರರು ಪ್ರತಿ ಈವೆಂಟ್‌ಗೆ ಒಂದೇ ಟಿಕೆಟ್ ರಚಿಸಬಹುದು (ಮತ್ತು ಹೆಚ್ಚಿನ ಟಿಕೆಟ್‌ಗಳನ್ನು ಸೇರಿಸುವ ಆಯ್ಕೆಗಳು ಕಾಣಿಸುವುದಿಲ್ಲ).','In the <a href=\'%s\'>settings page</a>, you\'ll find various textboxes where you can edit how event information looks, such as for event and location lists. Using the placeholders below, you can choose what information should be displayed.'=>'<a href=\'%s\'>ಸೆಟ್ಟಿಂಗ್‌ಗಳ ಪುಟ</a>ದಲ್ಲಿ, ಈವೆಂಟ್ ಮತ್ತು ಸ್ಥಳಗಳ ಪಟ್ಟಿಗಳಂತಹ ಈವೆಂಟ್ ಮಾಹಿತಿ ಹೇಗೆ ಕಾಣಬೇಕೆಂದು ಸಂಪಾದಿಸಲು ವಿವಿಧ ಪಠ್ಯಪೆಟ್ಟಿಗೆಗಳನ್ನು ನೀವು ಕಾಣುವಿರಿ. ಕೆಳಗಿನ ಪ್ಲೇಸ್‌ಹೋಲ್ಡರ್‌ಗಳನ್ನು ಬಳಸಿ, ಯಾವ ಮಾಹಿತಿಯನ್ನು ಪ್ರದರ್ಶಿಸಬೇಕೆಂದು ನೀವು ಆರಿಸಬಹುದು.','In the boxes below, you are expected to write the page IDs. For multiple pages, use comma-separated values e.g. 1,2,3. Entering 0 means EVERY page, -1 means the home page.'=>'ಕೆಳಗಿನ ಬಾಕ್ಸ್‌ಗಳಲ್ಲಿ, ನೀವು ಪುಟದ ID ಗಳನ್ನು ಬರೆಯಬೇಕು. ಹಲವು ಪುಟಗಳಿಗೆ, 1,2,3 ಎಂದು ಅಲ್ಪವಿರಾಮದಿಂದ ಬೇರ್ಪಡಿಸಿದ ಮೌಲ್ಯಗಳನ್ನು ಬಳಸಿ. 0 ನಮೂದಿಸಿದರೆ ಪ್ರತಿ ಪುಟ ಎಂದರ್ಥ, -1 ಎಂದರೆ ಮುಖಪುಟ.','In this case, a user can confirm their own booking even if the booking is pending.'=>'ಈ ಸಂದರ್ಭದಲ್ಲಿ, ಬುಕಿಂಗ್ ಬಾಕಿಯಿದ್ದರೂ ಬಳಕೆದಾರರು ತಮ್ಮ ಬುಕಿಂಗ್ ಅನ್ನು ತಾವೇ ದೃಢೀಕರಿಸಬಹುದು.','Include %s'=>'%s ಸೇರಿಸಿ','Include Countries'=>'ರಾಷ್ಟ್ರಗಳನ್ನು ಸೇರಿಸಿ','Include all'=>'ಎಲ್ಲವನ್ನೂ ಸೇರಿಸಿ','Include cancelled events?'=>'ರದ್ದಾದ ಈವೆಂಟ್‌ಗಳನ್ನು ಸೇರಿಸುವುದೇ?','Include in WordPress Searches?'=>'WordPress ಹುಡುಕಾಟಗಳಲ್ಲಿ ಸೇರಿಸುವುದೇ?','Include on'=>'ಇವುಗಳಲ್ಲಿ ಸೇರಿಸಿ','Include only guest submissions'=>'ಅತಿಥಿ ಸಲ್ಲಿಕೆಗಳನ್ನು ಮಾತ್ರ ಸೇರಿಸಿ','Include only these %1$s IDs, for multiple values separate by commas such as %2$s.'=>'ಈ %1$s ಐಡಿಗಳನ್ನು ಮಾತ್ರ ಸೇರಿಸಿ; ಹಲವು ಮೌಲ್ಯಗಳಿಗೆ %2$s ನಂತೆ ಅಲ್ಪವಿರಾಮದಿಂದ ಬೇರ್ಪಡಿಸಿ.','Include pages where you use shortcode or PHP to display event submission forms.'=>'ಈವೆಂಟ್ ಸಲ್ಲಿಕೆ ಫಾರ್ಮ್‌ಗಳನ್ನು ಪ್ರದರ್ಶಿಸಲು ನೀವು ಶಾರ್ಟ್‌ಕೋಡ್ ಅಥವಾ PHP ಬಳಸುವ ಪುಟಗಳನ್ನು ಸೇರಿಸಿ.','Include pages where you use shortcodes or widgets to display event search forms.'=>'ಈವೆಂಟ್ ಹುಡುಕಾಟ ಫಾರ್ಮ್‌ಗಳನ್ನು ಪ್ರದರ್ಶಿಸಲು ನೀವು ಶಾರ್ಟ್‌ಕೋಡ್‌ಗಳು ಅಥವಾ ವಿಜೆಟ್‌ಗಳನ್ನು ಬಳಸುವ ಪುಟಗಳನ್ನು ಸೇರಿಸಿ.','Include past events'=>'ಹಿಂದಿನ ಈವೆಂಟ್‌ಗಳನ್ನು ಸೇರಿಸಿ','Included in %s'=>'%s ನಲ್ಲಿ ಸೇರಿಸಲಾಗಿದೆ','Included with your %s'=>'ನಿಮ್ಮ %s ನೊಂದಿಗೆ ಸೇರಿಸಲಾಗಿದೆ','Includes hybrid events, which can also be attended physically.'=>'ಭೌತಿಕವಾಗಿಯೂ ಹಾಜರಾಗಬಹುದಾದ ಹೈಬ್ರಿಡ್ ಈವೆಂಟ್‌ಗಳನ್ನು ಒಳಗೊಂಡಿದೆ.','Incomplete Bookings'=>'ಅಪೂರ್ಣ ಬುಕಿಂಗ್‌ಗಳು','Individual Components'=>'ಪ್ರತ್ಯೇಕ ಘಟಕಗಳು','Individual tickets with remaining spaces will not be available if total booking spaces reach this limit. Leave blank for no limit.'=>'ಒಟ್ಟು ಬುಕಿಂಗ್ ಸ್ಥಾನಗಳು ಈ ಮಿತಿಯನ್ನು ತಲುಪಿದರೆ, ಉಳಿದ ಸ್ಥಾನಗಳಿರುವ ವೈಯಕ್ತಿಕ ಟಿಕೆಟ್‌ಗಳು ಲಭ್ಯವಿರುವುದಿಲ್ಲ. ಮಿತಿ ಬೇಡವಾದರೆ ಖಾಲಿ ಬಿಡಿ.','Inherit your theme settings'=>'ನಿಮ್ಮ ಥೀಮ್ ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಪಡೆದುಕೊಳ್ಳಿ','Initial lengths'=>'ಆರಂಭಿಕ ಉದ್ದಗಳು','Inline'=>'ಇನ್‌ಲೈನ್','Insert the address of the notification sender.'=>'ಅಧಿಸೂಚನೆ ಕಳುಹಿಸುವವರ ವಿಳಾಸವನ್ನು ನಮೂದಿಸಿ.','Insert the display name of the notification sender.'=>'ಅಧಿಸೂಚನೆ ಕಳುಹಿಸುವವರ ಪ್ರದರ್ಶನ ಹೆಸರನ್ನು ನಮೂದಿಸಿ.','Insert the password to be used to access your SMTP server'=>'ನಿಮ್ಮ SMTP ಸರ್ವರ್ ಅನ್ನು ಪ್ರವೇಶಿಸಲು ಬಳಸಬೇಕಾದ ಗುಪ್ತಪದವನ್ನು ನಮೂದಿಸಿ','Insert the username to be used to access your SMTP server.'=>'ನಿಮ್ಮ SMTP ಸರ್ವರ್ ಅನ್ನು ಪ್ರವೇಶಿಸಲು ಬಳಸಬೇಕಾದ ಬಳಕೆದಾರರ ಹೆಸರನ್ನು ನಮೂದಿಸಿ.','Install'=>'ಇನ್‌ಸ್ಟಾಲ್ ಮಾಡಿ','Installed'=>'ಇನ್‌ಸ್ಟಾಲ್ ಮಾಡಲಾಗಿದೆ','Installed, not active'=>'ಇನ್‌ಸ್ಟಾಲ್ ಮಾಡಲಾಗಿದೆ, ಸಕ್ರಿಯವಾಗಿಲ್ಲ','Invalid Number'=>'ಅಮಾನ್ಯ ಸಂಖ್ಯೆ','Invalid file upload.'=>'ಅಮಾನ್ಯ ಫೈಲ್ ಅಪ್‌ಲೋಡ್.','Invalid interval format for %s'=>'%s ಗಾಗಿ ಅಮಾನ್ಯ ಅಂತರದ ಸ್ವರೂಪ','Invalid request'=>'ಅಮಾನ್ಯ ವಿನಂತಿ','Invalid source URL.'=>'ಅಮಾನ್ಯ ಮೂಲ URL.','Involid token credentials, the folloiwng are missing: %s.'=>'ಟೋಕನ್ ರುಜುವಾತುಗಳು ಅಮಾನ್ಯವಾಗಿವೆ, ಈ ಕೆಳಗಿನವು ಕಾಣೆಯಾಗಿವೆ: %s.','Is consent required?'=>'ಒಪ್ಪಿಗೆ ಅಗತ್ಯವೇ?','It looks like you have WPML enabled on your site. We advise you also install our extra <a href="%s">Events Manager WPML Connector</a> plugin which helps the two work better together. <a href="%s">Dismiss message</a>'=>'ನಿಮ್ಮ ಸೈಟ್‌ನಲ್ಲಿ WPML ಸಕ್ರಿಯವಾಗಿರುವಂತೆ ತೋರುತ್ತಿದೆ. ಎರಡೂ ಉತ್ತಮವಾಗಿ ಒಟ್ಟಿಗೆ ಕೆಲಸ ಮಾಡಲು ಸಹಾಯ ಮಾಡುವ ನಮ್ಮ ಹೆಚ್ಚುವರಿ <a href="%s">Events Manager WPML Connector</a> ಪ್ಲಗಿನ್ ಅನ್ನೂ ಸ್ಥಾಪಿಸಲು ನಾವು ಸಲಹೆ ನೀಡುತ್ತೇವೆ. <a href="%s">ಸಂದೇಶವನ್ನು ವಜಾಮಾಡಿ</a>','JavaScript Files'=>'JavaScript ಫೈಲ್‌ಗಳು','Join'=>'ಸೇರಿ','Join online'=>'ಆನ್‌ಲೈನ್‌ನಲ್ಲಿ ಸೇರಿ','Keep The Events Calendar\'s web addresses for events, venues, organizers, categories and tags'=>'ಈವೆಂಟ್‌ಗಳು, ಸ್ಥಳಗಳು, ಆಯೋಜಕರು, ವರ್ಗಗಳು ಮತ್ತು ಟ್ಯಾಗ್‌ಗಳಿಗೆ The Events Calendar ನ ವೆಬ್ ವಿಳಾಸಗಳನ್ನು ಉಳಿಸಿಕೊಳ್ಳಿ','Keep your current settings, or individuall revert to default formats.'=>'ನಿಮ್ಮ ಪ್ರಸ್ತುತ ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಇರಿಸಿಕೊಳ್ಳಿ, ಅಥವಾ ಪ್ರತ್ಯೇಕವಾಗಿ ಡೀಫಾಲ್ಟ್ ಫಾರ್ಮ್ಯಾಟ್‌ಗಳಿಗೆ ಹಿಂತಿರುಗಿ.','Kilometers'=>'ಕಿಲೋಮೀಟರ್‌ಗಳು','Label'=>'ಲೇಬಲ್','Labels'=>'ಲೇಬಲ್‌ಗಳು','Language Booked'=>'ಬುಕ್ ಮಾಡಿದ ಭಾಷೆ','Large'=>'ದೊಡ್ಡದಾದ','Last %d Months'=>'ಕಳೆದ %d ತಿಂಗಳುಗಳು','Last Month'=>'ಕಳೆದ ತಿಂಗಳು','Last Name'=>'ಕೊನೆಯ ಹೆಸರು','Last Year'=>'ಕಳೆದ ವರ್ಷ','Last checked via %1$s on %2$s.'=>'ಕೊನೆಯದಾಗಿ %1$s ಮೂಲಕ %2$s ರಂದು ಪರಿಶೀಲಿಸಲಾಗಿದೆ.','Last page'=>'ಕೊನೆಯ ಪುಟ','Last sync failed: %s'=>'ಕೊನೆಯ ಸಿಂಕ್ ವಿಫಲವಾಯಿತು: %s','Latitude'=>'ಅಕ್ಷಾಂಶ','Learn More'=>'ಇನ್ನಷ್ಟು ತಿಳಿಯಿರಿ','Learn more'=>'ಇನ್ನಷ್ಟು ತಿಳಿಯಿರಿ','Leave blank for default archetype setting.'=>'ಡೀಫಾಲ್ಟ್ ಆರ್ಕಿಟೈಪ್ ಸೆಟ್ಟಿಂಗ್‌ಗಾಗಿ ಖಾಲಿ ಬಿಡಿ.','Leave blank for no limit.'=>'ಮಿತಿ ಬೇಡವಾದರೆ ಖಾಲಿ ಬಿಡಿ.','Leave blank to use the built-in default for your site\'s language.'=>'ನಿಮ್ಮ ತಾಣದ ಭಾಷೆಗೆ ಅಂತರ್ನಿರ್ಮಿತ ಡೀಫಾಲ್ಟ್ ಬಳಸಲು ಖಾಲಿ ಬಿಡಿ.','Leave blank to use the default format from Settings.'=>'ಸೆಟ್ಟಿಂಗ್‌ಗಳ ಡೀಫಾಲ್ಟ್ ಫಾರ್ಮ್ಯಾಟ್ ಬಳಸಲು ಖಾಲಿ ಬಿಡಿ.','Leave either blank for no upper/lower limit.'=>'ಮೇಲಿನ/ಕೆಳಗಿನ ಮಿತಿ ಬೇಡವಾದರೆ ಯಾವುದನ್ನಾದರೂ ಖಾಲಿ ಬಿಡಿ.','Leave this field empty'=>'ಈ ಕ್ಷೇತ್ರವನ್ನು ಖಾಲಿ ಬಿಡಿ','License expired'=>'ಪರವಾನಗಿ ಅವಧಿ ಮುಗಿದಿದೆ','License not activated'=>'ಪರವಾನಗಿ ಸಕ್ರಿಯಗೊಳಿಸಲಾಗಿಲ್ಲ','Licensed'=>'ಪರವಾನಗಿ ಹೊಂದಿದೆ','Limit JS file loading?'=>'JS ಫೈಲ್ ಲೋಡ್ ಮಾಡುವುದನ್ನು ಮಿತಿಗೊಳಿಸುವುದೇ?','Limit loading of our CSS files?'=>'ನಮ್ಮ CSS ಫೈಲ್‌ಗಳ ಲೋಡ್ ಅನ್ನು ಮಿತಿಗೊಳಿಸುವುದೇ?','Limits the number of events on each calendar day. Leave blank for no limit.'=>'ಪ್ರತಿ ದಿನಸೂಚಿ ದಿನದ ಈವೆಂಟ್‌ಗಳ ಸಂಖ್ಯೆಯನ್ನು ಮಿತಿಗೊಳಿಸುತ್ತದೆ. ಮಿತಿ ಬೇಡವೆಂದಿದ್ದರೆ ಖಾಲಿ ಬಿಡಿ.','Limits the number of future events shown (0 = unlimited).'=>'ತೋರಿಸುವ ಮುಂಬರುವ ಈವೆಂಟ್‌ಗಳ ಸಂಖ್ಯೆಯನ್ನು ಮಿತಿಗೊಳಿಸುತ್ತದೆ (0 = ಮಿತಿಯಿಲ್ಲ).','Line Graph'=>'ಲೈನ್ ಗ್ರಾಫ್','Link'=>'ಲಿಂಕ್','Link Text'=>'ಕೊಂಡಿ ಪಠ್ಯ','Link directly to event on day with single event?'=>'ಒಂದೇ ಈವೆಂಟ್ ಇರುವ ದಿನದಂದು ಈವೆಂಟ್‌ಗೆ ನೇರವಾಗಿ ಲಿಂಕ್ ಮಾಡಬೇಕೇ?','Link sub-site %s directly to sub-site?'=>'ಉಪ-ಸೈಟ್ %s ಅನ್ನು ನೇರವಾಗಿ ಉಪ-ಸೈಟ್‌ಗೆ ಲಿಂಕ್ ಮಾಡುವುದೇ?','Link text used for link to user bookings.'=>'ಬಳಕೆದಾರರ ಬುಕಿಂಗ್‌ಗಳಿಗೆ ಲಿಂಕ್‌ಗಾಗಿ ಬಳಸುವ ಲಿಂಕ್ ಪಠ್ಯ.','List'=>'ಪಟ್ಟಿ','List %s'=>'%s ಪಟ್ಟಿ ಮಾಡಿ','List Limits'=>'ಪಟ್ಟಿಯ ಮಿತಿಗಳು','List bookings'=>'ಬುಕಿಂಗ್‌ಗಳನ್ನು ಪಟ್ಟಿ ಮಾಡಿ','List event tickets'=>'ಈವೆಂಟ್ ಟಿಕೆಟ್‌ಗಳನ್ನು ಪಟ್ಟಿ ಮಾಡಿ','List events'=>'ಈವೆಂಟ್‌ಗಳನ್ನು ಪಟ್ಟಿ ಮಾಡಿ','List events by date title'=>'ದಿನಾಂಕದ ಪ್ರಕಾರ ಈವೆಂಟ್‌ಗಳ ಪಟ್ಟಿಯ ಶೀರ್ಷಿಕೆ','List footer format'=>'ಪಟ್ಟಿ ಅಡಿಟಿಪ್ಪಣಿ ಫಾರ್ಮ್ಯಾಟ್','List header format'=>'ಪಟ್ಟಿ ಶೀರ್ಷಿಕೆ ಫಾರ್ಮ್ಯಾಟ್','List item footer format'=>'ಪಟ್ಟಿ ಐಟಂ ಅಡಿಟಿಪ್ಪಣಿ ಫಾರ್ಮ್ಯಾಟ್','List item format'=>'ಪಟ್ಟಿ ಐಟಂ ನಮೂನೆ','List item header format'=>'ಪಟ್ಟಿ ಐಟಂ ಶೀರ್ಷಿಕೆ ಫಾರ್ಮ್ಯಾಟ್','List location countries'=>'ಸ್ಥಳದ ರಾಷ್ಟ್ರಗಳನ್ನು ಪಟ್ಟಿ ಮಾಡಿ','List location regions'=>'ಸ್ಥಳದ ಪ್ರದೇಶಗಳನ್ನು ಪಟ್ಟಿ ಮಾಡಿ','List location states'=>'ಸ್ಥಳದ ರಾಜ್ಯಗಳನ್ನು ಪಟ್ಟಿ ಮಾಡಿ','List location towns'=>'ಸ್ಥಳದ ಪಟ್ಟಣಗಳನ್ನು ಪಟ್ಟಿ ಮಾಡಿ','List locations'=>'ಸ್ಥಳಗಳನ್ನು ಪಟ್ಟಿ ಮಾಡಿ','Load minified %s files?'=>'ಮಿನಿಫೈ ಮಾಡಿದ %s ಫೈಲ್‌ಗಳನ್ನು ಲೋಡ್ ಮಾಡುವುದೇ?','Load minified/compressed files, reducing the file size, load times and bandwidth usage on your site.'=>'ಮಿನಿಫೈ/ಸಂಕುಚಿತ ಫೈಲ್‌ಗಳನ್ನು ಲೋಡ್ ಮಾಡಿ, ಇದು ನಿಮ್ಮ ಸೈಟ್‌ನ ಫೈಲ್ ಗಾತ್ರ, ಲೋಡ್ ಸಮಯ ಮತ್ತು ಬ್ಯಾಂಡ್‌ವಿಡ್ತ್ ಬಳಕೆಯನ್ನು ಕಡಿಮೆ ಮಾಡುತ್ತದೆ.','Loading Map....'=>'ನಕ್ಷೆ ಲೋಡ್ ಆಗುತ್ತಿದೆ....','Loading...'=>'ಲೋಡ್ ಆಗುತ್ತಿದೆ...','Loads our own JS file if no other dependencies are already loaded, which is still needed for many items generated by EM using JavaScript such as Calendars, Maps and Booking Forms/Buttons'=>'ಬೇರೆ ಯಾವುದೇ ಅವಲಂಬನೆಗಳು ಈಗಾಗಲೇ ಲೋಡ್ ಆಗದಿದ್ದರೆ ನಮ್ಮದೇ JS ಫೈಲ್ ಅನ್ನು ಲೋಡ್ ಮಾಡುತ್ತದೆ, ಕ್ಯಾಲೆಂಡರ್‌ಗಳು, ನಕ್ಷೆಗಳು ಮತ್ತು ಬುಕಿಂಗ್ ಫಾರ್ಮ್‌ಗಳು/ಬಟನ್‌ಗಳಂತೆ JavaScript ಬಳಸಿ EM ರಚಿಸುವ ಹಲವು ಐಟಂಗಳಿಗೆ ಇದು ಈಗಲೂ ಅಗತ್ಯ','Location'=>'ಸ್ಥಳ','Location ID.'=>'ಸ್ಥಳ ID.','Location Image'=>'ಸ್ಥಳ ಚಿತ್ರ','Location Name'=>'ಸ್ಥಳದ ಹೆಸರು','Location Related Placeholders'=>'ಸ್ಥಳ ಸಂಬಂಧಿತ ಪ್ಲೇಸ್‌ಹೋಲ್ಡರ್‌ಗಳು','Location Submission Forms'=>'ಸ್ಥಳ ಸಲ್ಲಿಕೆ ಫಾರ್ಮ್‌ಗಳು','Location Type'=>'ಸ್ಥಳದ ಬಗೆ','Location Types'=>'ಸ್ಥಳದ ಬಗೆಗಳು','Location balloon format'=>'ಸ್ಥಳದ ಬಲೂನ್ ನಮೂನೆ','Location coordinates'=>'ಸ್ಥಳದ ನಿರ್ದೇಶಾಂಕಗಳು','Location could not be deleted.'=>'ಸ್ಥಳವನ್ನು ಅಳಿಸಲಾಗಲಿಲ್ಲ.','Location could not be saved.'=>'ಸ್ಥಳವನ್ನು ಉಳಿಸಲಾಗಲಿಲ್ಲ.','Location data is invalid.'=>'ಸ್ಥಳದ ಡೇಟಾ ಅಮಾನ್ಯವಾಗಿದೆ.','Location map and coordinates have been updated. Please re-save your location to update the map.'=>'ಸ್ಥಳದ ನಕ್ಷೆ ಮತ್ತು ನಿರ್ದೇಶಾಂಕಗಳನ್ನು ಪರಿಷ್ಕರಿಸಲಾಗಿದೆ. ನಕ್ಷೆಯನ್ನು ಪರಿಷ್ಕರಿಸಲು ದಯವಿಟ್ಟು ನಿಮ್ಮ ಸ್ಥಳವನ್ನು ಮತ್ತೆ ಉಳಿಸಿ.','Location name'=>'ಸ್ಥಳದ ಹೆಸರು','Location name and address'=>'ಸ್ಥಳದ ಹೆಸರು ಮತ್ತು ವಿಳಾಸ','Location not found'=>'ಸ್ಥಳ ಸಿಗಲಿಲ್ಲ','Location not found, so the uploaded image was not set as its featured image.'=>'ಸ್ಥಳ ಕಂಡುಬಂದಿಲ್ಲ, ಆದ್ದರಿಂದ ಅಪ್‌ಲೋಡ್ ಮಾಡಿದ ಚಿತ್ರವನ್ನು ಅದರ ವೈಶಿಷ್ಟ್ಯಗೊಳಿಸಿದ ಚಿತ್ರವಾಗಿ ಹೊಂದಿಸಲಾಗಿಲ್ಲ.','Location not found.'=>'ಸ್ಥಳ ಕಂಡುಬಂದಿಲ್ಲ.','Location pages'=>'ಸ್ಥಳದ ಪುಟಗಳು','Locations'=>'ಸ್ಥಳಗಳು','Locations imported from CSV files'=>'CSV ಫೈಲ್‌ಗಳಿಂದ ಆಮದು ಮಾಡಿದ ಸ್ಥಳಗಳು','Locations list page'=>'ಸ್ಥಳಗಳ ಪಟ್ಟಿ ಪುಟ','Locations list settings'=>'ಸ್ಥಳಗಳ ಪಟ್ಟಿ ಸೆಟ್ಟಿಂಗ್‌ಗಳು','Locations on main blog?'=>'ಮುಖ್ಯ ಬ್ಲಾಗ್‌ನಲ್ಲಿ ಸ್ಥಳಗಳು?','Locations submitted by guest users are not included, unless they are linked to events also submitted by them.'=>'ಅತಿಥಿ ಬಳಕೆದಾರರು ಸಲ್ಲಿಸಿದ ಸ್ಥಳಗಳನ್ನು, ಅವರೇ ಸಲ್ಲಿಸಿದ ಈವೆಂಟ್‌ಗಳಿಗೆ ಲಿಂಕ್ ಆಗಿರದ ಹೊರತು, ಸೇರಿಸಲಾಗುವುದಿಲ್ಲ.','Log'=>'ಲಾಗ್','Log In'=>'ಲಾಗ್ ಇನ್','Log in if you already have an account with us.'=>'ನಿಮಗೆ ಈಗಾಗಲೇ ನಮ್ಮೊಂದಿಗೆ ಖಾತೆ ಇದ್ದರೆ ಲಾಗ್ ಇನ್ ಮಾಡಿ.','Logged In Users'=>'ಲಾಗ್ ಇನ್ ಆದ ಬಳಕೆದಾರರು','Longitude'=>'ರೇಖಾಂಶ','Looking for the rest of the FullCalendar Options? They\'ve moved <a href="%s">here</a>, the options below are for overriding specific bits relevant to Events Manager.'=>'FullCalendar ನ ಉಳಿದ ಆಯ್ಕೆಗಳನ್ನು ಹುಡುಕುತ್ತಿದ್ದೀರಾ? ಅವು <a href="%s">ಇಲ್ಲಿಗೆ</a> ಸರಿದಿವೆ, ಕೆಳಗಿನ ಆಯ್ಕೆಗಳು Events Manager ಗೆ ಸಂಬಂಧಿಸಿದ ನಿರ್ದಿಷ್ಟ ಭಾಗಗಳನ್ನು ಮೀರಿಸಲು ಇವೆ.','Lost your password?'=>'ನಿಮ್ಮ ಗುಪ್ತಪದ ಕಳೆದುಹೋಯಿತೇ?','Mail sending method'=>'ಮೇಲ್ ಕಳುಹಿಸುವ ವಿಧಾನ','Main Search Fields'=>'ಮುಖ್ಯ ಹುಡುಕಾಟ ಕ್ಷೇತ್ರಗಳು','Main recurrence set %s are required.'=>'ಮುಖ್ಯ ಪುನರಾವರ್ತನೆ ಗುಂಪಿನ %s ಅಗತ್ಯವಿದೆ.','Make this the default view.'=>'ಇದನ್ನು ಡೀಫಾಲ್ಟ್ ವೀಕ್ಷಣೆಯನ್ನಾಗಿ ಮಾಡಿ.','Makes Events Manager translatable with WPML, including tickets, location addresses, booking forms and email templates. Supports recurring events and multisite. Requires WPML.'=>'ಟಿಕೆಟ್‌ಗಳು, ಸ್ಥಳದ ವಿಳಾಸಗಳು, ಬುಕಿಂಗ್ ಫಾರ್ಮ್‌ಗಳು ಮತ್ತು ಇಮೇಲ್ ಟೆಂಪ್ಲೇಟ್‌ಗಳು ಸೇರಿದಂತೆ Events Manager ಅನ್ನು WPML ನೊಂದಿಗೆ ಅನುವಾದಿಸಲು ಸಾಧ್ಯವಾಗಿಸುತ್ತದೆ. ಪುನರಾವರ್ತಿತ ಈವೆಂಟ್‌ಗಳು ಮತ್ತು multisite ಅನ್ನು ಬೆಂಬಲಿಸುತ್ತದೆ. WPML ಅಗತ್ಯವಿದೆ.','Manage %s Bookings'=>'%s ಬುಕಿಂಗ್‌ಗಳನ್ನು ನಿರ್ವಹಿಸಿ','Manage Person\'s Booking'=>'ವ್ಯಕ್ತಿಯ ಬುಕಿಂಗ್ ನಿರ್ವಹಿಸಿ','Manage booking: %s'=>'ಬುಕಿಂಗ್ ನಿರ್ವಹಿಸಿ: %s','Manage bookings'=>'ಬುಕಿಂಗ್‌ಗಳನ್ನು ನಿರ್ವಹಿಸಿ','Manage bookings link text'=>'ಬುಕಿಂಗ್‌ಗಳ ನಿರ್ವಹಣಾ ಲಿಂಕ್ ಪಠ್ಯ','Manage events, bookings, locations, tickets and other related features.'=>'ಈವೆಂಟ್‌ಗಳು, ಬುಕಿಂಗ್‌ಗಳು, ಸ್ಥಳಗಳು, ಟಿಕೆಟ್‌ಗಳು ಮತ್ತು ಇತರ ಸಂಬಂಧಿತ ವೈಶಿಷ್ಟ್ಯಗಳನ್ನು ನಿರ್ವಹಿಸಿ.','Manage in your account'=>'ನಿಮ್ಮ ಖಾತೆಯಲ್ಲಿ ನಿರ್ವಹಿಸಿ','Manage licenses'=>'ಪರವಾನಗಿಗಳನ್ನು ನಿರ್ವಹಿಸಿ','Manage my bookings'=>'ನನ್ನ ಬುಕಿಂಗ್‌ಗಳನ್ನು ನಿರ್ವಹಿಸಿ','Many themes display extra meta information on post pages such as \'posted by\' or \'post date\' information, which may not be desired. Usually, page templates contain less clutter.'=>'ಹಲವು ಥೀಮ್‌ಗಳು \'ಪೋಸ್ಟ್ ಮಾಡಿದವರು\' ಅಥವಾ \'ಪೋಸ್ಟ್ ದಿನಾಂಕ\' ಮಾಹಿತಿಯಂತಹ ಹೆಚ್ಚುವರಿ ಮೆಟಾ ಮಾಹಿತಿಯನ್ನು ಪೋಸ್ಟ್ ಪುಟಗಳಲ್ಲಿ ಪ್ರದರ್ಶಿಸುತ್ತವೆ, ಅದು ಅಪೇಕ್ಷಣೀಯವಲ್ಲದಿರಬಹುದು. ಸಾಮಾನ್ಯವಾಗಿ, ಪುಟ ಟೆಂಪ್ಲೇಟ್‌ಗಳಲ್ಲಿ ಅಸ್ತವ್ಯಸ್ತತೆ ಕಡಿಮೆ ಇರುತ್ತದೆ.','Map'=>'ನಕ್ಷೆ','Map Unavailable'=>'ನಕ್ಷೆ ಲಭ್ಯವಿಲ್ಲ','Maps'=>'ನಕ್ಷೆಗಳು','Match the needed columns, then update the preview.'=>'ಅಗತ್ಯವಿರುವ ಕಾಲಮ್‌ಗಳನ್ನು ಹೊಂದಿಸಿ, ನಂತರ ಪೂರ್ವವೀಕ್ಷಣೆಯನ್ನು ಅಪ್‌ಡೇಟ್ ಮಾಡಿ.','Max'=>'ಗರಿಷ್ಠ','Max events shown per calendar day (0 = no limit).'=>'ಪ್ರತಿ ಕ್ಯಾಲೆಂಡರ್ ದಿನದಲ್ಲಿ ತೋರಿಸುವ ಗರಿಷ್ಠ ಈವೆಂಟ್‌ಗಳು (0 = ಮಿತಿಯಿಲ್ಲ).','Max events shown per calendar day (0 = no limit; blank = site default).'=>'ಪ್ರತಿ ಕ್ಯಾಲೆಂಡರ್ ದಿನದಲ್ಲಿ ತೋರಿಸುವ ಗರಿಷ್ಠ ಈವೆಂಟ್‌ಗಳು (0 = ಮಿತಿಯಿಲ್ಲ; ಖಾಲಿ = ತಾಣದ ಡೀಫಾಲ್ಟ್).','Maximum File Size'=>'ಗರಿಷ್ಠ ಕಡತ ಗಾತ್ರ','Maximum Files Per Upload'=>'ಪ್ರತಿ ಅಪ್‌ಲೋಡ್‌ಗೆ ಗರಿಷ್ಠ ಕಡತಗಳು','Maximum Height (px)'=>'ಗರಿಷ್ಠ ಎತ್ತರ (px)','Maximum Spaces Per Booking'=>'ಪ್ರತಿ ಬುಕಿಂಗ್‌ಗೆ ಗರಿಷ್ಠ ಸ್ಥಾನಗಳು','Maximum Width (px)'=>'ಗರಿಷ್ಠ ಅಗಲ (px)','Maximum number of upcoming timeslots to show on initial page load. Enter 0 to show all upcoming timeslots.'=>'ಮೊದಲ ಪುಟ ಲೋಡ್‌ನಲ್ಲಿ ತೋರಿಸಬೇಕಾದ ಮುಂಬರುವ ಸಮಯ ಸ್ಲಾಟ್‌ಗಳ ಗರಿಷ್ಠ ಸಂಖ್ಯೆ. ಎಲ್ಲಾ ಮುಂಬರುವ ಸಮಯ ಸ್ಲಾಟ್‌ಗಳನ್ನು ತೋರಿಸಲು 0 ನಮೂದಿಸಿ.','Maximum of %d files are allowed.'=>'ಗರಿಷ್ಠ %d ಫೈಲ್‌ಗಳಿಗೆ ಮಾತ್ರ ಅನುಮತಿ ಇದೆ.','Maximum size (bytes)'=>'ಗರಿಷ್ಠ ಗಾತ್ರ (ಬೈಟ್‌ಗಳು)','Maximum spaces per booking'=>'ಪ್ರತಿ ಬುಕಿಂಗ್‌ಗೆ ಗರಿಷ್ಠ ಸ್ಥಾನಗಳು','Maybe'=>'ಬಹುಶಃ','Maybe Attending'=>'ಹಾಜರಾಗಬಹುದು','Medium'=>'ಮದ್ಯಮ','Metric'=>'ಮೆಟ್ರಿಕ್','Metrics'=>'ಮೆಟ್ರಿಕ್‌ಗಳು','Migrate'=>'ವರ್ಗಾಯಿಸಿ','Migrate Formats'=>'ಫಾರ್ಮ್ಯಾಟ್‌ಗಳನ್ನು ವಲಸೆ ಮಾಡಿ','Migrate from %s'=>'%s ನಿಂದ ವರ್ಗಾಯಿಸಿ','Migrate tickets, RSVPs and attendees'=>'ಟಿಕೆಟ್‌ಗಳು, RSVPಗಳು ಮತ್ತು ಹಾಜರಾತಿದಾರರನ್ನು ವರ್ಗಾಯಿಸಿ','Migrate to Events Manager'=>'Events Manager ಗೆ ವರ್ಗಾಯಿಸಿ','Miles'=>'ಮೈಲುಗಳು','Min'=>'ಕನಿಷ್ಠ','Min/Max'=>'ಕನಿಷ್ಠ/ಗರಿಷ್ಠ','Minimum Height (px)'=>'ಕನಿಷ್ಠ ಎತ್ತರ (px)','Minimum Width (px)'=>'ಕನಿಷ್ಠ ಅಗಲ (px)','Minutes'=>'ನಿಮಿಷಗಳು','Minutes before the event'=>'ಈವೆಂಟ್‌ಗೆ ಮೊದಲು ನಿಮಿಷಗಳು','Missing fields: '=>'ಕಾಣೆಯಾದ ಕ್ಷೇತ್ರಗಳು: ','Missing required field: %s'=>'ಅಗತ್ಯ ಕ್ಷೇತ್ರ ಕಾಣೆಯಾಗಿದೆ: %s','Mobile App Notifications'=>'ಮೊಬೈಲ್ ಆ್ಯಪ್ ಅಧಿಸೂಚನೆಗಳು','Modal'=>'ಮೋಡಲ್','Modal Popup'=>'ಮೋಡಲ್ ಪಾಪ್‌ಅಪ್','Modifications to %s can be applied to all recurrences and will overwrite any changes made to those individual %s recurrences.'=>'%s ಗೆ ಮಾಡುವ ಮಾರ್ಪಾಡುಗಳನ್ನು ಎಲ್ಲಾ ಪುನರಾವರ್ತನೆಗಳಿಗೆ ಅನ್ವಯಿಸಬಹುದು ಮತ್ತು ಆ ಪ್ರತ್ಯೇಕ %s ಪುನರಾವರ್ತನೆಗಳಲ್ಲಿ ಮಾಡಿದ ಯಾವುದೇ ಬದಲಾವಣೆಗಳನ್ನು ಅದು ಮೇಲ್ಬರಹ ಮಾಡುತ್ತದೆ.','Modifications to event tickets will cause all bookings to individual recurrences of this event to be deleted.'=>'ಈವೆಂಟ್ ಟಿಕೆಟ್‌ಗಳಿಗೆ ಮಾಡುವ ಮಾರ್ಪಾಡುಗಳು ಈ ಈವೆಂಟ್‌ನ ಪ್ರತ್ಯೇಕ ಪುನರಾವರ್ತನೆಗಳ ಎಲ್ಲಾ ಬುಕಿಂಗ್‌ಗಳನ್ನು ಅಳಿಸಲು ಕಾರಣವಾಗುತ್ತವೆ.','Modifications to repeating events will be applied to all recurrences and will overwrite any changes made to those individual event recurrences.'=>'ಪುನರಾವರ್ತಿತ ಈವೆಂಟ್‌ಗಳಿಗೆ ಮಾಡುವ ಮಾರ್ಪಾಡುಗಳನ್ನು ಎಲ್ಲಾ ಪುನರಾವರ್ತನೆಗಳಿಗೆ ಅನ್ವಯಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ಆ ಪ್ರತ್ಯೇಕ ಈವೆಂಟ್ ಪುನರಾವರ್ತನೆಗಳಲ್ಲಿ ಮಾಡಿದ ಯಾವುದೇ ಬದಲಾವಣೆಗಳನ್ನು ಅದು ಮೇಲ್ಬರಹ ಮಾಡುತ್ತದೆ.','Modified unavailable dates.'=>'ಲಭ್ಯವಿಲ್ಲದ ದಿನಾಂಕಗಳನ್ನು ಮಾರ್ಪಡಿಸಲಾಗಿದೆ.','Modify Booking'=>'ಬುಕಿಂಗ್ ಮಾರ್ಪಡಿಸಿ','Modify Recurring Event Tickets '=>'ಪುನರಾವರ್ತಿತ ಈವೆಂಟ್ ಟಿಕೆಟ್‌ಗಳನ್ನು ಮಾರ್ಪಡಿಸಿ ','Modify Unavailable Dates?'=>'ಲಭ್ಯವಿಲ್ಲದ ದಿನಾಂಕಗಳನ್ನು ಮಾರ್ಪಡಿಸಬೇಕೇ?','Modify what information is displayed in this booking table.'=>'ಈ ಬುಕಿಂಗ್ ಕೋಷ್ಟಕದಲ್ಲಿ ಯಾವ ಮಾಹಿತಿಯನ್ನು ಪ್ರದರ್ಶಿಸಬೇಕೆಂದು ಮಾರ್ಪಡಿಸಿ.','Month first: 03/04/2027 is March 4'=>'ತಿಂಗಳು ಮೊದಲು: 03/04/2027 ಎಂದರೆ March 4','Month format'=>'ತಿಂಗಳ ನಮೂನೆ','Monthly'=>'ಮಾಸಿಕ','More Events message'=>'ಹೆಚ್ಚಿನ ಈವೆಂಟ್‌ಗಳ ಸಂದೇಶ','More Info'=>'ಹೆಚ್ಚಿನ ಮಾಹಿತಿ','More information about migrating to v6 can be found %s.'=>'V6 ಗೆ ವಲಸೆ ಹೋಗುವ ಬಗ್ಗೆ ಹೆಚ್ಚಿನ ಮಾಹಿತಿ %s ನಲ್ಲಿ ಸಿಗುತ್ತದೆ.','Most of an event held at once (%)'=>'ಒಂದೇ ಬಾರಿಗೆ ಹಿಡಿದಿಡಬಹುದಾದ ಈವೆಂಟ್‌ನ ಗರಿಷ್ಠ ಭಾಗ (%)','Moving from %s?'=>'%s ನಿಂದ ಬದಲಾಯಿಸುತ್ತಿದ್ದೀರಾ?','Multi Line'=>'ಬಹು ಸಾಲುಗಳು','Multi Site Options'=>'ಮಲ್